var MINGCI_DATA = [{"s":"运动训练学","chapters":[{"t":"第一章 竞技体育与运动训练（导言）","items":[{"q":"运动训练","a":"运动训练是竞技体育活动的重要组成部分，是为了提高运动员的竟技能力和运动成绩， 而专门组织的有计划的体育活动","c":"s","b":""},{"q":"运动员选材","a":"就是挑选具有良好运动天赋及竞技潜力的儿童少年或后备力量参加运动训练。选材时， 应注意考虑各个运动项目的特点，力求使用科学的测试和预测方法，努力提高选材的成功率","c":"s","b":""},{"q":"运动竞赛","a":"是在裁判员主持下，按统一的规则要求组织与实施的运动员个体或运动队之间的竞技较 量。竞赛是竞技体育与社会发生关系，并作用于社会的媒介","c":"s","b":""},{"q":"运动员","a":"运动员是运动训练活动的主体，是运动训练负荷的承载者和运动训练成果的表现者。运 动训练的一切活动都是围绕着运动员竞技能力的发展，围绕着运动员机体的生物学改造与心 理学建设而设计、组织和实施的","c":"s","b":""},{"q":"运动训练学","a":"运动训练学是研究运动训练规律以及有效组织运动训练活动行为的科学。本源性、综合 性和实践性是运动训练学的主要学科特征","c":"s","b":""},{"q":"一般训练理论","a":"一般训练理论是普适性的训练理论，研究与阐释适用于所有运动项目的共同规律以及训 练活动的操作行为，为运动训练活动的参与者提供基本的原理性的理论知识","c":"s","b":""},{"q":"项群训练理论","a":"一组具有相似竞技特征及训练要求的竞技项目称为一个项群，项群训练理论就是揭示不 同项群竞技规律与训练规律的理论。项群训练理论是一般训练理论与专项训练理论之间的一 个理论层次。 8.专项训练理论p12 人们在体育活动实践中，逐渐形成了一些规范的活动方式，每一个运动项目都是人们从 事体育活动的一种特定方式。专项训练理论即指研究运动专项训练活动规律及组织操作行为 的训练理论。专项，系指特定的运动项目","c":"s","b":""},{"q":"运动成绩","a":"运动员参加比赛的结果”,是“根据特定的评定行为对运动员及其对手的竞技能力在比 赛中发挥状况及竞技结果的综合评定\"。这一评定既包括竟赛的胜负或名次，也包括运动员 在比赛中表现出来的竞技水平","c":"s","b":""},{"q":"比赛名次","a":"比赛名次是运动成绩的一个重要组成部分。不论哪一个运动项目，比赛结束时都必须要 分出名次。在许多情况下，比赛名次的意义甚至超过运动员所表现出来的竞技水平的价值","c":"s","b":""},{"q":"竞技水平","a":"运动员所具备的竞技能力在比赛中的表现称作竞技水平。不同项目运动员在比赛中表现 出来的竞技水平也有着不同的衡量标准，比赛结果的评价方法也不相同","c":"s","b":""},{"q":"竞技能力","a":"竞技能力即指运动员的参赛能力，是运动员参加比赛的主观条件或自身才能，由具有不 同表现形式和不同作用的体能、技能、战术能力、心理能力以及知识能力所构成，并综合地 表现于专项竞技的过程之中","c":"s","b":""},{"q":"竟技能力结构模型","a":"是依据运动员竞技能力各组成要素之间相互联系、相互作用方式的具体特性与功能建立 的反映竞技能力构成共性的模型，是对运动员竟技能力结构的概括、归纳或抽象","c":"s","b":""},{"q":"运动训练负荷","a":"运动训练负荷是指在运动训练活动中，各种练习施加于运动员机体生理的和心理的训练 刺激。运动训练负荷蕴含于不同目的、不同形式的体育练习之中","c":"s","b":""},{"q":"运动训练过程","a":"是运动训练活动在时间维度上的表现，是运动训练活动进行的步骤和程序。认识运动训 练过程的特征，对于准确把握运动训练活动的客观规律，制订科学的运动训练计划，提高运 动训练活动的效益，有着重要的意义","c":"s","b":""},{"q":"运动训练计划","a":"运动训练计划是在运动训练过程开始之前对训练活动预先做出的一种理论设计，是建立 在状态诊断的基础之上，为实现训练目标而选择的状态转移通路。","c":"s","b":""}]},{"t":"第二章 运动训练的辩证协同原则","items":[{"q":"运动训练原则","a":"人们在运动训练活动中所遵循的基本准则即称为运动训练原则。运动训练原则对于运动 训练活动的方式方法予以指导和规范，告诉人们在运动训练活动中应该如何思考，如何操作， 才能够取得理想的训练效果","c":"s","b":""},{"q":"运动训练规律","a":"运动训练规律是指运动训练系统内部各构成因素之间，以及它们与系统外部各相关因素 之间在结构与功能上的本质联系和发展的必然趋势","c":"s","b":""},{"q":"竞技能力构成规律","a":"竞技能力的构成规律是指竞技能力的构成要素以及诸因素之间的本质联系。竞技能力即 指运动员的参赛能力，是运动员参加比赛的主观条件或自身才能，是影响运动员参赛结果诸 因素中的主观因素","c":"s","b":""},{"q":"运动员竞技能力变化规律","a":"人体运动竞技能力的变化规律是指内外各种相关因素对人体运动竞技能力的因应性影 响，以及这些因素之间的相互联系","c":"s","b":""},{"q":"运动员竞技能力表现规律","a":"运动员按照专门制定的竞技规则，在比赛中展示的竞技水平与比赛名次称为竞技表现","c":"s","b":""},{"q":"三从一大训练原则","a":"即“从严、从难、从实战出发、大运动量训练”的简称，是中国体育事业理论与实践经 验的科学总结，其运用促进了中国体育事业的迅速发展，对中国体育事业的振兴与发展具有 极其重要的意义。","c":"s","b":""}]},{"t":"第三章 运动员竞技能力及其训练（上）·体能","items":[{"q":"体能","a":"体能是以人体三大供能系统的能量代谢活动为基础，通过骨骼肌系统表现出来的基本运 动能力，是运动员竞技能力的重要构成因素","c":"s","b":""},{"q":"体能训练","a":"体能训练是运动训练的重要内容。不同项目的运动员对能量代谢、神经、肌肉、骨骼等 系统的功能都有着特定的要求，在运动训练过程中，都力求运用各种有效的训练方法和手段， 改造运动员的身体形态，提高有机体的机能水平，增进健康和发展运动素质","c":"s","b":""},{"q":"力量素质","a":"力量素质是指人体肌肉工作时克服阻力的能力。人体运动时，会受到各种外力、内力的 阻碍，这就需要依靠人体的肌肉收缩产生力量，克服各种阻力，完成预定的体育活动","c":"s","b":""},{"q":"最大力量","a":"最大力量是指人体肌肉在随意收缩中所能表现出来的最大的力的能力。其力值只有在抵 抗超过肌肉最大能力的阻力过程中才能准确地测到","c":"s","b":""},{"q":"快速力量","a":"快速力量是指肌肉在尽可能短的时间内发挥出尽可能大的力量的能力。快速力量是运动 速度和力量的综合表现形式","c":"s","b":""},{"q":"力量耐力","a":"力量耐力是指运动员在静力性工作中长时间保持相应强度的肌肉紧张，或在动力性工作 中多次完成相应强度的肌肉收缩的能力","c":"s","b":""},{"q":"速度素质","a":"速度素质是指人体快速运动的能力，也指人体或人体某一部分快速移动、快速完成动作 和对外界信号快速做出运动反应的能力","c":"s","b":""},{"q":"反应速度","a":"反应速度是指人体对各种信号刺激快速应答的能力。反映这种应答能力的指标主要为 “反应时”","c":"s","b":""},{"q":"动作速度","a":"动作速度是指人体完成单个或成套动作的速度，是技术动作不可缺少的要素","c":"s","b":""},{"q":"移动速度","a":"移动速度是指在运动中.单位时间里运动员身体快速移动的能力","c":"s","b":""},{"q":"耐力素质","a":"耐力素质是指有机体在较长的时间内，保持特定强度负荷或动作质量的能力，是人体基 本的运动素质之一","c":"s","b":""},{"q":"一般耐力","a":"一般耐力是运动员有机体各器官系统机能的综合，是在不同项目中表现出专项耐力的基 础","c":"s","b":""},{"q":"专项耐力","a":"专项耐力是运动员为了获取专项成绩而最大限度动员机体的机能能力以克服专项负荷 所产生的疲劳的能力。运动员在专项训练和比赛中都要表现出这种能力","c":"s","b":""},{"q":"协调素质","a":"协调素质是指运动员机体不同系统、不同部位、不同器官协同配合完成技术动作的能力， 协调能力是形成运动技术的重要基础","c":"s","b":""},{"q":"柔韧素质","a":"柔韧素质是指人体关节活动幅度的大小以及跨过关节的韧带、肌腱、肌肉、皮肤及其他 组织的弹性和伸展的能力","c":"s","b":""},{"q":"灵敏素质","a":"灵敏素质是指在变换条件的情况下，运动员能够迅速、准确、协调地改变身体运动的空 间位置和运动方向的能力","c":"s","b":""}]},{"t":"第四章 运动员竞技能力及其训练（下）·技战术、心理与知识","items":[{"q":"运动技术","a":"运动技术即完成体育动作的方法，是运动员竞技能力水平的重要决定因素。参加不同体 育项目的活动，需完成不同的动作，即需要学习和掌握不同的技术。","c":"s","b":""},{"q":"运动战术","a":"运动战术指在比赛中为战胜对手或为表现出期望的比赛结果而采取的计谋和行动","c":"s","b":""},{"q":"赛前隐蔽","a":"赛前隐蔽是有意识地隐藏(不让对方了解)本方真实情况的战术行为，以求达到在比赛中 争得主动、出奇制胜的战术目的","c":"s","b":""},{"q":"战术能力","a":"战术能力指运动员(队)掌握和运用战术的能力，是运动员(队)整体竞技能力水平的重要 构成部分","c":"s","b":""},{"q":"心理能力","a":"运动员心理能力即指运动员与训练竞赛有关的个性心理特征，以及依训练竞赛的需要把 握和调整心理过程的能力，是运动员竞技能力的重要组成部分","c":"s","b":""},{"q":"知识能力","a":"运动员知识能力是运动员竞技能力的重要组成部分。它是指运动员掌握和运用运动知识 提高竞技运动水平的能力。掌握运动知识是运用运动知识的前提，运用运动知识，提高竞技 运动水平是掌握运动知识的目的。","c":"s","b":""}]},{"t":"第五章 运动训练方法及其应用","items":[{"q":"运动训练方法","a":"运动训练方法是指在运动训练活动中，为提高竞技运动水平、实现科学训练目的、完成 运动训练任务所采取的途径和办法的总称","c":"s","b":""},{"q":"模式训练法","a":"模式训练法是一种依靠训练信息指标从宏观上控制运动训练过程的训练方法","c":"s","b":""},{"q":"程序训练法","a":"程序训练法是一种依靠训练内容系统和严格的逻辑顺序控制运动训练过程的方法","c":"s","b":""},{"q":"微机辅训法","a":"微机辅训法是一种依靠微机技术实施控制的训练方法，亦称CAD。是现代运动训练控 制原理与现代科学技术高度结合而创造出来的具有高科技特点的训练控制方法","c":"s","b":""},{"q":"分解训练法","a":"分解训练法是指将完整的技术动作或战术配合过程合理地分成若干个环节或部分，分别 进行训练的方法","c":"s","b":""},{"q":"完整训练法","a":"完整训练法是指从技术动作或战术配合的开始到结束，不分部分和环节，完整地进行练 习的训练方法","c":"s","b":""},{"q":"重复训练法","a":"重复训练法是指多次重复同一练习，两次(组)练习之间安排相对充分休息的练习方法","c":"s","b":""},{"q":"间歇训练法","a":"间歇训练法是指对练习过程中次间、组间间歇时间做出严格规定，使机体处于不完全恢 复状态下，反复进行训练的练习方法","c":"s","b":""},{"q":"持续训练法","a":"持续训练法是指负荷强度较低、负荷时间较长、无间断连续进行训练的方法","c":"s","b":""},{"q":"变换训练法","a":"变换训练法是指一种对运动负荷、练习内容、练习形式及其条件实施变换，以提高运动 员积极性、趣味性、适应性及应变能力的训练方法","c":"s","b":""},{"q":"循环训练法","a":"循环训练法是指根据训练的具体任务，将若干练习手段设置为相应的若干个练习站(点), 运动员按照既定顺序和路线，依次完成每站(点)练习任务的训练方法","c":"s","b":""},{"q":"比赛训练法","a":"比赛训练法是指在近似、模拟或真实、严格的比赛条件下，按照比赛的规则和方式，以 提高训练质量为目的的训练方法","c":"s","b":""},{"q":"运动训练手段","a":"运动训练手段是指在运动训练过程中，为提高某种竞技运动能力、恢复某种运动器官功 能、改善某种运动技能、完成某种具体训练任务所采用的身体练习，是构成现代运动训练方 法的重要组成因素。","c":"s","b":""}]},{"t":"第六章 运动训练负荷及其设计与安排","items":[{"q":"运动负荷","a":"是指运动者在体育教学、健身锻炼、竞技运动等活动中，在一定时间里完成的活动及其 承受的运动量度","c":"s","b":""},{"q":"竞技负荷","a":"是指运动员、教练员等为了实现训练与参赛的目标与任务，在一定时间内完成的竞技活 动及其量度","c":"s","b":""},{"q":"训练负荷","a":"训练负荷是培养、发展运动员竞技能力时运动员在一定时间里完成和承受的训练量度","c":"s","b":""},{"q":"比赛负荷","a":"比赛负荷是运动员为了创造运动成绩.表现竞技能力时在一定时间里完成和承受的比赛 量度","c":"s","b":""},{"q":"训练负荷监控","a":"对运动训练活动及其成效进行的检查、评价和调控称为运动训练监控。可通过训练负荷 监控，辅助教练员评价训练效果，并为训练计划的临时性调整和未来训练计划的制订与修订 提供参考和依据。","c":"s","b":""}]},{"t":"第七章 运动训练过程与训练计划","items":[{"q":"多年训练","a":"运动员持续两年以上的训练即可称为多年训练。在此基础上。又可以分为两个层次，即 全程性多年训练和区间性多年训练","c":"s","b":""},{"q":"全程性多年训练过程","a":"全程性多年训练过程是指运动员从开始参加竞技训练，经过系统的训练培养达到个人的 竞技高峰，直到最终退役的整个发展过程","c":"s","b":""},{"q":"区间性多年训练过程","a":"是指全程性多年训练过程中具有特定任务的、阶段性的多年训练过程，一般会持续2~6 年的时间","c":"s","b":""},{"q":"单周期","a":"全年训练按照一个完整的大周期组织实施，称为“单周期”,主要适用于马拉松、长距 离竞走、越野滑雪等需要较长时间才能完成的项目以及冬季项目等受气候条件限制较大的项 目","c":"s","b":""},{"q":"双周期","a":"在传统的竞赛体系安排中，有些项目在一个年度里会安排两次重要的比赛或者两个重要 的比赛阶段，运动员的训练也相应地按照两个大周期来设计和实施，称为“双周期安排\"","c":"s","b":""},{"q":"多周期","a":"一年里出现三个或者三个以上的大周期，称为多周期安排","c":"s","b":""},{"q":"板块训练","a":"“板块”训练理念的核心在于对运动员关键身体能力的集中刺激与深度发展，强调竞技 训练的集中效应。训练过程根据运动员能力发展的适应性变化来安排，通过训练课的重点刺 激实现运动员机体适应性水平的提高，由此实现竞技能力的持续发展","c":"s","b":""}]}]},{"s":"运动生理学","chapters":[{"t":"第一章 运动生理学导论","items":[{"q":"新陈代谢","a":"生物体作为一个开放系统，与外界环境不断进行着物质与能量交换，从而完成自我更新的过程，称为新陈代谢。","c":"4","b":"第四版"},{"q":"合成代谢","a":"机体通过消耗能量合成自身需要的物质的过程，称为合成代谢。","c":"4","b":"第四版"},{"q":"分解代谢","a":"机体分解自身中可利用的成分，包括从食物中获得的营养物质，并释放能量的过程，称为分解代谢。","c":"4","b":"第四版"},{"q":"兴奋性","a":"当生物体所处外界条件变化时，机体能够感受到并相应地改变其活动的能力，称为兴奋性，组成机体的细胞、组织及完整的机体都具有这种特性。","c":"4","b":"第四版"},{"q":"刺激","a":"能被机体、组织或细胞感受到，并且能引起其反应的这些变化，称为刺激。","c":"4","b":"第四版"},{"q":"反应","a":"刺激引起机体、组织或细胞产生的活动变化被称为反应。","c":"4","b":"第四版"},{"q":"适应性","a":"在外界环境变换过程中，机体为了维持自身内部环境的稳定，保持生命活动正常运行，而调节自身各部分机能及相互关系的能力，称为适应性，包括行为适应和生理适应。","c":"4","b":"第四版"},{"q":"行为适应","a":"行为适应是通过躯体的活动来适应改变，如遇到攻击时会出现躲避动作。","c":"4","b":"第四版"},{"q":"生理适应","a":"生理适应是身体内部各器官协调的反应，如世居高原的人，为了适应缺氧的环境，机体内红细胞数量和血红蛋白含量均会提高。","c":"4","b":"第四版"},{"q":"生殖","a":"生殖是指个体生长发育到一定阶段后能够产生与自身相似的子代个体，是生命体延续的基础。","c":"4","b":"第四版"},{"q":"体液","a":"人体内的液体统称为体液，包含大量的水及溶解在水中的无机盐和有机物等，约占体重的60%。","c":"4","b":"第四版"},{"q":"细胞内液","a":"一部分体液存在于细胞内，称为细胞内液。","c":"4","b":"第四版"},{"q":"细胞外液","a":"一部分体液存在于细胞外，包括各组织细胞间隙中的组织液和血液中的血浆等，统称为细胞外液。","c":"4","b":"第四版"},{"q":"内环境","a":"细胞外液是体内细胞生存的直接环境，又称为内环境。","c":"4","b":"第四版"},{"q":"内环境稳态","a":"机体内存在一系列复杂的调控机制，可以使内环境的理化性质在一定范围内保持相对动态平衡的状态，生理学家把正常机体在神经、体液等调节作用下，通过各个器官、系统的协调活动，共同维持内环境相对稳定的状态，称为内环境稳态。","c":"4","b":"第四版"},{"q":"神经调节","a":"神经调节是人体最重要的调节方式之一，其基本方式是反射。","c":"4","b":"第四版"},{"q":"反射","a":"反射是指机体通过神经系统对内、外环境的各种刺激产生的应答性反应。","c":"4","b":"第四版"},{"q":"反射弧","a":"实现反射的结构基础是反射弧，反射弧由感受器、传入神经、神经中枢、传出神经和效应器5个部分组成。例如，当手触碰温度较高的物体时，皮肤内的温度感受器。","c":"4","b":"第四版"},{"q":"体液调节","a":"体液调节是指内分泌腺体或细胞产生的特殊化学物质通过体液运输到全身各处，对机体的新陈代谢、生长、发育和生殖等生理功能进行调节。","c":"4","b":"第四版"},{"q":"自身调节","a":"自身调节是指不依赖于神经或体液调节的情况下，有些组织、细胞自身也能对周围环境变化产生适应性反应，这种反应是组织细胞本身的生理特性。","c":"4","b":"第四版"},{"q":"运动生理学","a":"运动生理学属于人体生理学的一个分支学科，主要研究人体对运动或身体活动的反应与适应。运动生理学是体育学科中非常重要的基础科学，也是体育学科中的核心理论课程，还是体育学各专业课程的前置课程。","c":"4","b":"第四版"},{"q":"稳态","a":"内环境理化性质不是绝对静止不变的，而是各种物质在不断交换、转变中达到相对平衡 状态，即动态平衡状态，这种平衡状态称为稳态","c":"o","b":"原题库补充 #72"},{"q":"前馈","a":"在调控系统中，干扰信息可以直接通过受控装置作用于控制部分，引起输出效应发生变 化，具有前瞻性的调节特点，称为前馈","c":"o","b":"原题库补充 #77"},{"q":"可兴奋组织","a":"神经、肌肉和腺体等组织受刺激后，能迅速地产生可传布的动作电位，即发生兴奋，这 些组织被称为可兴奋组织","c":"o","b":"原题库补充 #333"},{"q":"应激性","a":"机体或一切活体组织对周围环境变化具有发生反应的能力或特性称为应激性","c":"o","b":"原题库补充 #334"},{"q":"非自动控制系统","a":"在控制系统中，控制部分不受受控部分的影响，即受控部分不能通过反馈活动改变控制 部分的活动，这种控制系统称为非自动控制系统","c":"o","b":"原题库补充 #338"},{"q":"反馈控制系统","a":"在控制系统中，控制部分不断受受控部分的影响，即受控部分不断有反馈信息返回输入 给控制部分，并改变它的活动，这种控制系统称为反馈控制系统.","c":"o","b":"原题库补充 #339"},{"q":"负反馈","a":"在人体生理功能调节的自动控制系统中，如果受控部分的反馈信息能减弱控制部分活动， 这样的反馈称为负反馈","c":"o","b":"原题库补充 #340"},{"q":"正反馈","a":"与负反馈相反，如果反馈信息能促进或加强控制部分活动，这种反馈称为正反馈","c":"o","b":"原题库补充 #341"},{"q":"前馈控制系统","a":"在调控系统中，有时干扰信息在作用于受控部分引起输出效应发生变化的同时，还可以 通过感受装置直接作用于控制部分。这种干扰信息对控制部分的直接作用称为前馈。","c":"o","b":"原题库补充 #342"}]},{"t":"第二章 细胞的基本功能","items":[{"q":"细胞质膜/细胞膜","a":"细胞质膜又称为细胞膜，主要由脂质、蛋白质和糖类构成。","c":"4","b":"第四版"},{"q":"被动转运","a":"被动转运是指物质顺电一化学梯度、不消耗能量的跨膜转运过程。","c":"4","b":"第四版"},{"q":"单纯扩散","a":"单纯扩散是指非极性脂溶性的小分子物质顺浓度差通过细胞质膜的扩散过程。","c":"4","b":"第四版"},{"q":"易化扩散","a":"易化扩散是指非脂溶性的小分子物质或带电前离子在膜蛋白的介导下顺浓度梯度和（或）电位梯度进行的跨膜转运，这一过程包括经载体介导的易化扩散和经通道介导的易化扩散。","c":"4","b":"第四版"},{"q":"经载体介导的易化扩散","a":"经载体介导的易化扩散是指葡萄糖、氨基酸、核苷酸等非脂溶性或脂溶性较小的小分子物质，在细胞质膜上载体蛋白的介导下，顺浓度梯度进行的跨膜转运。","c":"4","b":"第四版"},{"q":"经通道介导的易化扩散","a":"经通道介导的易化扩散是指溶液中带电荷离子借助于细胞质膜上离子通道蛋白质，顺浓度梯度或电位差的跨膜转运过程，这一过程与细胞生物电现象密切相关。","c":"4","b":"第四版"},{"q":"主动转运","a":"主动转运是细胞通过耗能将物质逆浓度梯度或电位梯度进行跨膜转运的过程，可分为原发性主动转运和继发性主动转运两类。","c":"4","b":"第四版"},{"q":"原发性主动转运","a":"原发性主动转运是细胞直接利用代谢产生的能量将物质逆浓度梯度或电位梯度进行跨膜转运的过程，如Na+-K+泵和Ca2+泵等。","c":"4","b":"第四版"},{"q":"继发性主动转运","a":"继发性主动转运为多种物质在进行逆浓度梯度或电位梯度的跨膜转运时，所需的能量不直接来自ATP的分解。","c":"4","b":"第四版"},{"q":"联合转运","a":"依靠原发性主动转运形成的某些离子的浓度梯度，即依靠存储在离子浓度梯度中的能量完成转运，这种间接利用 ATP能量的主动转运过程也称为联合转运。","c":"4","b":"第四版"},{"q":"反向转运","a":"在联合转运中，如果被转运的离子或分子都向同一方向运动，称为同向转运，反之则称为反向转运。","c":"4","b":"第四版"},{"q":"囊泡运输/批量运输","a":"大分子和颗粒物质进出细胞不能直接通过细胞质膜，而是由膜包围形成囊泡，通过膜包裹、膜融合和膜离断等一系列过程完成运输，故称为囊泡运输，这种运输可同时转运大量物质，因此也可称为批量运输。","c":"4","b":"第四版"},{"q":"胞吐","a":"胞吐是指细胞内的大分子物质以分泌囊泡的形式排出细胞的过程，如外分泌腺细胞排放酶原颗粒和黏液、内分泌腺细胞分泌激素，以及神经纤维末梢释放神经递质都属于胞吐。","c":"4","b":"第四版"},{"q":"胞吞","a":"胞吞是指细胞外大分子物质或物质团块如细菌、死亡的细胞和细胞碎片等被细胞质膜包裹后以囊泡的形式进入细胞的过程，也称为内化。","c":"4","b":"第四版"},{"q":"细胞信号转导","a":"细胞信号转导是指能够被细胞感知的信息在细胞间或者细胞内传递和转换，并产生生物学效应的过程。","c":"4","b":"第四版"},{"q":"跨膜信号转导","a":"通常所说的信号转导是指跨膜信号转导，即生物活性物质或物理信号通过受体的作用激活或抑制细胞功能的过程，同时也是信号从细胞外传入细胞内的过程。","c":"4","b":"第四版"},{"q":"受体","a":"受体是指细胞中能够识别和有选择性结合某些信号分子（也称为配体），具有接受和转导信号功能的分子，它们绝大部分是蛋白质，少数是糖脂或糖蛋白与糖脂复合物。","c":"4","b":"第四版"},{"q":"膜受体/细胞表面受体","a":"分布于细胞质膜中的受体称为膜受体或细胞表面受体。","c":"4","b":"第四版"},{"q":"胞质受体/核受体","a":"位于胞质中和核基质内的受体分别称为胞质受体和核受体。","c":"4","b":"第四版"},{"q":"细胞质","a":"细胞质是除去光学显微镜下可分辨的细胞器以外的胶状物质的总称，是能量交换、物质运输、信息传递过程的主要场所。","c":"4","b":"第四版"},{"q":"细胞骨架","a":"在细胞质基质中存在一些纤维样的三维立体结构，称为细胞骨架，其由于纤维的组装与分解而处于动态变化中。","c":"4","b":"第四版"},{"q":"细胞器","a":"细胞器是细胞中由生物膜包围起来的亚细胞结构，主要有内质网、线粒体和细胞核等，在细胞中行使特定的功能。","c":"4","b":"第四版"},{"q":"静息电位","a":"静息电位是指细胞未受到刺激时，膜内、外两侧的电位差。通常情况下，细胞同一侧表面各点电位相同，绝大多数细胞膜内、外侧存在外正内负的电位差。","c":"4","b":"第四版"},{"q":"离子通道","a":"离子通道是由跨膜蛋白质构成的通道，它们允许特定离子通过细胞膜，快速进出细胞。","c":"4","b":"第四版"},{"q":"动作电位","a":"动作电位是指处于静息电位状态的细胞接受有效刺激后产生的一个迅速的、可逆的、可向远处传播的膜电位波动。","c":"4","b":"第四版"},{"q":"阈刺激","a":"能使细胞产生动作电位的刺激称为阈刺激。","c":"4","b":"第四版"},{"q":"阈上刺激","a":"大于阈强度的刺激分别称为阈上刺激。","c":"4","b":"第四版"},{"q":"阈下刺激","a":"小于阈强度的刺激分别称为阈下刺激。","c":"4","b":"第四版"},{"q":"有效刺激","a":"所谓有效刺激，是指能使细胞产生动作电位的阈刺激或阈上刺激。","c":"4","b":"第四版"},{"q":"锋电位","a":"升支和降支共同形成尖峰状的电位变化，称为锋电位，锋电位是动作电位的主要部分，被视为动作电位的标志。","c":"4","b":"第四版"},{"q":"后电位","a":"锋电位之后膜电位的低幅、缓慢波动称为后电位。","c":"4","b":"第四版"},{"q":"后去极化电位/后超极化电位","a":"后电位包括前后两个部分，前一部分的膜电位仍高于静息电位，称为后去极化电位；后一部分低于静息电位，称为后超极化电位。","c":"4","b":"第四版"},{"q":"绝对不应期","a":"绝对不应期是指在动作电位的去极化阶段和部分复极化阶段，细胞膜上的Na+通道打开，Na+从细胞外部流入细胞内部，使得细胞内部的电位上升。","c":"4","b":"第四版"},{"q":"内向电流","a":"当正离子由膜外向膜内转运或负离子由膜内向膜外转运，可造成膜外正电荷流入膜内，这种电流称为内向电流。","c":"4","b":"第四版"},{"q":"外向电流","a":"当正离子由膜内向膜外转运时，可引起膜内正电荷流向膜外，这种电流称为外向电流。","c":"4","b":"第四版"},{"q":"静息态","a":"静息态是指通道在未受到刺激时的关闭状态；","c":"4","b":"第四版"},{"q":"激活态","a":"激活态是指通道在膜电位的去极化期间，膜电压改变导致通道激活，呈开放的状态，此时允许特定离子通过。","c":"4","b":"第四版"},{"q":"失活态","a":"离子通道的开放并不会一直持续，而是在开放后的几毫秒内关闭，在此期间虽然有去极化造成的电压改变的刺激，但是离子通道仍不能再激活，称为失活态。","c":"4","b":"第四版"},{"q":"不应期","a":"足够数量的Na+通道从失活中恢复以支持新的动作电位所需的时间，称为不应期，不应期限制了神经元的重复放电率。","c":"4","b":"第四版"},{"q":"局部电流","a":"兴奋区与邻旁未兴奋区之间将出现电位差，并产生由正电位区域流向负电位区域的电流，这种在兴奋区与邻旁未兴奋区之间的电流称为局部电流。","c":"4","b":"第四版"},{"q":"跳跃式传导","a":"在有髓神经纤维上，动作电位的传导则不同，其动作电位从一个郎飞结跳跃传导到下一个郎飞结，这种传导方式称为跳跃式传导。","c":"4","b":"第四版"},{"q":"兴奋","a":"兴奋是生物体的器官、组织或细胞受到足够强的刺激后所产生的生理功能加强的反应","c":"o","b":"原题库补充 #79"},{"q":"可兴奋细胞","a":"在机体内神经、肌肉和内分泌腺细胞在刺激作用下能够产生可传播的动作电位，因此， 这些细胞被称为可兴奋细胞","c":"o","b":"原题库补充 #81"},{"q":"阈强度","a":"固定刺激作用时间和时间-强度变化率，可引起组织兴奋的最小刺激强度，称为阈强度","c":"o","b":"原题库补充 #84"},{"q":"阈电位","a":"能够触发细胞兴奋产生动作电位的临界膜电位，称为阈电位","c":"o","b":"原题库补充 #85"},{"q":"极化状态","a":"细胞在安静状态时，膜电位处于正常数值的外正内负状态，称为极化状态","c":"o","b":"原题库补充 #86"},{"q":"去极化","a":"去极化是指膜内电位负值较静息电位时减小的过程，即极化状态减弱","c":"o","b":"原题库补充 #87"},{"q":"复极化","a":"细胞去极化后又向原来极化状态恢复的过程，称为复极化","c":"o","b":"原题库补充 #88"},{"q":"超极化","a":"膜内电位负值较静息电位时加大的过程称为超极化，即极化状态加强","c":"o","b":"原题库补充 #89"},{"q":"局部反应","a":"细胞受到阈下刺激时，在细胞膜上产生的局部去极化，其电位变化不能向远处扩布，因 此称为局部反应","c":"o","b":"原题库补充 #90"},{"q":"相对不应期","a":"经过心肌细胞的绝对不应期后，随着时间的推移，心肌的兴奋性逐渐恢复，此时给予心 肌细胞阈上刺激，则可能引起心肌再次兴奋，这段时期称为相对不应期","c":"o","b":"原题库补充 #368"},{"q":"有效不应期","a":"在绝对不应期稍长的一个时期内，细胞对阈上刺激也不能产生可传导的动作电位，这一 时期称为有效不应期","c":"o","b":"原题库补充 #369"},{"q":"超常期","a":"动作电位结束即刻的一段时程，心肌兴奋性会稍高于正常水平，在受到阈下刺激时也会 产生兴奋，此期称为超常期。之后兴奋性恢复到正常水平","c":"o","b":"原题库补充 #370"}]},{"t":"第三章 骨骼肌收缩","items":[{"q":"骨骼肌","a":"骨骼肌由肌细胞组成，肌细胞外形呈长圆柱状，又称为肌纤维，是骨骼肌的基本结构和功能单位。","c":"4","b":"第四版"},{"q":"肌纤维","a":"骨骼肌由肌细胞组成，肌细胞外形呈长圆柱状，又称为肌纤维，是骨骼肌的基本结构和功能单位。","c":"4","b":"第四版"},{"q":"明带/暗带/横纹肌","a":"在显微镜下可见每条肌原纤维全长都呈现有规则的明暗交替排列，分别称为明带（又称I 带）和暗带（又称为 A带），同时在平行排列的各肌原纤维之间，明带和暗带又分布在同一水平上，这就使肌纤维呈现横纹，故骨骼肌被称为横纹肌。","c":"4","b":"第四版"},{"q":"M 线","a":"在肌原纤维上，暗带长度比较固定，其中间有一个较透明的区域，为 H 区，H区中间有一横向暗线称为M 线。","c":"4","b":"第四版"},{"q":"Z线","a":"明带长度可变，其中央也有一条横向的暗线称为Z线。","c":"4","b":"第四版"},{"q":"肌小节","a":"每两条相邻Z 线之间的区域，包括一个位于中间部位的暗带和其两侧各1/2 的明带，称为肌小节。","c":"4","b":"第四版"},{"q":"肌管系统","a":"肌管系统指包绕在每一条肌原纤维周围的膜性囊管状结构，它们实际是由功能不同的两组独立的管道系统所组成。","c":"4","b":"第四版"},{"q":"横管系统","a":"横管系统走向和肌原纤维相垂直，又称为 T 小管，位于肌小节明带和暗带的交界处，它由肌膜向细胞内凹陷并向深部延伸而成，其走向与肌原纤维垂直，与该肌细胞在同一周径上生成的其他横管系统联通成网，包裹在每一条肌原纤维周围。","c":"4","b":"第四版"},{"q":"神经-肌肉接头","a":"躯体运动神经纤维在接近骨骼肌细胞时失去髓鞘，轴突末梢部分形成膨大并嵌入到肌细胞膜形成的凹陷中，形成神经-肌肉接头，这是实现神经纤维与骨骼肌细胞之间兴奋传递的部位。","c":"4","b":"第四版"},{"q":"兴奋-收缩耦联","a":"肌细胞兴奋过程是以细胞膜电变化为特征的，而肌细胞的收缩过程是以肌纤维机械活动为基础的，它们有着不同的生理机制，肌肉收缩时必定存在某种中介过程把它们联系起来，这一中介过程称为兴奋-收缩耦联。","c":"4","b":"第四版"},{"q":"肌丝滑行理论","a":"肌丝滑行理论认为，肌肉收缩时虽然外观上可以看到整个肌肉或肌纤维的缩短，但在肌细胞内并无肌丝或它们分子结构的缩短或卷曲，而是在每个肌小节内发生的细肌丝向粗肌丝的相对滑行。","c":"4","b":"第四版"},{"q":"横桥循环","a":"当横桥角度发生变化时，横桥头部与肌动蛋白解脱，并恢复到原来垂直的位置，紧接着横桥又开始与下一个肌动蛋白的位点结合，通过重复上述过程，即横桥循环。","c":"4","b":"第四版"},{"q":"单收缩","a":"肌肉受到单个有效刺激，引起一次收缩和舒张活动，称为单收缩，包括等张性单收缩和等长性单收缩。","c":"4","b":"第四版"},{"q":"收缩时间","a":"在等长性单收缩过程中，由刺激开始至肌张力曲线达到最大值的时间称为收缩时间。","c":"4","b":"第四版"},{"q":"收缩残余","a":"肌肉疲劳时，单收缩缩短幅度变小，放松不完全，称为收缩残余。","c":"4","b":"第四版"},{"q":"强直收缩","a":"以适当的时间间隔连续给予两个有效刺激，可以获得比单个刺激更大的肌肉收缩力或收缩幅度，这一现象称为强直收缩。","c":"4","b":"第四版"},{"q":"不完全强直收缩","a":"刺激频率较低时，每一次新的刺激所引起的肌肉收缩是在前一次肌肉收缩的舒张期基础上进行的，从而形成“有波动”的收缩，称为不完全强直收缩。","c":"4","b":"第四版"},{"q":"完全强直收缩","a":"刺激频率较高时，每一次新的刺激所引起的肌肉收缩是在前一次肌肉收缩的收缩期达到张力最大的基础上进行的，从而形成“无波动”的收缩，称为完全强直收缩。","c":"4","b":"第四版"},{"q":"临界融合频率","a":"满足强直收缩“无波动”收缩的最小刺激频率称为临界融合频率。","c":"4","b":"第四版"},{"q":"等长收缩","a":"肌肉收缩时，肌肉长度不变的收缩称为等长收缩。","c":"4","b":"第四版"},{"q":"缩短收缩","a":"肌肉收缩时，长度缩短的收缩称为缩短收缩。","c":"4","b":"第四版"},{"q":"向心收缩","a":"由于缩短收缩时肌肉的起止点相互靠近，因此又称为向心收缩。","c":"4","b":"第四版"},{"q":"等速收缩","a":"等速收缩是肌肉保持恒定收缩速度条件下进行的一种缩短收缩，这种收缩需要借助特殊的等速练习器械完成。","c":"4","b":"第四版"},{"q":"拉长收缩","a":"当肌肉收缩张力小于负荷阻力，肌肉在被动拉长的条件下收缩，称为拉长收缩。","c":"4","b":"第四版"},{"q":"离心收缩","a":"由于拉长收缩时肌肉的起止点相互远离，因此又称为离心收缩。","c":"4","b":"第四版"},{"q":"牵张-收缩循环","a":"在运动实践中，单纯的缩短收缩和拉长收缩都是不常见的，更多情况下是拉长收缩与缩短收缩联系在一起，形成所谓的牵张-收缩循环来驱动肢体的活动。","c":"4","b":"第四版"},{"q":"肌肉收缩的“负荷阻力-收缩速度曲线”","a":"将在缩短和拉长收缩条件下负荷阻力与收缩速度变化描绘在直角坐标系上，可以获得肌肉收缩的“负荷阻力-收缩速度曲线”。","c":"4","b":"第四版"},{"q":"骨骼肌收缩的“长度-张力关系曲线”","a":"将骨骼肌在不同前负荷作用下肌肉长度与肌肉张力的变化绘制下来，可以获得骨骼肌收缩的“长度-张力关系曲线”。","c":"4","b":"第四版"},{"q":"运动单位","a":"α运动神经元连同它所支配的所有骨骼肌纤维称为运动单位。","c":"4","b":"第四版"},{"q":"快运动单位","a":"大α运动神经元连同它所支配的快肌纤维或II 型肌纤维，称为快运动单位。","c":"4","b":"第四版"},{"q":"慢运动单位","a":"小α运动神经元连同它所支配的慢肌纤维或I型肌纤维，称为慢运动单位。","c":"4","b":"第四版"},{"q":"运动单位募集","a":"运动单位募集是指运动过程中不同类型运动单位参与活动的次序和程度。","c":"4","b":"第四版"},{"q":"选择性募集/顺序性募集","a":"不同类型运动单位随运动强度增加而表现出来的募集模式称为运动单位的选择性募集或顺序性募集。","c":"4","b":"第四版"},{"q":"横桥","a":"在组成粗肌丝的肌球蛋白分子球状头部，有规则地突出在M 线两侧的粗肌丝主干表面 的突起部分，称为横桥","c":"o","b":"原题库补充 #80"},{"q":"肌肉收缩蛋白","a":"在肌肉收缩和舒张过程中，与肌丝滑行有关的蛋白质，称为肌肉收缩蛋白，包括肌球蛋 白和肌动蛋白","c":"o","b":"原题库补充 #92"},{"q":"前负荷","a":"肌肉收缩之前所承受的负荷称为前负荷","c":"o","b":"原题库补充 #94"},{"q":"后负荷","a":"肌肉开始收缩后所遇到的负荷称为后负荷","c":"o","b":"原题库补充 #95"},{"q":"非等动收缩","a":"非等动收缩是指肌肉克服恒定负荷的一种收缩形式，习惯上亦称为等张收缩","c":"o","b":"原题库补充 #97"},{"q":"肌纤维类型","a":"依据骨骼肌的形态、结构和功能特征对其类别进行判别的结果，称为肌纤维类型","c":"o","b":"原题库补充 #100"},{"q":"肌肉收缩能力","a":"不依赖于前、后负荷，可影响肌肉收缩效果的肌肉内在功能状态称为肌肉收缩能力。","c":"o","b":"原题库补充 #105"},{"q":"传导","a":"动作电位一旦在细胞膜的某一点产生，就沿着细胞膜向各个方向传播，直到整个细胞膜 都产生动作电位，这种在单一细胞上动作电位的传播叫作传导","c":"o","b":"原题库补充 #344"},{"q":"运动终板","a":"神经—肌肉接头的结构又称为运动终板。运动神经的末梢发出许多细小分支，并且在终 末部分膨大","c":"o","b":"原题库补充 #345"},{"q":"亨尼曼大小原则","a":"在肌肉收缩增加过程中，运动单位的募集顺序是从最小到最大，即对应的是慢收缩运动 神经元到快收缩运动神经元，这被称为亨尼曼大小原则","c":"o","b":"原题库补充 #346"},{"q":"伸展性","a":"骨骼肌在受到外力牵拉或负重时可被拉长，这种特性称为伸展性","c":"o","b":"原题库补充 #347"},{"q":"弹性","a":"当外力或负重取消后，肌肉的长度又可恢复，这种特性称为弹性","c":"o","b":"原题库补充 #348"},{"q":"超等长收缩","a":"超等长收缩是指骨骼肌工作时先做离心式拉长，继而做向心式收缩的一种复合式收缩形 式","c":"o","b":"原题库补充 #351"},{"q":"等张收缩","a":"肌肉张力在肌肉开始缩短后即不再增加，直到收缩结束。这种收缩形式称为等张收缩, 有时也称为动力性或时相性收缩","c":"o","b":"原题库补充 #352"},{"q":"等动收缩","a":"在整个关节运动范围内，肌肉以恒定的速度，且外界的阻力与肌肉收缩时肌肉产生的力 量始终相等的肌肉收缩称为等动收缩","c":"o","b":"原题库补充 #353"},{"q":"绝对力量","a":"某一块肌肉做最大收缩时所产生的张力为该肌肉的绝对肌力。肌肉的绝对肌力和肌肉的 横断面大小有关，肌肉的横断面越大，其绝对肌力越大","c":"o","b":"原题库补充 #354"},{"q":"相对力量","a":"相对肌力是指肌肉单位横断面积(一般为1cm²肌肉横断面积)所具有的肌力。相对力量 可更好地评价运动员的力量素质","c":"o","b":"原题库补充 #355"},{"q":"兴奋—收缩脱耦联","a":"异常情况下，会出现心肌细胞有电活动但不能产生收缩的现象，称为兴奋—收缩脱耦联","c":"o","b":"原题库补充 #364"}]},{"t":"第四章 骨骼肌收缩的能量供应","items":[{"q":"能量代谢","a":"生物体内物质代谢过程中，所伴随的能量释放、转移、储存和利用称为能量代谢。","c":"4","b":"第四版"},{"q":"ATP稳态","a":"细胞、组织乃至器官、系统在能量转换过程中维持其 ATP 恒定含量的现象称为ATP稳态。","c":"4","b":"第四版"},{"q":"磷酸原系统/ATP-CP 系统","a":"由于ATP和CP 中均含高能磷酸键，因此将ATP和CP 所构成的能量供应系统称为磷酸原系统或ATP-CP系统。","c":"4","b":"第四版"},{"q":"糖酵解系统/乳酸能系统","a":"糖酵解系统是指糖原或葡萄糖在无氧分解过程中再合成 ATP 的供能系统。由于这一系统供能时生成乳酸，所以亦称之为乳酸能系统。","c":"4","b":"第四版"},{"q":"无氧供能系统","a":"由于磷酸原系统和糖酵解系统在代谢过程中都不需要氧的参与，所以这两个供能系统又合称为无氧供能系统。","c":"4","b":"第四版"},{"q":"有氧氧化系统","a":"糖类、脂肪和蛋白质在氧供充足的情况下，彻底氧化成H,O和CO，并合成ATP的供能系统，称为有氧氧化系统。","c":"4","b":"第四版"},{"q":"ATP","a":"ATP由腺嘌呤和核糖构成的腺苷与三个磷酸基团结合形成，相邻的两个磷酸基团之间的化学键非常活跃，水解时可释放约30.54kJ·mol-1的能量，因此称为高能磷酸键，用“~P“表示。","c":"4","b":"第四版"},{"q":"高能磷酸键","a":"ATP由腺嘌呤和核糖构成的腺苷与三个磷酸基团结合形成，相邻的两个磷酸基团之间的化学键非常活跃，水解时可释放约30.54kJ·mol-1的能量，因此称为高能磷酸键，用“~P“表示。","c":"4","b":"第四版"},{"q":"肌糖原","a":"储存于肌肉中的糖原称为肌糖原，肌糖原是进行高强度无氧运动时机体的能源物质，也是进行中高强度有氧运动时的主要能源。","c":"4","b":"第四版"},{"q":"肝糖原","a":"储存于肝中的糖原称为肝糖原，肝糖原可以迅速分解入血补充血糖，如长时间运动时，血糖水平下降，刺激肝糖原分解成葡萄糖释放到血液中补充葡萄糖，以维持血糖的动态平衡。","c":"4","b":"第四版"},{"q":"乳酸循环/Cori 循环","a":"肌肉中的糖类无氧酵解产生的乳酸转运到肝中，经糖异生作用转化为葡萄糖，然后回到肌肉中进行代谢利用，这一过程称为乳酸循环，也称为 Cori循环。","c":"4","b":"第四版"},{"q":"能量连续统一体","a":"不同类型的运动项目的能量供应途径之间，以及各能量系统之间相互联系形成的这种连续统一体，称为能量连续统一体。","c":"4","b":"第四版"},{"q":"食物的热价/卡价","a":"1g食物氧化时产生的热量称为食物的热价或卡价。","c":"4","b":"第四版"},{"q":"物理热价","a":"物理热价为食物在体外燃烧时释放的热量。","c":"4","b":"第四版"},{"q":"生物热价","a":"生物热价指食物在体内完全氧化时所产生的热量。","c":"4","b":"第四版"},{"q":"氧热价","a":"某种食物氧化时消耗1LO 所产生的热量，即氧热价。","c":"4","b":"第四版"},{"q":"呼吸商","a":"同一时间内机体CO 的生成量和耗氧量的比值称为呼吸商。","c":"4","b":"第四版"},{"q":"特殊动力效应","a":"在安静状态下摄入食物后，人体释放的热量比摄入的食物本身氧化后所产生的热量要多。食物能使机体“额外”消耗热量的现象称为食物的特殊动力效应。","c":"4","b":"第四版"},{"q":"基础代谢","a":"基础代谢是指人体在清晨安静状态下，不受精神紧张、肌肉活动、食物和环境温度等因素影响时的能量代谢。","c":"4","b":"第四版"},{"q":"基础代谢率","a":"单位时间内的基础代谢，称为基础代谢率，通常用每小时每平方米体表面积的产热量。","c":"4","b":"第四版"},{"q":"氧储备","a":"在正常情况下，O2 除了维持体内的代谢消耗，还储存在体内一小部分待用，该部分称 为氧储备","c":"o","b":"原题库补充 #394"},{"q":"氧利用率","a":"每100 毫升动脉血流经组织时所释放的O2 占动脉血氧含量的百分数，称为氧利用率","c":"o","b":"原题库补充 #395"},{"q":"物质代谢","a":"为了维持正常的生命活动，机体必须不断地从外界环境中摄入氧气及各种营养物质，以 构筑和更新机体自身的组织，称为同化作用；同时，机体自身的组成物质也不断分解成代谢 产物排出体外，称为异化作用。这种机体与其周围环境不断进行的物质交换过程，称为物质 代谢","c":"o","b":"原题库补充 #396"},{"q":"安静代谢率","a":"指人体安静状态下单位时间内的能量代谢。能量代谢率与体重不成比例关系，而与体表 面积成正比","c":"o","b":"原题库补充 #397"},{"q":"热价","a":"1g 食物完全氧化分解所释放出的热量称为食物的热价。食物的热价分为物理热价和生 物热价，前者指食物在体外燃烧时释放的热量，后者指食物在体内氧化时产生的热量","c":"o","b":"原题库补充 #398"},{"q":"代谢当量","a":"运动时的耗氧量与安静时耗氧量的比值称为代谢当量，又称梅脱","c":"o","b":"原题库补充 #399"},{"q":"酵解能系统","a":"酵解能系统又称为乳酸能系统，是运动中骨骼肌糖原或葡萄糖在无氧条件下酵解，生成 乳酸并释放能量供肌肉利用的能源系统","c":"o","b":"原题库补充 #402"},{"q":"氧化能系统","a":"氧化能系统又称为有氧氧化系统。糖类、脂肪和蛋白质在氧供充分时，可以彻底氧化分 解为二氧化碳和水，同时产生大量能量的过程，称为有氧氧化","c":"o","b":"原题库补充 #403"}]},{"t":"第五章 血液与运动","items":[{"q":"血量","a":"血量是指全身血液的总量。正常成年人的血量占体重的 7%~8%。包括循环血量和储存血量。","c":"4","b":"第四版"},{"q":"循环血量","a":"在安静状态下，大部分的血量都在心血管系统中迅速流动，这部分血量称为循环血量。。","c":"4","b":"第四版"},{"q":"储存血量/储血库","a":"储存血量/储血库一部分血量潴留在肝、肺、腹腔静脉及皮下静脉丛等处，其流动缓慢、血浆较少、红细胞较多，这部分血量称为储存血量，由于这些器官起到储存血液的作用，故称为储血库。","c":"4","b":"第四版"},{"q":"血浆","a":"血浆是血液的液体成分，基本成分包括水和溶解于其中的多种电解质、小分子有机化合物及一些气体。","c":"4","b":"第四版"},{"q":"血浆蛋白","a":"血浆中含有多种分子大小、结构和功能不同的蛋白质，统称为血浆蛋白，正常成年人的血浆蛋白含量为 65~80g·L-1，其中白蛋白最多，球蛋白次之，纤维蛋白最少。","c":"4","b":"第四版"},{"q":"血脂","a":"血浆中所含的游离脂肪酸、甘油三酯、磷脂、胆固醇及其酯等成分统称为血脂。","c":"4","b":"第四版"},{"q":"血浆脂蛋白","a":"由于血浆中的脂类物质不溶于水，而是与血浆中的蛋白质结合以脂蛋白的形式运输，因此称为血浆脂蛋白。","c":"4","b":"第四版"},{"q":"非蛋白质含氮化合物","a":"血液中除蛋白质以外的含氮化合物统称为非蛋白质含氮化合物，包括尿素、尿酸、肌酐、氨基酸和多肽等。","c":"4","b":"第四版"},{"q":"血糖","a":"血液中的葡萄糖称为血糖，健康成年人在空腹时血糖浓度为 3.9~6.1mmol·L-1，餐后2h为4.4~7.8mmol·L-1，血糖是机体维持稳态的重要物质。","c":"4","b":"第四版"},{"q":"低血糖症","a":"血糖过高或过低均会对机体产生一定的影响，当血糖低于2.8mmol· L-1时就会发生低血糖症。","c":"4","b":"第四版"},{"q":"运动性低血糖","a":"在空腹状态下进行长时间剧烈运动时，或在运动前进食较少、运动中补糖不足均可导致血糖浓度下降，产生运动性低血糖。","c":"4","b":"第四版"},{"q":"血细胞","a":"血细胞是血液的有形成分，包括红细胞、白细胞和血小板三类，其中红细胞的数量最多，约占血细胞总数的 99%，白细胞最少。","c":"4","b":"第四版"},{"q":"贫血","a":"如果人体外周血液中红细胞数量、血红蛋白浓度低于正常值则称为贫血。","c":"4","b":"第四版"},{"q":"红细胞可塑变形性","a":"正常红细胞在外力作用下具有变形的能力，红细胞的这种特性称为可塑变形性。","c":"4","b":"第四版"},{"q":"红细胞悬浮稳定性","a":"将盛有抗凝血的血沉管垂直静置，尽管红细胞的相对密度大于血浆，但正常时红细胞下沉缓慢，表明红细胞能相对稳定地悬浮于血浆中，红细胞的这种特性称为悬浮稳定性。","c":"4","b":"第四版"},{"q":"红细胞渗透脆性/脆性","a":"红细胞在低渗盐溶液中发生膨胀破裂的特性称为红细胞渗透脆性，简称脆性。","c":"4","b":"第四版"},{"q":"促红细胞生成素/EPO","a":"促红细胞生成素（EPO）是机体红细胞生成的主要调节物质，是促进红细胞增殖与释放的关键物质。","c":"4","b":"第四版"},{"q":"白细胞","a":"白细胞为无色、有核的细胞，在血液中一般呈球形。白细胞可分为中性粒细胞、嗜酸性粒细胞、嗜碱性粒细胞、单核细胞和淋巴细胞 5类，","c":"4","b":"第四版"},{"q":"粒细胞","a":"中性粒细胞、嗜酸性粒细胞和嗜碱性粒细胞，三者胞质中含有嗜色颗粒，总称为粒细胞。","c":"4","b":"第四版"},{"q":"白细胞渗出","a":"除淋巴细胞外，所有的白细胞都能伸出伪足做变形运动，凭借这种运动，白细胞可以从毛细血管内皮细胞的间隙挤出，进入血管周围组织内，这一过程称为白细胞渗出。","c":"4","b":"第四版"},{"q":"白细胞趋化性","a":"渗出后的白细胞也可借助变形运动在组织内游走，并且具有朝向某些化学物质发生运动的特性，称为趋化性。","c":"4","b":"第四版"},{"q":"趋化因子","a":"能吸引白细胞发生定向运动的化学物质称为趋化因子。","c":"4","b":"第四版"},{"q":"吞噬","a":"白细胞吞入并杀伤或降解病原物及组织碎片的过程称为吞噬。","c":"4","b":"第四版"},{"q":"嗜碱性细胞/肥大细胞","a":"嗜碱性细胞在结缔组织和黏膜上皮内时，称为肥大细胞，其结构和功能与嗜酸性细胞相似。","c":"4","b":"第四版"},{"q":"单核细胞","a":"单核细胞在血液中停留约1天后迁移到组织中，继续发育成为巨噬细胞，胞体增大，细胞内溶酶体和线粒体的数目增多，具有比中性粒细胞更强的吞噬能力。","c":"4","b":"第四版"},{"q":"淋巴细胞","a":"淋巴细胞在免疫应答反应过程中起核心作用，根据细胞生长发育的过程、细胞表面标志和功能的不同，可将淋巴细胞分成T细胞、B细胞和自然杀伤细胞（NK细胞）三大类。","c":"4","b":"第四版"},{"q":"血小板","a":"血小板无细胞核，呈双凸圆盘状，体积很小，直径仅为2~3pm。血小板具有黏附、释放、聚集、收缩和吸附等生理特性。","c":"4","b":"第四版"},{"q":"血小板黏附","a":"血小板与非血小板表面的黏着称为血小板黏附，当血管内皮细胞受损时血小板即可黏附于内皮下组织。","c":"4","b":"第四版"},{"q":"血小板释放","a":"当血小板受刺激后将储存在致密体、α-颗粒或溶酶体内的物质排出的现象称为血小板释放，许多由血小板释放的物质可进一步促进血小板的活化、聚集，加速止血过程。","c":"4","b":"第四版"},{"q":"血小板聚集","a":"血小板与血小板之间的相互黏着称为血小板聚集，这一过程需要纤维蛋白原、Ca2+和血小板膜上糖蛋白 GPII B/ III a的参与。","c":"4","b":"第四版"},{"q":"红细胞比容","a":"血细胞中主要是红细胞，它在全血中所占的容积百分比称为红细胞比容","c":"o","b":"原题库补充 #182"},{"q":"血型","a":"血型通常是指红细胞膜上特异抗原的类型","c":"o","b":"原题库补充 #183"},{"q":"渗透压","a":"溶液促使水分子透过膜移动的力量即称为渗透压或渗透吸水力","c":"o","b":"原题库补充 #184"},{"q":"晶体渗透压","a":"由电解质所形成的渗透压称为晶体渗透压","c":"o","b":"原题库补充 #185"},{"q":"胶体渗透压","a":"由蛋白质所形成的渗透压称为胶体渗透压","c":"o","b":"原题库补充 #186"},{"q":"碱储备","a":"碱储备。血液中缓冲酸性物质的主要成分是NaHCO₃,通常以每100mL 血浆的NaHCO₃ 含量来表示碱储备量","c":"o","b":"原题库补充 #360"},{"q":"运动性贫血","a":"由于运动训练引起的Hb 浓度、红细胞数和（或）HCT 低于正常水平的一种暂时性现象 称为运动性贫血","c":"o","b":"原题库补充 #191"},{"q":"生理性止血","a":"正常情况下，小血管受损后引起的出血在几分钟内就会自然停止，这种现象称为生理性 止血","c":"o","b":"原题库补充 #193"},{"q":"血液凝固","a":"血液凝固是指血液由流动的液体状态变成不能流动的凝胶状态的过程","c":"o","b":"原题库补充 #194"},{"q":"血液","a":"血液是一种由血浆和血细胞组成的液态组织，在心血管系统内循环流动。血细胞为血液 的有形成分，包括红细胞、白细胞和血小板","c":"o","b":"原题库补充 #357"},{"q":"血清","a":"流出体外的血液如不加抗凝剂处理，几分钟后就会凝固成胶冻血块。在室温内搁置1h 以上，血块缩小，并在血块周围出现少量黄色澄清液，称为血清","c":"o","b":"原题库补充 #358"},{"q":"血浆渗透压","a":"渗透压是一切溶液所固有的一种特性，它是由溶液中溶质分子运动造成的。水分子通过 半透膜向溶液扩散的现象称为渗透现象，简称渗透。血浆渗透压由晶体渗透压和胶体渗透压 两部分组成。由晶体物质产生的渗透压称为晶体渗透压。由胶体物质产生的渗透压称为胶体 渗透压","c":"o","b":"原题库补充 #359"}]},{"t":"第六章 呼吸与运动","items":[{"q":"呼吸","a":"机体在新陈代谢过程中，需要不断地从外界环境中摄取 O 和排出CO 机体与环2 2境之间的气体交换称为呼吸。","c":"4","b":"第四版"},{"q":"外呼吸","a":"外呼吸是指在肺部实现的外界环境与血液间的气体交换，其过程包括肺通气和肺换气。","c":"4","b":"第四版"},{"q":"气体运输","a":"气体运输是指血液中的气体在肺部和身体细胞之间的输送。","c":"4","b":"第四版"},{"q":"内呼吸/组织换气","a":"内呼吸是指组织毛细血管中血液通过组织液与组织细胞间的气体交换，也称为组织换气。","c":"4","b":"第四版"},{"q":"肺通气","a":"肺是机体与外界环境进行气体交换的部位，肺与外界环境之间所进行的气体交换过程称为肺通气。","c":"4","b":"第四版"},{"q":"呼吸运动","a":"呼吸运动是指由呼吸肌的收缩与舒张所引起的胸廓节律性扩大和缩小，包括吸气运动和呼气运动两个过程。","c":"4","b":"第四版"},{"q":"吸气肌","a":"能扩大胸廓内腔容积的肌肉称为吸气肌，主要包括隔肌和肋间外肌。","c":"4","b":"第四版"},{"q":"胸内压/胸膜腔内压","a":"胸内压又称为胸膜腔内压，是指脏层胸膜与壁层胸膜间的一个密闭腔隙（即胸膜腔）内的压力。","c":"4","b":"第四版"},{"q":"胸内负压","a":"在安静状态下呼吸（即平静呼吸）时，胸膜腔内的压力总是低于大气压，称为胸内负压。","c":"4","b":"第四版"},{"q":"憋气","a":"憋气是指吸气后紧闭声门用力呼气的过程。憋气时，可反射性地引起肌肉张力增加，为有关的运动环节创造最有效的收缩支撑条件。","c":"4","b":"第四版"},{"q":"弹性组织/弹性阻力","a":"机体具有弹性的组织称为弹性组织，弹性组织（肺和胸廓）对抗外力作用所引起的变形力，称为弹性阻力，其大小可用顺应性来度量，顺应性是指在外力作用下弹性组织的可扩张性。","c":"4","b":"第四版"},{"q":"气道阻力","a":"气道阻力是指气体流经呼吸道时气体分子之间及气体分子与气道壁之间的摩擦力，占非弹性阻力的 80%~90%。气道阻力产生于气体流动时，并随流速加快而增加，属于动态阻力。","c":"4","b":"第四版"},{"q":"肺容积","a":"肺容积是指肺内气体的容积总量，由潮气量、补吸气量、补呼气量和余气量 4部分组成。","c":"4","b":"第四版"},{"q":"潮气量","a":"潮气量是指每次呼吸吸入或呼出的气量，正常成年人为 500mL。","c":"4","b":"第四版"},{"q":"补吸气量","a":"补吸气量是指平静吸气后再做最大吸气所补充吸入的气量，正常成年人为1500~2000mL。","c":"4","b":"第四版"},{"q":"余气量","a":"余气量是最大呼气后仍残余在肺内的气量，正常成年人为 1000~1500mL。","c":"4","b":"第四版"},{"q":"肺容量","a":"肺容量是指肺容积中两项或两项以上的联合气体量。","c":"4","b":"第四版"},{"q":"深吸气量","a":"潮气量与补吸气量之和称为深吸气量，即从平静呼气之末做最大吸气时所能吸入的气量，该值是衡量最大通气潜力的重要指标。","c":"4","b":"第四版"},{"q":"功能余气量","a":"余气量与补呼气量之和称为功能余气量，即平静呼气之末尚存留于肺内的气量，可缓冲呼吸过程中肺泡气氧分压（Po ）和二氧化碳分压（Pco ）的变化幅度。2 2","c":"4","b":"第四版"},{"q":"肺活量","a":"潮气量、补吸气量与补呼气量之和称为肺活量，即最大吸气后再做最大呼气所能呼出的气量，反映的是一次通气的最大能力，是评价肺通气功能的常用指标之一。","c":"4","b":"第四版"},{"q":"用力肺活量/时间肺活量","a":"用力肺活量也称为时间肺活量，是指一次最大吸气后，以最快速度用力呼气时所能呼出的最大气体量，以第1s 的用力肺活量意义最大，称为第1s 用力呼气容积，FEV /FVC 约为83%。","c":"4","b":"第四版"},{"q":"第1s 用力呼气容积","a":"以第1s 的用力肺活量意义最大，称为第1s 用力呼气容积，FEV /FVC 约为83%。正常人在3s 内基本可呼出全部气体，肺部阻塞性疾病患者往往需要5~6s 或更长的时间。","c":"4","b":"第四版"},{"q":"肺总量","a":"肺活量与余气量之和称为肺总量，即肺所能容纳的最大气体量。","c":"4","b":"第四版"},{"q":"肺通气量","a":"肺通气量是指人体每分钟吸入或者呼出的气体总量，其值等于潮气量与每分钟呼吸频率的乘积。","c":"4","b":"第四版"},{"q":"肺泡通气量","a":"每次呼吸所吸入的气体并非都能进入肺泡进行气体交换，从气体交换的角度考虑，真正有效的通气量是肺泡通气量，即每分钟吸入肺泡的新鲜空气量，它等于潮气量减去解剖无效腔的差再乘以呼吸频率。","c":"4","b":"第四版"},{"q":"气体交换","a":"肺泡与血液之间及血液与组织细胞之间 O 和CO 的交换，称为气体交换，包括2 2肺换气和组织换气。","c":"4","b":"第四版"},{"q":"肺换气","a":"肺泡与血液之间O 和CO 的交换，称为肺换气。2 2","c":"4","b":"第四版"},{"q":"分压","a":"分压是指混合气体中各自所具有的压力，可用总压力乘以各组成气体的容积百分比求得。","c":"4","b":"第四版"},{"q":"氧合血红蛋白","a":"当血液流经Po 高的肺部时，Hb 与O 结合形成氧合血红蛋白，呈鲜红色。2 2","c":"4","b":"第四版"},{"q":"去氧血红蛋白","a":"当血液流经Po 低的组织时，HbO 迅速解离，释出O 成为去氧血红蛋白，呈暗2 2 2红色。","c":"4","b":"第四版"},{"q":"Hb 的氧容量","a":"100mL 血液中 Hb 所能结合的最大O 量称为Hb 的氧容量。","c":"4","b":"第四版"},{"q":"Hb 的氧含量","a":"100mL 血液中 Hb 实际结合的O 量称为Hb 的氧含量。","c":"4","b":"第四版"},{"q":"Hb 的氧饱和度","a":"Hb 的氧含量与氧容量的百分比称为 Hb 的氧饱和度。","c":"4","b":"第四版"},{"q":"氧解离曲线/氧合血红蛋白解离曲线","a":"氧解离曲线是表示血液 Po 与Hb 氧饱和度关系的曲线，也称为氧合血红蛋白解离曲线。","c":"4","b":"第四版"},{"q":"波尔效应","a":"氧解离曲线左移，CO 浓度的增加可降低细胞内的pH，引起红细胞内HbO 亲和2 2力下降，这一现象称为波尔效应。","c":"4","b":"第四版"},{"q":"何尔登效应","a":"O 与Hb 结合可促使CO 释放，而去氧的Hb 则容易与CO 结合，该现象称为何2 2 2尔登效应。","c":"4","b":"第四版"},{"q":"呼吸中枢","a":"在中枢神经系统内，产生和调节节律性呼吸运动的神经元群称为呼吸中枢。","c":"4","b":"第四版"},{"q":"肺扩张反射","a":"肺充气或扩张到一定程度时抑制吸气的反射，称为肺扩张反射。","c":"4","b":"第四版"},{"q":"肺萎陷反射","a":"肺萎陷到一定程度时引起吸气活动的反射称为肺萎陷反射。","c":"4","b":"第四版"},{"q":"化学感受器","a":"在颈动脉体、主动脉体和延髓腹外侧浅表部位存在着对血液或脑脊液中 CO 、H+和O 等化学物质较敏感的感受器，称为化学感受器。","c":"4","b":"第四版"},{"q":"化学感受器反射性调节","a":"这些化学因素发生变化时，通过刺激化学感受器所引起的调节，称为化学感受器反射性调节。","c":"4","b":"第四版"},{"q":"防御性反射","a":"当呼吸道受到机械性或化学性刺激时，分布于呼吸道黏膜上皮内的感受器兴奋，引起咳嗽反射、喷嚏反射等防御性反射，以清除刺激物，避免其进入肺泡。","c":"4","b":"第四版"},{"q":"氧通气当量","a":"每分通气量和每分摄氧量的比值（V /VO ）称为氧通气当量，此值小说明O 的E 2 2摄取效率高。","c":"4","b":"第四版"},{"q":"腹式呼吸","a":"膈肌舒缩时，腹部随之起伏，以膈肌活动为主的呼吸运动称为膈式呼吸或腹式呼吸","c":"o","b":"原题库补充 #201"},{"q":"胸式呼吸","a":"肋间肌的活动使肋骨发生提降移动，胸部也随之起伏，以肋间肌活动为主的呼吸运动称 为肋式呼吸或胸式呼吸","c":"o","b":"原题库补充 #202"},{"q":"每分通气量","a":"人体通过呼吸，每分钟能够进入肺泡或从肺泡中呼出的气体量，称为每分通气量","c":"o","b":"原题库补充 #207"},{"q":"通气/血流比值","a":"每分肺泡通气量和肺血流量（心输出量）的比值，称为通气/血流比值","c":"o","b":"原题库补充 #210"},{"q":"氧利用系数","a":"血液流经组织时释放出的O2 容积占动脉血氧含量的百分数称为氧利用系数","c":"o","b":"原题库补充 #212"},{"q":"氧脉搏","a":"心脏每次搏动输出血量所摄取的氧量，称为氧脉搏，可以用每分摄氧量除以每分心率计 算。氧脉搏越高，说明心肺功能越好、效率越高","c":"o","b":"原题库补充 #213"},{"q":"肺牵张反射","a":"由于肺的扩张或缩小所引起的反射性呼吸变化称为肺牵张反射","c":"o","b":"原题库补充 #214"},{"q":"呼吸肌本体感受性反射","a":"由于呼吸肌本体感受器传入冲动所引起的反射性呼吸变化，称为呼吸肌本体感受性反射。","c":"o","b":"原题库补充 #215"},{"q":"平静呼吸","a":"平静呼吸是指安静状态下的呼吸运动。其特点是：吸气时，依靠膈肌和肋间外肌的收缩， 使胸廓扩大，完成吸气过程；呼气时，通过膈肌和肋间外肌的舒张，使扩大的胸廓回位(恢 复),完成呼气过程","c":"o","b":"原题库补充 #382"},{"q":"用力呼吸","a":"用力呼吸是指吸气与呼气过程均有肌肉的收缩活动。用力吸气时，除主要的吸气肌(膈 肌和肋间外肌)加强收缩外，辅助吸气肌也参与收缩，使胸廓进一步扩大，从而增加吸气量","c":"o","b":"原题库补充 #383"},{"q":"肺内压","a":"肺泡内的压力称为肺内压。气体进出肺泡是借助肺内压与大气压之间的压差实现的","c":"o","b":"原题库补充 #384"},{"q":"补呼气量","a":"静呼气之后再做最大呼气时，增补呼出的气量称为补呼气量。正常成人为900~1200mL。 补呼气量的大小表示呼气的贮备能力","c":"o","b":"原题库补充 #388"},{"q":"肺总容量","a":"肺所能容纳的最大气量为肺总容量,是肺活量和余气量之和","c":"o","b":"原题库补充 #390"},{"q":"解剖无效腔","a":"在肺通气过程中，每次吸入的新鲜气体，有一小部分将留在鼻、咽、喉、气管和支气管 等管腔内，由于这部分管腔因其解剖特征没有气体交换的功能，其管腔内的气体就气体交换 来说是无效的，故这部分管腔称为解剖无效腔","c":"o","b":"原题库补充 #392"},{"q":"最大通气量","a":"以适宜的呼吸频率和呼吸深度进行呼吸时所测得的每分通气量，称为最大通气量或最大 随意通气量","c":"o","b":"原题库补充 #393"}]},{"t":"第七章 血液循环与运动","items":[{"q":"血液循环系统/心血管系统","a":"心脏和血管及里面流动的血液构成了机体的血液循环系统，又称为心血管系统。","c":"4","b":"第四版"},{"q":"血管","a":"血管是血液流通的管道，由动脉、毛细血管和静脉组成；","c":"4","b":"第四版"},{"q":"心脏","a":"心脏是血液流动的动力器官。","c":"4","b":"第四版"},{"q":"血液循环","a":"心脏不断跳动推动血液在心血管系统内循环流动的过程，称为血液循环。血液循环是高等动物生存的必要条件，一旦停止，生命活动则无法正常进行。","c":"4","b":"第四版"},{"q":"心肌组织","a":"心肌组织由实质成分（即心肌细胞）和间质成分（即心肌胶原、毛细血管等）组成。","c":"4","b":"第四版"},{"q":"心肌细胞","a":"心肌细胞是可兴奋性细胞，根据细胞动作电位时相中是否自动去极化，将心肌细胞分为工作细胞和自律细胞两类，心肌细胞的种类决定了心肌的生理特性。","c":"4","b":"第四版"},{"q":"自动节律性","a":"自动节律性简称为自律性，是指心肌自律细胞在无外来刺激的情况下，能自动发生节律性兴奋的特性。","c":"4","b":"第四版"},{"q":"心脏的正常起搏点","a":"不同部位的自律性高低不一，通常窦房结的自律性最高，是主导整个心脏兴奋的自律细胞，故称为心脏的正常起搏点。","c":"4","b":"第四版"},{"q":"窦性心律","a":"临床上将以窦房结为起搏点所引起的心脏节律性活动称为窦性心律。","c":"4","b":"第四版"},{"q":"异位心律","a":"以窦房结以外部位为起搏点所引起的心脏活动称为异位心律。","c":"4","b":"第四版"},{"q":"房室延搁","a":"心房肌的传播速度较快，左、右心房几乎同时收缩，在房室交界区的传导出现传导速度极慢的现象，即房室延搁。","c":"4","b":"第四版"},{"q":"全或无式收缩","a":"由于心房和心室间存在房室延搁，使得左、右心房和左、右心室先后发生同步收缩，从而保证了心脏各部分之间的协同工作，使心脏能有效地发挥其泵血功能。心肌的这种同步工作，也称“全或无式收缩”。","c":"4","b":"第四版"},{"q":"期前兴奋","a":"正常情况下，心脏根据窦房结发出的兴奋进行节律性舒缩，但在心肌正常兴奋的有效不应期结束后，如果在下一次窦房结兴奋到达前，给予窦房结一次额外刺激，可使心室提前产生一次兴奋，称为期前兴奋。","c":"4","b":"第四版"},{"q":"期前收缩/早搏","a":"正常情况下，心脏根据窦房结发出的兴奋进行节律性舒缩，但在心肌正常兴奋的有效不应期结束后，如果在下一次窦房结兴奋到达前，给予窦房结一次额外刺激，可使心室提前产生一次收缩，称为期前收缩。期前收缩又称为早搏，正常人偶发，是临床上最常见的一种心律失常。","c":"4","b":"第四版"},{"q":"代偿间歇","a":"期前兴奋也有自己的有效不应期，当紧接在期前兴奋后下一次正常窦房结兴奋传到心室时，正好落在期前兴奋的有效不应期之内，无法再引起心室兴奋和收缩，须等到下一次窦房结正常兴奋传来时才能引起心室收缩，并出现一段较长的心室舒张期，这种现象称为代偿间歇。","c":"4","b":"第四版"},{"q":"心电图","a":"将测量电极置于体表一定部位所记录的心脏电位变化波形，称为心电图。心电图反映了心脏兴奋产生、传导和恢复过程中的生物电变化，与心脏机械收缩活动具有一定对应关系。","c":"4","b":"第四版"},{"q":"心泵","a":"心脏工作形式类似于水泵，故称为心泵。","c":"4","b":"第四版"},{"q":"心脏泵血功能","a":"心脏通过心肌节律性舒缩驱动血液定向流动的作用称为心脏泵血功能。","c":"4","b":"第四版"},{"q":"心率","a":"心率是指每分钟心脏跳动的次数。成年人安静时心率为60~100次/min，平均75次/min。","c":"4","b":"第四版"},{"q":"心动过缓","a":"人体安静时心率低于60次/min称为心动过缓。","c":"4","b":"第四版"},{"q":"心动过速","a":"人体安静时心率大于100次/min称为心动过速。","c":"4","b":"第四版"},{"q":"心动周期","a":"心动周期是指心脏每收缩和舒张一次构成的机械活动周期。在心动周期中，心房和心室的机械活动均包括收缩期和舒张期。","c":"4","b":"第四版"},{"q":"心脏舒缩/心室舒缩","a":"通常的心脏舒缩主要是指心室舒缩，正常情况下左、右心室的活动保持同步，输出血量基本相同。分为等容收缩期和射血期。","c":"4","b":"第四版"},{"q":"快速射血期","a":"心室在等容收缩期时，瓣膜均关闭，心室暂时处于封闭腔状态，心室内压急剧升高，当超过主动脉压时推开主动脉瓣，心室将2/3 血液快速射入主动脉内，即为快速射血期。","c":"4","b":"第四版"},{"q":"减慢射血期","a":"随后由于心室内血液量减少和心室收缩强度减弱，加之主动脉压升高，射血阻力加大，射血速度则逐渐减慢，即为减慢射血期，之后进入心室舒张期。","c":"4","b":"第四版"},{"q":"等容舒张期","a":"从主动脉半月瓣关闭至房室瓣开启，心室肌继续舒张使室内压急剧下降而心室容积并不改变，故称为等容舒张期。","c":"4","b":"第四版"},{"q":"快速充盈期","a":"当室内压下降至低于房内压时，房室瓣开启，心室舒张期总充盈量2/3 的血液快速进入心室，心室容积迅速增大，称为快速充盈期。","c":"4","b":"第四版"},{"q":"减慢充盈期","a":"快速充盈期之后血液进入心室的速度减慢，这一时期为减慢充盈期。","c":"4","b":"第四版"},{"q":"心房收缩期","a":"在心室舒张期最后的0.1s，下一个心动周期的心房收缩期开始前，可使心室的充盈量再增加10%~30%，即进入心房收缩期。","c":"4","b":"第四版"},{"q":"搏出量/每搏输出量","a":"搏出量即每搏输出量，是指心脏的一侧心室搏动一次所射出的血量。","c":"4","b":"第四版"},{"q":"射血分数","a":"心室每次射血并未将充盈血液全部射出，把搏出量占心室舒张末期充盈量的百分比称为射血分数。射血分数反映了心室的泵血效率，能够更加准确地反映心脏的泵血功能。","c":"4","b":"第四版"},{"q":"心输出量/每分输出量","a":"心输出量即每分输出量，是指一侧心室每分钟所输出的血量，其值为搏出量与心率的乘积。","c":"4","b":"第四版"},{"q":"心指数","a":"以每平方米体表面积计算的心输出量称为心指数。心指数存在年龄差异，10 岁左右时最大，之后随年龄增长逐渐降低。","c":"4","b":"第四版"},{"q":"心力储备/心泵功能储备","a":"心力储备又称为心泵功能储备，是指心输出量随机体代谢的需要而增加的能力，包括心率储备和搏出量储备，是评价心泵功能的有效指标。","c":"4","b":"第四版"},{"q":"心率储备","a":"心率储备是指依靠增加心率来提高心输出量的能力，可通过最大心率减去安静时心率来计算。","c":"4","b":"第四版"},{"q":"搏出量储备","a":"搏出量储备包括收缩期储备和舒张期储备。","c":"4","b":"第四版"},{"q":"收缩期储备","a":"收缩期储备是指依靠增加心室收缩力使心室收缩末期容积减小的幅度。","c":"4","b":"第四版"},{"q":"舒张期储备","a":"舒张期储备是指心室舒张末期容积增加的幅度。","c":"4","b":"第四版"},{"q":"心脏前负荷","a":"心脏前负荷即容量负荷，是指心肌收缩之前所承受的负荷。心脏前负荷决定了心肌在收缩前所处的拉长状态，即初长度。","c":"4","b":"第四版"},{"q":"心脏后负荷","a":"心脏后负荷即压力负荷，是指心肌开始收缩时才遇到的负荷。对心室而言，后负荷主要为大动脉压。","c":"4","b":"第四版"},{"q":"心肌收缩力","a":"心肌收缩力是指心肌不依赖前负荷和后负荷而改变其力学性能（包括收缩强度和速度）的内在特性，是决定心脏泵血功能的主要因素。","c":"4","b":"第四版"},{"q":"心音","a":"在心动周期中，心肌收缩、瓣膜启闭、血液流动冲击瓣膜和大动脉壁引起的振动，通过周围组织传递至胸壁，使用听诊器在胸前臂左下部，可以听到振动产生的声音，即为心音。","c":"4","b":"第四版"},{"q":"弹性储器血管","a":"弹性储器血管是由主动脉、肺动脉主干及其发出的最大分支组成，其特点是管壁坚厚、富含弹性纤维、有明显的弹性和扩张性。","c":"4","b":"第四版"},{"q":"弹性储器作用","a":"当主动脉瓣关闭后，被扩张的大动脉依靠其弹性回缩，把在射血期多容纳的那部分血液继续推向外周，大动脉的这种功能称为弹性储器作用，其作用可使心脏间断的射血变成为血管系统中连续的血流，并能减少血压的波动幅度。","c":"4","b":"第四版"},{"q":"分配血管","a":"分配血管是从弹性储器血管以后到分支为小动脉前的动脉管道，主要功能是将血液运输至各器官组织，故称为分配血管。","c":"4","b":"第四版"},{"q":"阻力血管","a":"依据在毛细血管前后的分布情况，阻力血管可分为毛细血管前阻力血管和后阻力血管。","c":"4","b":"第四版"},{"q":"交换血管","a":"位于动、静脉之间的毛细血管称为交换血管。","c":"4","b":"第四版"},{"q":"毛细血管前括约肌","a":"在真毛细血管起始部环绕着一些平滑肌，称为毛细血管前括约肌，它的舒缩活动可控制毛细血管的开放和关闭，影响毛细血管开放的数量。","c":"4","b":"第四版"},{"q":"容量血管","a":"与同级动脉相比，静脉的数量多、管壁薄、口径大，可扩张性好，在血管系统中起着血液储存库的作用，安静状态下可容纳循环血量的 60%~70%，因而称为容量血管。","c":"4","b":"第四版"},{"q":"血流量","a":"血流量是指单位时间内流经血管某一截面的血量。","c":"4","b":"第四版"},{"q":"血流速度","a":"血流速度是指血液中某一质点在血管内移动的线速度。","c":"4","b":"第四版"},{"q":"血流阻力","a":"血流阻力是指血液流经血管时所遇到的阻力，主要由流动的血流与血管壁摩擦，以及血液内部分子之间的相互摩擦产生。","c":"4","b":"第四版"},{"q":"血压","a":"血压是指血管内的血液对于单位面积血管壁的侧压力，即压强，通常所说的血压是指动脉血压。","c":"4","b":"第四版"},{"q":"动脉血压","a":"血液对单位面积动脉血管壁的侧压力称为动脉血压，一般所说的动脉血压是指主动脉压。","c":"4","b":"第四版"},{"q":"收缩压","a":"在一个心动周期中，动脉血压会随着心室的收缩与舒张发生有规律的波动，心室收缩射血时，动脉血压急剧升高，在心室收缩中期达到最大，称为收缩压。","c":"4","b":"第四版"},{"q":"舒张压","a":"在一个心动周期中，动脉血压会随着心室的收缩与舒张发生有规律的波动，心室舒张时，动脉血压下降，在心舒末期降至最低，称为舒张压。","c":"4","b":"第四版"},{"q":"脉搏压/脉压","a":"收缩压与舒张压的差值称为脉搏压，简称脉压。","c":"4","b":"第四版"},{"q":"平均动脉压","a":"整个心动周期中各瞬间动脉血压的平均值，称为平均动脉压。由于心室收缩期短于舒张期，故平均动脉压更接近舒张压，约等于舒张压与 1/3脉压之和。","c":"4","b":"第四版"},{"q":"动脉脉搏/脉搏","a":"在心动周期中，动脉内压力会发生周期性波动，这种由于心脏舒缩所引起的动脉血管周期性搏动的现象，称为动脉脉搏，简称脉搏。","c":"4","b":"第四版"},{"q":"中心静脉压/外周静脉压","a":"右心房作为体循环终点，血压近乎为零，通常将右心房和胸腔内大静脉血压称为中心静脉压，将各器官静脉血压称为外周静脉压。","c":"4","b":"第四版"},{"q":"重力性休克","a":"当身体由卧位突然转为直立位时，因大量血液积聚于下肢静脉，导致回心血量大幅减少，引起脑部缺氧而发生头晕甚至晕厥的现象，称为重力性休克。","c":"4","b":"第四版"},{"q":"静脉泵/肌肉泵","a":"通过骨骼肌舒缩和静脉瓣配合，对静脉血回流起着泵样驱动作用，称为“静脉泵”或“肌肉泵”。","c":"4","b":"第四版"},{"q":"呼吸泵","a":"呼吸运动对静脉血回流起着“泵”样作用，称为“呼吸泵”。","c":"4","b":"第四版"},{"q":"微循环","a":"微循环是指微动脉和微静脉之间的血液循环。血液循环最基本的功能是通过微循环实现血液和组织液之间的物质交换。","c":"4","b":"第四版"},{"q":"有效滤过压","a":"组织液的生成与回流取决于有效滤过压。滤过的力量和重吸收的力量之差称为有效滤过压。有效滤过压（毛细血管压+组织液胶体渗透压）-（组织液静水压+血浆胶体渗透压）。","c":"4","b":"第四版"},{"q":"自主神经","a":"支配内脏、心血管和腺体等器官的神经不受意识支配，称为自主神经。自主神经包括交感神经和副交感神经。","c":"4","b":"第四版"},{"q":"交感-肾上腺系统","a":"当交感神经活动加强时，常伴有肾上腺髓质激素的分泌活动增强，因而将交感神经和肾上腺活动合称为“交感-肾上腺系统”。","c":"4","b":"第四版"},{"q":"心血管中枢","a":"心血管中枢是指与心血管活动调控有关的神经元核团集中的部位，最基本的心血管中枢位于延髓。","c":"4","b":"第四版"},{"q":"颈动脉窦压力感受器和主动脉弓压力感受器","a":"在颈动脉窦和主动脉弓的血管外膜下分布着丰富的感觉神经末梢，能感受血压变化对血管壁造成的机械牵张刺激，该结构分别称为颈动脉窦压力感受器和主动脉弓压力感受器。","c":"4","b":"第四版"},{"q":"颈动脉窦和主动脉弓的压力感受性反射","a":"压力感受性反射（又称为减压反射）是指当动脉血压突然升高时，动脉管壁被牵张的程度升高，刺激颈动脉窦和主动脉弓的压力感受器，反射性引起心率减慢、心输出量减少、血管舒张和血压下降的反射活动。","c":"4","b":"第四版"},{"q":"颈动脉体化学感受器和主动脉体化学感受器","a":"在颈总动脉分叉处和主动脉弓区分布有感受血液中化学成分细微变化的感受器，分别称为颈动脉体化学感受器和主动脉体化学感受器。","c":"4","b":"第四版"},{"q":"颈动脉体和主动脉体的化学感受性反射","a":"化学感受性反射是指当O 缺乏、CO 和H+浓度增加时，颈动脉体和主动脉体的2 2化学感受器兴奋，反射性引起呼吸加深加快，并间接引起心率加快、心输出量增加、外周血管阻力增大和血压升高的反射活动。","c":"4","b":"第四版"},{"q":"代谢性自身调节","a":"代谢性自身调节是指由于组织代谢活动增强引起局部组织的代谢产物如 CO 、H+和腺苷等增多，Po 降低，局部组织的微动脉和毛细血管前括约肌舒张，使局部组织血流量增多，代谢产物浓度随之降低并改善局部组织缺氧状况的调节效应。","c":"4","b":"第四版"},{"q":"肌源性自身调节","a":"肌源性自身调节是指当某器官的血流灌注压突然升高时，血管平滑肌受到牵拉刺激而发生紧张性收缩加强，局部器官的血流阻力增大，避免器官血流量因灌注压升高而增加的调节效应。","c":"4","b":"第四版"},{"q":"运动员的心脏","a":"运动员的心脏存在向左右两侧增大的现象，因未发现其他任何病理性变化，故将其定义为“运动员心脏”。","c":"4","b":"第四版"},{"q":"运动性心脏肥大","a":"由于长期锻炼或训练而引起以心腔扩大和心壁增厚为主要标志的心脏肥大，称为运动性心脏肥大，是运动员心脏的重要特征。","c":"4","b":"第四版"},{"q":"离心性肥大","a":"耐力性项目运动员心脏肥大主要为全心扩大伴左室壁厚度轻度增加，又称为离心性肥大。","c":"4","b":"第四版"},{"q":"向心性肥大","a":"力量性项目运动员心脏肥大以左室壁增厚为主，而左、右心室腔扩大不明显，又称为向心性肥大。","c":"4","b":"第四版"},{"q":"心脏生理性重塑","a":"存在运动性心脏肥大的心脏的心肌细胞线粒体、氧化酶、毛细血管、肌质网、心肌细胞的特殊分泌颗粒，以及神经支配等微细结构均发生适应性变化，即心脏生理性重塑。","c":"4","b":"第四版"},{"q":"运动性心动徐缓","a":"长期进行运动训练可使安静心率明显降低，这种由于运动锻炼或训练导致安静时心率明显低于正常值的现象，称为运动性心动徐缓。","c":"4","b":"第四版"},{"q":"异长自身调节","a":"异长自身调节是指与神经、体液因素无关，由于心肌初长度改变而导致搏出量改变的一 种调节方式","c":"o","b":"原题库补充 #226"},{"q":"心肌收缩能力","a":"心肌收缩能力是指心肌不依赖前后负荷而改变其力学性能的一种内在特性","c":"o","b":"原题库补充 #227"},{"q":"最佳心率范围","a":"使心输出量处于较高水平的心率范围，称为最佳心率范围","c":"o","b":"原题库补充 #228"},{"q":"减压反射","a":"当血压突然升高时，压力感受器传入冲动至延髓心血管，导致心迷走中枢活动加强，心 交感中枢活动减弱，动脉血压下降，此反射称为减压反射","c":"o","b":"原题库补充 #236"},{"q":"血液的重新分配","a":"运动时，运动的肌肉和心脏的血流量显著增加，不运动的肌肉和内脏器官的血流量减少， 皮肤的血流量先减少后增加，这一现象称血液的重新分配","c":"o","b":"原题库补充 #237"},{"q":"循环系统","a":"是个相对封闭的管道系统，包括心血管系统和淋巴系统两部分。心血管系统由心脏、血 管以及存在于心脏和血管内的血液组成，血管部分包括动脉、毛细血管和静脉","c":"o","b":"原题库补充 #362"},{"q":"窦性节律","a":"窦房结的自律细胞自律性最高，它产生兴奋并控制整个心脏活动的自律组织，故窦房结 被称为心脏活动的正常起搏点，以窦房结为起搏点的心脏节律称为窦性节律","c":"o","b":"原题库补充 #365"},{"q":"“全或无”同步收缩","a":"由于存在同步收缩，心脏要么不收缩，如果发生收缩，其收缩就达到一定强度，称为“全 或无”式收缩","c":"o","b":"原题库补充 #371"},{"q":"最大心率/极限心率","a":"每个人的心率增加均有一定限度，这个限度称为最大心率或极限心率","c":"o","b":"原题库补充 #372"},{"q":"减压反射/压力感受性反射","a":"机体在血压突然升高时，通过压力感受器，可发射性地引起心率减慢、心输出量减少、 血管舒张、外周阻力减小，血压下降，称为压力感受性反射或减压反射","c":"o","b":"原题库补充 #379"}]},{"t":"第八章 消化、吸收、排泄和运动","items":[{"q":"消化","a":"食物通过消化管被分解为可吸收的小分子物质的过程称为消化，包括机械性消化和化学性消化。","c":"4","b":"第四版"},{"q":"机械性消化","a":"机械性消化是指通过消化管肌组织的收缩和舒张，将摄入的食物磨碎，使之与消化液充分搅拌、混合，并将食物不断地向消化管远端推进的过程。","c":"4","b":"第四版"},{"q":"化学性消化","a":"化学性消化是指通过消化腺分泌的消化液，在消化酶作用下将食物中的糖类、脂肪和蛋白质等大分子物质分解为可被吸收的小分子物质的过程。","c":"4","b":"第四版"},{"q":"平滑肌","a":"消化管除口腔、咽、食管上段的肌组织，以及肛门外括约肌属于骨骼肌外，其余部分的肌组织均属于平滑肌，平滑肌具有不同于骨骼肌和心肌的电生理特性和一般生理特性。","c":"4","b":"第四版"},{"q":"消化液","a":"消化腺分泌的液体物质称为消化液，内含多种消化酶、黏液、抗体、水和电解质，人体每天分泌的消化液可达 6~8L。","c":"4","b":"第四版"},{"q":"唾液","a":"唾液是由口腔中的腮腺、颌下腺和舌下腺三对大唾液腺，以及散在的小唾液腺分泌的混合液，日分泌量为1~1.5L。","c":"4","b":"第四版"},{"q":"非条件反射性唾液分泌","a":"进食时，口腔内的机械、化学、温度感受器受到刺激，兴奋沿第 V、VII、IX、X对脑神经传至唾液分泌中枢，然后兴奋沿第VII、IX 区对脑神经的副交感和交感神经纤维到达唾液腺，引起唾液分泌，这一过程为非条件反射性唾液分泌。","c":"4","b":"第四版"},{"q":"条件反射性唾液分泌","a":"进食过程中，食物的性状、颜色、气味、进食环境、进食信号，甚至与食物和进食有关的第二信号（如语言），都可作为条件刺激导致条件反射的形成，引起明显的唾液分泌，这一过程为条件反射性唾液分泌。","c":"4","b":"第四版"},{"q":"胃液","a":"胃液是一种无色的酸性液体，pH为0.9~1.5，正常成年人日分泌量为1.5~2.5L，其主要成分为盐酸、胃蛋白酶原、黏液和内因子。","c":"4","b":"第四版"},{"q":"基础胃酸分泌","a":"在食物的刺激下分泌量将大幅增加，即使空腹6h后在无任何食物刺激的情况下，也有少量分泌，称为基础胃酸分泌。","c":"4","b":"第四版"},{"q":"紧张性收缩","a":"胃壁平滑肌经常处于一定程度的缓慢持续收缩状态，称为紧张性收缩。","c":"4","b":"第四版"},{"q":"容受性舒张","a":"咀嚼和进食动作，以及食物对口腔、咽、食管等处的感受器的刺激，反射性地引起胃底和胃体平滑肌的舒张，称为容受性舒张。","c":"4","b":"第四版"},{"q":"蠕动","a":"蠕动是指胃平滑肌顺序收缩而完成的一种向前推进的波形运动。","c":"4","b":"第四版"},{"q":"胃排空","a":"食物由胃排入十二指肠的过程称为胃排空。","c":"4","b":"第四版"},{"q":"胃肠激素","a":"由于胃肠黏膜中内分泌细胞合成和释放的多种激素主要在消化管内发挥作用，因此把这些激素合称为胃肠激素。","c":"4","b":"第四版"},{"q":"分节运动","a":"分节运动是一种以小肠环行肌为主的节律性收缩和舒张交替进行的运动。","c":"4","b":"第四版"},{"q":"吸收","a":"食物经过消化后的营养成分通过消化道上皮细胞进入血液和淋巴的过程，称为吸收。","c":"4","b":"第四版"},{"q":"排泄","a":"机体将代谢产物、多余的水分和盐类，以及进入体内的异物，经过血液循环由排泄器官排出体外的过程，称为排泄。","c":"4","b":"第四版"},{"q":"肾小球的滤过率","a":"单位时间内两侧肾生成的滤液量，称为肾小球的滤过率。","c":"4","b":"第四版"},{"q":"肾糖阀","a":"生理学上将尿液中开始出现葡萄糖时的血糖浓度，称为肾糖阀。","c":"4","b":"第四版"},{"q":"碱储备量","a":"生理学上通常用每100mL 血浆中的NaHCO 含量来表示碱储备量。","c":"4","b":"第四版"},{"q":"运动性胃肠综合征","a":"剧烈运动还会导致胃肠受到强烈的机械震荡，影响胃肠黏液分泌、胃肠的收缩运动及胃肠黏膜防御屏障，容易引起胃黏膜出血、糜烂，出现恶心、呕吐、反胃、腹痛、腹泻或便血等症状，这种现象被称为运动性胃肠综合征。","c":"4","b":"第四版"},{"q":"运动性蛋白尿","a":"正常人安静时尿液中的蛋白质含量甚微，用常规检测方法无法测出，故尿蛋白检测为阴性，若运动后尿液中出现较多的蛋白质，则称为运动性蛋白尿。","c":"4","b":"第四版"},{"q":"运动性血尿","a":"正常人尿液中无红细胞或偶见个别红细胞，如果运动员或健康人在运动后出现一过性的血尿，经详细检测找不到其他原因，称为运动性血尿。","c":"4","b":"第四版"},{"q":"肾单位","a":"肾单位是指肾脏基本的机能和结构单位，每个肾单位包括肾小体和肾小管两部分，人类 两侧肾脏共约有170~240 万个肾单位","c":"o","b":"原题库补充 #248"},{"q":"血红蛋白尿","a":"当Hb 被大量破坏，其浓度超过了与结合珠蛋白所能结合的量时，未结合的Hb 进入滤 液，从尿中排出，这种尿液称为血红蛋白尿","c":"o","b":"原题库补充 #249"},{"q":"分泌作用","a":"肾小管与集合管上皮细胞将自身新陈代谢的产物分泌到小管液中的过程，称分泌作用","c":"o","b":"原题库补充 #251"},{"q":"肾小管重吸收","a":"肾小管重吸收是指原尿或小管液流经肾小管和集合管时，其中的某些成分通过上皮细胞 重新回到血液的过程","c":"o","b":"原题库补充 #254"},{"q":"肾小球滤过","a":"循环血液流经肾小球毛细血管时，由于毛细血管内血压较高且滤过膜具有通透性，使除 大分子蛋白质外，血浆中的水和小分子溶质均可通过肾小球滤过膜滤入肾小囊中而形成超滤 液，这一过程就称为肾小球滤过","c":"o","b":"原题库补充 #407"},{"q":"重吸收","a":"是指物质从小管液转运至血液中的过程，根据肾小管对物质的重吸收机制不同，可以将 重吸收分为主动转运和被动转运两种","c":"o","b":"原题库补充 #408"}]},{"t":"第九章 神经系统的调节功能","items":[{"q":"神经系统","a":"神经系统也是人体最重要的调节系统，它能够对机体内、外环境的变化进行感觉、分析，并通过其传出信息的变化对躯体功能和内脏功能进行调节。","c":"4","b":"第四版"},{"q":"神经元/神经细胞","a":"神经元，又称神经细胞，由细胞体（胞体）和突起组成，突起又分树突及轴突，神经元承担着神经系统的主要功能活动。","c":"4","b":"第四版"},{"q":"神经纤维","a":"神经元的轴突和包裹轴突的髓鞘总称为神经纤维。","c":"4","b":"第四版"},{"q":"轴浆运输","a":"神经纤维内的轴浆经常处于流动状态，轴浆流动具有运输物质的作用，故称为轴浆运输。","c":"4","b":"第四版"},{"q":"顺向轴浆运输","a":"轴浆从胞体向轴突末梢的运输称为顺向轴浆运输。","c":"4","b":"第四版"},{"q":"逆向轴浆运输","a":"轴浆自末梢到胞体的运输则称为逆向轴浆运输。","c":"4","b":"第四版"},{"q":"神经营养因子","a":"神经对所支配的组织除发挥调节作用外，还能通过神经末梢释放一些营养性因子，如神经生长因子、脑源性神经营养因子、神经营养因子3和神经营养因子4/5 等，这些物质统称为神经营养因子。","c":"4","b":"第四版"},{"q":"营养性作用","a":"神经营养因子可持续调节所支配组织的代谢活动，影响其结构、生化和生理功能，神经的这种作用称为营养性作用。","c":"4","b":"第四版"},{"q":"神经冲动","a":"在神经系统活动中，神经元实现其功能的最基本方式就是产生动作电位，也可称为神经冲动。","c":"4","b":"第四版"},{"q":"神经传导","a":"在神经元任何一个部位所产生的神经冲动，均可传播到整个细胞，使细胞未兴奋部位依次经历一次膜电位的倒转，这一过程称为神经冲动的传导，简称神经传导。突触在中枢神经系统中，神经冲动作为信息单位不仅限于一个神经元范围内的传导，还要经过两个或两个以上神经元，生理学中将相互连结的两个神经元之间或神经元与效应器之间的接触部称为突触。","c":"4","b":"第四版"},{"q":"突触传递","a":"信息从前一个神经元传递给后一个神经元，这一信息传递过程被称为突触传递。","c":"4","b":"第四版"},{"q":"电突触","a":"信息传递媒介为局部电流的突触，称为电突触。","c":"4","b":"第四版"},{"q":"化学性突触","a":"信息传递媒介物是神经递质的突触，称为化学性突触。化学性突触是由相互对应的突触前膜和突触后膜结构构成。","c":"4","b":"第四版"},{"q":"间隙连接","a":"在电突触处，两个神经元紧密接触的部位间隔 2~4nm，连接部位的细胞膜并不增厚，两侧膜上有沟通细胞胞质的通道蛋白，这种结构又称为间隙连接。","c":"4","b":"第四版"},{"q":"突触间隙","a":"一般情况下，轴突末梢被视为突触前的部分，目标神经元的树突、胞体和轴突处或效应器细胞则被视为突触后的部分，两者之间的狭小区间称为突触间隙，宽为20~40nm，其间有黏多糖和糖蛋白。","c":"4","b":"第四版"},{"q":"突触后电位","a":"递质进入突触间隙后，经扩散抵达突触后膜，作用于后膜上特异性受体或化学门控通道，引起后膜对某些离子通透性的改变，使某些带电离子进出后膜，突触后膜即发生一定程度的去极化或超极化。这种发生在突触后膜上的电位变化，称为突触后电位。","c":"4","b":"第四版"},{"q":"兴奋性突触后电位","a":"根据突触后膜发生去极化或超极化的不同，可将突触后电位分为兴奋性突触后电位和抑制性突触后电位两种。如果突触后膜在递质作用下发生去极化，使该突触后神经元的兴奋性升高，这种电位变化称为兴奋性突触后电位。","c":"4","b":"第四版"},{"q":"抑制性突触后电位","a":"如果突触前膜释放的是抑制性递质，它可引起后膜对 K+和 CI-，尤其是 CI-的通透性升高，导致突触后膜产生超极化，这一电位变化称为抑制性突触后电位。","c":"4","b":"第四版"},{"q":"反射","a":"反射是神经活动的基本方式，身体各部位的感受器相当于换能器，其功能是将所感受的刺激转变为一定形式的神经放电信号，后者通过传入神经纤维传至相应的神经中枢，神经中枢对传入信号进行分析并作出反应后，再通过传出神经纤维将神经中枢的指令传达到相应的效应器官发动或改变其活动，这一过程就称为反射。","c":"4","b":"第四版"},{"q":"非条件反射","a":"非条件反射是指人和动物生来就有、数量有限、种系所有、比较固定和形式低级的反射活动（如防御反射、食物反射、性反射等）。","c":"4","b":"第四版"},{"q":"条件反射","a":"条件反射是反射活动的高级形式，是指人和高等动物在个体生活过程中，按照所处的生活环境，在非条件反射的基础上，通过后天学习和训练不断建立而形成的一种反射活动。","c":"4","b":"第四版"},{"q":"单线式联系","a":"单线式联系是指一个突触前神经元仅与一个突触后神经元发生突触联系。","c":"4","b":"第四版"},{"q":"聚合式联系","a":"一个神经元接收来自许多神经元的轴突末梢而建立突触联系称为聚合式联系。","c":"4","b":"第四版"},{"q":"辐散式联系","a":"辐散式联系是指一个神经元可通过其轴突末梢与多个神经元形成突触联系，从而使与之相联系的许多神经元同时兴奋或抑制。","c":"4","b":"第四版"},{"q":"中枢延搁","a":"兴奋经中枢化学性突触传递所需时间与在相同距离的神经纤维上传导相比要长得多，这一现象称为中枢延搁。","c":"4","b":"第四版"},{"q":"后发放/后放电","a":"在中枢神经系统兴奋冲动环式联系中，即使最初的刺激已经停止，传出通路上的冲动发放仍能继续一段时间，这种现象称为后发放或后放电，该现象常见于各种神经反馈活动中。","c":"4","b":"第四版"},{"q":"突触后抑制","a":"由抑制性中间神经元释放抑制性神经递质，使突触后神经元产生 IPSP 而引起的抑制，称为突触后抑制。","c":"4","b":"第四版"},{"q":"传入侧支性抑制/交互抑制","a":"传入神经进入中枢后，一方面通过突触联系兴奋一个中枢神经元，另一方面通过侧支兴奋一个抑制性中间神经元，通过后者的活动再抑制另一个中枢神经元，这种抑制称为传入侧支性抑制或交互抑制。","c":"4","b":"第四版"},{"q":"回返性抑制","a":"中枢神经元兴奋时，传出冲动沿轴突外传，同时又经轴突侧支兴奋一个抑制性中间神经元，后者释放抑制性神经递质，反过来抑制原先兴奋的神经元及同一个中枢的其他神经元，这种抑制称为回返性抑制。","c":"4","b":"第四版"},{"q":"突触前抑制","a":"在突触前膜产生的抑制称为突触前抑制。这种抑制在中枢内广泛存在，尤其多见于感觉传入通路中，对调节感觉传入活动具有重要意义。","c":"4","b":"第四版"},{"q":"突触后易化","a":"突触后易化与突触前易化都可使 EPSP幅度增大。由于突触后膜的去极化，而使膜电位靠近阈电位水平，这一现象称为突触后易化。","c":"4","b":"第四版"},{"q":"突触前易化","a":"由于突触前轴突末梢的动作电位时程延长，使末梢释放的神经递质增多，最终使突触后膜神经元的EPSP增大，即产生突触前易化。","c":"4","b":"第四版"},{"q":"感受器","a":"在人和动物的体表或组织内部存在着一些专门感受机体内外环境变化刺激所形成的结构装置，称为感受器。","c":"4","b":"第四版"},{"q":"本体感觉","a":"位于肌肉、肌腱和关节等处的肌梭、腱器官和关节感受器统称为本体感受器，对躯体的空间位置、姿势、运动状态和运动方向的感觉称之为本体感觉。","c":"4","b":"第四版"},{"q":"肌梭","a":"肌梭是骨骼肌中一种特殊的感受装置，由梭内肌、神经末梢、梭囊和微小血管构成，位于肌肉的深部。","c":"4","b":"第四版"},{"q":"腱器官","a":"腱器官是长约1mm、直径0.1mm 的囊状结构，位于骨骼肌和肌腱的连接部位，与骨骼肌呈串联式排列。","c":"4","b":"第四版"},{"q":"触-压觉","a":"给皮肤施以触、压等机械刺激所引起的感觉，分别称为触觉和压觉，由于两者在性质上类似，故被统称为触-压觉。","c":"4","b":"第四版"},{"q":"温度觉","a":"在人类的皮肤上存在专门的“热点”和“冷点”，刺激这些点能分别引起热觉和冷觉，两者合称为温度觉。","c":"4","b":"第四版"},{"q":"痛觉","a":"痛觉是由体内、外伤害性刺激所引起的一种主观感觉，常伴有情绪活动和防卫反应。痛觉不是一个独立的单一感觉，而是一种与其他感觉混杂在一起的复合感觉。","c":"4","b":"第四版"},{"q":"躯体感觉代表区","a":"从丘脑携带的躯体感觉信息经特异投射系统投射到大脑皮质的特定区域，该区域称为躯体感觉代表区。","c":"4","b":"第四版"},{"q":"感觉运动区","a":"中央前回（4区）是运动区，也是本体感觉代表区。在较低等的哺乳动物，体表感觉区与运动区基本重合在一起，称为感觉运动区。","c":"4","b":"第四版"},{"q":"近视","a":"由于眼球前后径过长或折光系统的折光能力过强，远处物体发出的光线被聚焦在视网膜的前方，形成模糊的图像，这种情况称为近视。","c":"4","b":"第四版"},{"q":"远视","a":"由于眼球前后径过短或折光系统的折光能力太弱，远处物体发出的光线被聚焦在视网膜的后方，形成模糊的图像，称为远视。","c":"4","b":"第四版"},{"q":"视敏度/视力","a":"眼对物体细小结构的分辨能力称为视敏度，又称为视力，视力的量度通常以视角的倒数来表示。","c":"4","b":"第四版"},{"q":"视野","a":"用单眼固定地注视前方一点时，所能看到的空间范围称为视野。","c":"4","b":"第四版"},{"q":"融合现象","a":"用闪光重复刺激人眼，若闪光频率较低，在主观上可以分辨出彼此分开的光感，当闪光频率增加到一定程度（每秒大于几十次）时，人眼无法区分每个闪光之间的间隔，在主观上将产生连续光感，这一现象称为融合现象。","c":"4","b":"第四版"},{"q":"视网膜","a":"视网膜是位于眼球最内层的神经组织，视网膜上含有对光高度敏感的视杆细胞和视锥细胞，以及与之相联系的双极细胞和视神经节细胞，构成了眼的两种感光换能系统，即视杆系统和视锥系统。","c":"4","b":"第四版"},{"q":"视杆系统","a":"视杆系统又称为晚光觉或暗视觉系统，由视杆细胞和与之相联系的双极细胞及神经节细胞等组成，它们对光的敏感度较高，能在昏暗环境中感受弱光刺激而引起暗视觉，但无色觉，对被视物细节的分辨能力较差。","c":"4","b":"第四版"},{"q":"视锥系统","a":"视锥系统又称为昼光觉或明视觉系统，由视锥细胞和与之相联系的双极细胞及神经节细胞等组成，它们对光的敏感性较差，只有在强光条件下才能被激活，但视物时可辨别颜色，且对被视物的细节具有较高的分辨能力。","c":"4","b":"第四版"},{"q":"前庭器官","a":"前庭器官由内耳的椭圆囊、球囊和三个半规管组成，它是人体对自身姿势、运动状态及头部在空间位置感知的感受器，在保持身体的平衡中起重要作用。","c":"4","b":"第四版"},{"q":"前庭自主神经反应","a":"当半规管受到过强或长时间的刺激时，可通过前庭神经核与网状结构的联系引起自主神经功能失调，导致如心率加快、血压下降、呼吸频率增加、出汗，以及皮肤苍白、恶心呕吐、唾液分泌增多等，这种现象称为前庭自主神经反应。","c":"4","b":"第四版"},{"q":"反射性运动","a":"反射性运动是指不受主观意识控制、运动形式固定、反应快捷的运动。","c":"4","b":"第四版"},{"q":"形式化运动","a":"形式化运动是指主观意识只控制运动的起始与终止，而运动期间多可自动完成，此类运动形式固定，具有节律性与连续性。","c":"4","b":"第四版"},{"q":"意向性运动","a":"意向性运动是指运动具有明确的目的性，运动全过程均受主观意识支配，运动形式较为复杂，一般是通过后天的学习而获得。","c":"4","b":"第四版"},{"q":"到达肌肉的“最后公路”","a":"人的脊髓前角内约有300万个运动神经元直接与骨骼肌相连，它们既接受来自皮肤、肌肉和关节等部位传入的信息，同时也接受各级高位中枢下达的有关调控运动的指令，最后发出适宜的传出冲动引起所支配的肌肉收缩，从而实现各种反射性运动和随意运动。因此有人把位于脊髓前角的运动神经元称为到达肌肉的“最后公路”。","c":"4","b":"第四版"},{"q":"运动单位","a":"一个α运动神经元与它所支配的那些肌纤维，组成一个运动单位。","c":"4","b":"第四版"},{"q":"运动神经元池","a":"一块骨骼肌通常接受许多运动神经元支配，这些神经元比较集中位于脑干内几个毫米的区域或脊髓相邻节段的前角，因此将支配一块肌肉的那一组运动神经元相对集中的区域称为运动神经元池。","c":"4","b":"第四版"},{"q":"姿势反射","a":"中枢神经系统通过调节骨骼肌的紧张度或产生相应的运动，以保持或改变躯体在空间的姿势，这种反射称为姿势反射。","c":"4","b":"第四版"},{"q":"牵张反射","a":"牵张反射是指有完整神经支配的骨骼肌，在受外力牵拉伸长时引起的被牵拉的同一肌肉发生收缩的反射。","c":"4","b":"第四版"},{"q":"腱反射","a":"腱反射是指快速牵拉肌腱时发生的牵张反射，如叩击股四头肌肌腱引起的股四头肌收缩的膝反射，叩击跟腱引起的小腿腓肠肌收缩的跟腱反射等。","c":"4","b":"第四版"},{"q":"肌紧张","a":"肌紧张是指缓慢持续牵拉肌腱时发生的牵张反射，表现为受牵拉的肌肉处于持续的、同一肌肉的不同运动单位交替进行的收缩状态，但不表现出明显的动作，故能持久进行而不易疲劳。","c":"4","b":"第四版"},{"q":"屈肌反射","a":"脊椎动物在受到伤害性刺激时，受刺激的一侧肢体关节的屈肌快速收缩而伸肌弛缓、肢体屈曲，这种反射称为屈肌反射，该反射具有保护意义。","c":"4","b":"第四版"},{"q":"对侧伸肌反射","a":"在屈肌反射的基础上，如加大刺激强度，则可在同侧肢体屈曲的基础上出现对侧肢体伸展，称为对侧伸肌反射，该反射在维持躯体平衡中具有重要意义。","c":"4","b":"第四版"},{"q":"状态反射","a":"头部空间位置的改变及头部与躯干的相对位置发生改变时，将反射性地引起躯干和四肢肌肉紧张性的改变，这种反射称为状态反射。","c":"4","b":"第四版"},{"q":"迷路紧张反射","a":"迷路紧张反射是指头部空间位置发生改变时，内耳迷路耳石器官（椭圆囊和球囊）的传入冲动对躯体伸肌紧张性的调节反射。","c":"4","b":"第四版"},{"q":"颈紧张反射","a":"颈紧张反射是指颈部扭曲时，颈椎关节韧带和颈部肌肉受到刺激后，对四肢肌肉紧张性的调节反射。","c":"4","b":"第四版"},{"q":"翻正反射","a":"当人和动物处于不正常体位时，通过一系列协调运动将体位恢复常态的反射，称为翻正反射。","c":"4","b":"第四版"},{"q":"脑的可塑性","a":"脑的结构和功能随着内、外环境变化，不断修饰和重组的能力，称为脑的可塑性。","c":"4","b":"第四版"},{"q":"自主神经系统/内脏神经系统","a":"在机体中，调节内脏活动的神经称为自主神经系统，也称为内脏神经系统，包括传入神经和传出神经两部分，但通常所说的自主神经主要是指其传出部分。","c":"4","b":"第四版"},{"q":"节前纤维","a":"节前神经元胞体位于中枢内，它发出的神经纤维称为节前纤维，抵达自主神经节内并换元。","c":"4","b":"第四版"},{"q":"节后纤维","a":"节后神经元发出的神经纤维称为节后纤维，支配相应的效应器官。","c":"4","b":"第四版"},{"q":"边缘系统","a":"边缘叶和大脑皮质的岛叶、颞极、眶回，以及皮质下的杏仁核、隔区、下丘脑前核等皮质下结构，统称为边缘系统。","c":"4","b":"第四版"},{"q":"本能行为","a":"本能行为是指动物在进化过程中形成并经遗传固定下来的对个体和种属生存具有重要意义的行为，如摄食、饮水和性行为等。","c":"4","b":"第四版"},{"q":"情绪","a":"情绪是指人类和动物对客观环境刺激所表达的一种特殊的心理体验和某种固定形成的躯体行为表现。","c":"4","b":"第四版"},{"q":"情绪生理反应","a":"情绪生理反应是指在情绪活动中伴随发生的一系列生理变化，主要包括自主神经系统和内分泌系统功能活动的变化。","c":"4","b":"第四版"},{"q":"动机","a":"动机是指激发人或动物产生某种行为的意念。人类和动物的行为不是偶然发生的，本能行为也都是在一定的欲望驱使下产生的。","c":"4","b":"第四版"},{"q":"成瘾","a":"成瘾是泛指不能自制并不顾其消极后果反复地将某种物品摄入体内的表现。","c":"4","b":"第四版"},{"q":"化学突触","a":"化学突触是由突触前膜、后膜和突触间隙组成，具有单向传递、可塑性和突触延搁等特 征","c":"o","b":"原题库补充 #118"},{"q":"突触","a":"一个神经元的轴突末梢终端与另一个神经元的突起或胞体相互接触，并进行兴奋或抑制 的传递，这个相接触部位称为突触","c":"o","b":"原题库补充 #122"},{"q":"突触小体","a":"在轴突主干上，轴突的末梢分成许多分支，每个分支末端的膨大部分称为突触小体","c":"o","b":"原题库补充 #124"},{"q":"躯体感觉","a":"来自骨骼肌、肌腱和关节等处的深感觉和来自皮肤的浅感觉，总称为躯体感觉","c":"o","b":"原题库补充 #129"},{"q":"本体感受器","a":"本体感受器是指分布在肌肉、肌腱和关节囊中的肌梭与腱梭，能分别感受肌肉被牵拉的 程度及肌肉收缩和关节伸展的程度","c":"o","b":"原题库补充 #130"},{"q":"两点辨别阈","a":"触—压觉是皮肤接受机械刺激时产生的感觉。触—压觉能分辨出两点的最小距离，称为 两点辨别阈","c":"o","b":"原题库补充 #131"},{"q":"特异神经能量定律","a":"当刺激发生在一个特定感觉的神经通路时，无论该通路的活动是如何引起的，或者是由 该通路的哪一部分所产生的，所引起的感觉总是该感受器在生理情况下兴奋所引起的感觉， 这一原理称为特异神经能量定律","c":"o","b":"原题库补充 #133"},{"q":"感光换能系统","a":"视网膜上含有对光高度敏感的视杆细胞和视锥细胞，以及与之相联系的双极细胞和视神 经节细胞，构成了眼的两种感光换能系统，即视杆系统和视锥系统","c":"o","b":"原题库补充 #136"},{"q":"静态牵张反射","a":"静态牵张反射是缓慢持续牵拉肌肉而形成的，主要调节肌肉的紧张度，对维持躯体姿势 是非常重要的","c":"o","b":"原题库补充 #149"},{"q":"动态牵张反射","a":"由快速牵拉肌肉引起反射称为动态牵张反射，它的作用是对抗肌肉的拉长","c":"o","b":"原题库补充 #151"},{"q":"脑干网状结构","a":"在脑干中轴部位内许多形状和大小各异的神经元组成的脑区，其间穿行着各类行向不同 的神经纤维呈网状，这一部位称为脑干网状结构","c":"o","b":"原题库补充 #154"},{"q":"前庭反应","a":"前庭反应是指前庭分析器的感受器受刺激发放强烈而频繁的冲动，反射性地引起四肢躯 干肌张力的正常关系失调，使动作或身体平衡失调，还会使眼肌产生不随意的收缩和放松， 引起眼球发生有规律的震颤","c":"o","b":"原题库补充 #155"},{"q":"组构原则","a":"运动皮质发出下行控制纤维的细胞是高度分域地组织起来的，与每一块肌肉有关的皮质 神经元都有集聚的中心和围绕的外野，任何支配不同肌肉的中心区不会重叠，但是一条肌肉 的外野支配区可能和另一条肌肉的外野，甚至和它的中心区发生重叠，这一分布规律被称之 为皮质运动区神经元的组构原则","c":"o","b":"原题库补充 #156"},{"q":"皮质脊髓束","a":"由皮质发出，经内囊、脑干下行，到达脊髓前角运动神经元的传导束，称为皮质脊髓束。","c":"o","b":"原题库补充 #160"},{"q":"感觉器官","a":"感觉器官是指感受器与其附属装置共同构成的结构。人最主要的感觉器官有眼、耳、前 庭、鼻腔的嗅上皮、舌的味蕾、皮肤等","c":"o","b":"原题库补充 #410"},{"q":"前庭功能稳定性","a":"刺激前庭感受器而引起机体各种前庭反应的程度，称为前庭功能稳定性。其意义在于维 持机体一定的姿势和保持身体平衡","c":"o","b":"原题库补充 #413"},{"q":"视杆细胞","a":"主要分布在视网膜的周边部分，最高密度在偏离中央凹6nm 处，和与他们相联系的双 极细胞及神经节细胞等组成视杆系统，对光的敏感度高，能接受弱光刺激，形成暗视觉，但 无色觉，对被视物细节的分辨能力较差","c":"o","b":"原题库补充 #415"},{"q":"视锥细胞","a":"视锥细胞主要分布在视网膜的中央凹处，和与它们相联系的双极细胞和神经节细胞等组 成视锥系统。它们对光的敏感性较差，只能接受强光刺激，形成明视觉和色觉，并对被视物 体细节具有较高的分辨能力","c":"o","b":"原题库补充 #416"},{"q":"位觉","a":"身体进行各种变速运动时会引起前庭器官中的位觉感受器兴奋而产生的感觉，称为位觉 （前庭感觉）","c":"o","b":"原题库补充 #417"},{"q":"腱梭","a":"是分布在肌腱胶原纤维之间的一种张力感受器，与梭外肌纤维串联。","c":"o","b":"原题库补充 #418"},{"q":"神经胶质细胞","a":"神经胶质细胞是神经组织中除神经细胞以外的另一大类细胞，其数量是神经细胞的 10~50 倍，形态多样，细胞通常较小，胞突无树突与轴突之分，不与神经元形成突触，也不 传导神经冲动","c":"o","b":"原题库补充 #420"},{"q":"神经递质","a":"是指由神经元合成，突触前末梢释放，能特异性作用于突触后膜受体，并产生突触后电 位的信息传递物质","c":"o","b":"原题库补充 #421"},{"q":"递质共存","a":"两种或两种以上的递质(包括调质)共存于同一神经元内的现象称为递质共存。递质共存 的意义在于协调某些生理功能活动","c":"o","b":"原题库补充 #422"},{"q":"非定向突触传递","a":"当神经冲动到达曲张体时，递质从曲张体释放出来，以扩散方式到达效应器或突触后膜 上的受体，与膜上的相应受体结合，从而产生效应或使突触后膜发生反应，这种模式称为非 突触性化学传递，为非定向突触传递","c":"o","b":"原题库补充 #425"},{"q":"强直后增强","a":"是指突触前末梢在接受一短串高频刺激后，突触后电位幅度持续增大的现象","c":"o","b":"原题库补充 #426"},{"q":"长时程增强","a":"是指突触前神经元在短时间内受到快速重复的刺激后，在突触后神经元快速形成的持续 时间较长的兴奋性突触后电位增强，表现为潜伏期缩短，幅度增高，斜率加大","c":"o","b":"原题库补充 #427"},{"q":"长时程抑制","a":"是指突触传递效率的长时程降低。与长时程增强相反。长时程抑制也广泛存在于中枢神 经系统","c":"o","b":"原题库补充 #428"},{"q":"学习","a":"是指人和动物依赖于经验来改变自身行为以适应环境获得新知识或新技能的神经活动 过程，是信息“储存”的过程","c":"o","b":"原题库补充 #429"},{"q":"记忆","a":"是指学习到的新知识或技能编码、贮存和“读出”的神经活动过程","c":"o","b":"原题库补充 #430"},{"q":"外抑制","a":"由于引起条件反射抑制的刺激是在条件反射中枢以外，故称为外抑制。如比赛中新异刺 激引起的运动失误","c":"o","b":"原题库补充 #431"},{"q":"超限抑制","a":"由于过强或时间过长的刺激超过了大脑皮质神经细胞的工作承受能力，为防止皮质细胞 受损害而产生的保护性抑制，通常被称为超限抑制","c":"o","b":"原题库补充 #432"},{"q":"消退抑制","a":"在条件反射形成后，如果反复应用条件刺激而不给予非条件刺激强化，已形成的条件反 射就会逐渐减弱，直至消失，这种现象称为消退抑制","c":"o","b":"原题库补充 #433"},{"q":"延缓抑制","a":"建立条件反射的过程中，给予条件刺激后，再间隔一定时间才给予非条件刺激强化，如 此反复多次以后，便形成延缓条件反射","c":"o","b":"原题库补充 #435"},{"q":"条件抑制","a":"由于附加刺激不予强化而引起的抑制就称为条件抑制。例如，在球类运动中，许多限制 性规则都具有条件抑制作用","c":"o","b":"原题库补充 #436"},{"q":"脊髓休克","a":"是指人或动物的脊髓在与高位中枢之间离断后反射活动能力暂时丧失而进入无反应状 态的现象","c":"o","b":"原题库补充 #438"},{"q":"旋转运动反射","a":"人体在进行主动或被动旋转运动时，为了恢复正常体位而产生的一种反射活动，称为旋 转运动反射","c":"o","b":"原题库补充 #439"},{"q":"直线运动反射","a":"人体在主动或被动地进行直线加、减速运动时，即发生肌张力重新调配以恢复常态的现 象，称为直线运动反射","c":"o","b":"原题库补充 #440"},{"q":"脑电图","a":"在无明显刺激情况下，大脑皮质能经常自发地产生节律性的电位变化称为自发脑电活动。 经过人头皮电极引导、放大并记录下来的脑电活动图形称为脑电图。","c":"o","b":"原题库补充 #441"}]},{"t":"第十章 内分泌系统的调节功能","items":[{"q":"内分泌","a":"内分泌是指内分泌腺或内分泌细胞将其所产生的激素直接释放到体液中并发挥作用的分泌形式。","c":"4","b":"第四版"},{"q":"内分泌腺","a":"内分泌细胞集中的腺体统称为内分泌腺，体内主要的内分泌腺包括下丘脑、垂体、甲状腺、甲状旁腺、肾上腺、胰岛、性腺、松果体和胸腺等。","c":"4","b":"第四版"},{"q":"靶器官/靶组织/靶细胞","a":"被激素所作用的特定器官、组织和细胞分别称为该激素的靶器官、靶组织和靶细胞。","c":"4","b":"第四版"},{"q":"内分泌系统","a":"由主要的内分泌腺与分布在心脏、肝、肌肉等功能器官组织中的内分泌细胞组成的系统，统称为内分泌系统，该系统通过激素的分泌和作用，传递信息并调控机体的各种生理功能。","c":"4","b":"第四版"},{"q":"激素","a":"激素早期译作荷尔蒙，是内分泌腺或器官组织的内分泌细胞所合成与分泌、以体液为媒介、在细胞之间传送调节信息的高效能生物活性物质。","c":"4","b":"第四版"},{"q":"远距分泌","a":"内分泌激素以血液作为媒介实现长距离的通讯，将所携带的调节信息递送到机体远处的靶器官、靶组织和靶细胞，实现长距离的通讯称为远距分泌，主要分泌激素大多以远距分泌的形式发挥作用。","c":"4","b":"第四版"},{"q":"旁分泌","a":"激素通过组织液扩散而作用于邻近的其他靶细胞，称为旁分泌，如胰岛 A 细胞分泌的胰高血糖素会刺激胰岛 B 细胞分泌胰岛素；","c":"4","b":"第四版"},{"q":"自分泌","a":"激素原位作用于产生该激素的细胞称为自分泌，如胰岛素可抑制胰岛 B 细胞自身分泌胰岛素。","c":"4","b":"第四版"},{"q":"内在分泌","a":"激素不通过释放而直接在合成激素的细胞内发挥作用称为内在分泌，如肾上腺髓质激素抑制自身合成酶的活性。","c":"4","b":"第四版"},{"q":"神经分泌","a":"具有内分泌功能的神经细胞所分泌的激素称为神经分泌，如下丘脑神经元所分泌的调节肽，可通过垂体门脉系统作用于腺垂体。","c":"4","b":"第四版"},{"q":"腔分泌","a":"激素直接释放到体内管腔中发挥作用称为腔分泌，如某些胃肠激素可直接分泌至肠腔中发挥作用。","c":"4","b":"第四版"},{"q":"协同作用","a":"协同作用表现为不同激素对同一生理过程都有增强作用，如生长激素、糖皮质激素、肾上腺素与胰高血糖素都能使血糖升高。","c":"4","b":"第四版"},{"q":"拮抗作用","a":"拮抗作用表现为不同激素对某一生理活动的作用相反，如胰岛素使血糖水平降低，而胰高血糖素使血糖水平升高。","c":"4","b":"第四版"},{"q":"允许作用","a":"有些激素本身并不能直接对某器官或细胞产生生理效应，但它的存在却是另一种激素发挥效应的必要条件，这种现象称为允许作用。例如，糖皮质激素本身对心肌和血管平滑肌无收缩作用，但必须有它的存在，儿茶酚胺才能发挥收缩血管的作用。","c":"4","b":"第四版"},{"q":"受体","a":"受体是指位于细胞膜上或细胞内能与某些化学物质（如激素、递质、调质等）特异结合并诱发特定生物学效应的特殊生物分子。","c":"4","b":"第四版"},{"q":"下调","a":"受体数目减少后，所结合的激素相应减少，这种现象称为“下调”。","c":"4","b":"第四版"},{"q":"上调","a":"相反，细胞也可通过增加该激素受体数目，对某种激素的长期低水平作出相应反应，这样就会使细胞对该激素变得更加敏感，可结合更多的激素，这种现象称为“上调”。","c":"4","b":"第四版"},{"q":"内分泌功能轴","a":"内分泌这种以“一条线”发挥作用的方式，被称为“内分泌功能轴”。","c":"4","b":"第四版"},{"q":"应激轴","a":"肾上腺皮质激素作用于靶器官、靶组织或靶细胞，通过增强能量代谢等反应，对运动产生应激，故将其也称为应激轴。","c":"4","b":"第四版"},{"q":"呆小症","a":"胚胎时期缺碘而导致甲状腺激素合成不足或出生后甲状腺功能低下的婴幼儿，脑的发育有明显障碍，即智力低下且身材矮小，称为呆小症。","c":"4","b":"第四版"},{"q":"应激反应","a":"当机体突然受到创伤、手术、冷冻、饥饿、疼痛、感染、惊恐和剧烈运动等不同刺激时，均可出现血液中促肾上腺皮质激素浓度的急剧增高和糖皮质激素的大量分泌，这种非特异反应称为应激反应，其应激包括警戒反应期、抵抗期和衰竭期三个时期。","c":"4","b":"第四版"},{"q":"拟交感物质","a":"肾上腺髓质激素的生理作用与交感神经节后纤维的作用基本上一致，因此可以将肾上腺髓质看成是交感神经的神经节和它的延伸部分，肾上腺髓质激素也被称为“拟交感物质”。","c":"4","b":"第四版"},{"q":"应急反应","a":"当机体遭遇紧急情况时，如剧痛、缺氧、脱水、大出血、畏惧及剧烈运动时，交感-肾上腺髓质系统发生的应答性反应，称为应急反应。","c":"4","b":"第四版"},{"q":"生理应激","a":"生理应激是指一种日常生活中少见的强烈刺激引起的反应和恢复过程的总称，包括机体 对刺激的直接反应及代偿反应、机体对刺激的部分适应或全部适应和刺激停止后的恢复三个 阶段","c":"o","b":"原题库补充 #164"},{"q":"应急","a":"当机体遭遇特殊紧急情况（如畏惧、严重焦虑、剧痛、失血、脱水、暴冷暴热以及缺氧 窒息等）时，交感-肾上腺系统即被调动起来，通过调整身体各种机能，以抵抗环境的变化 或暂时渡过紧急时刻，称为应急","c":"o","b":"原题库补充 #165"},{"q":"长反馈","a":"激素分泌的调节中，某些靶腺所分泌的激素可对下丘脑或腺垂体的分泌活动发生反馈作 用，由于这种反馈的途径较长，故称为长反馈","c":"o","b":"原题库补充 #166"},{"q":"短反馈","a":"腺垂体分泌的促激素对下丘脑有反馈作用，由于这类反馈的路程较短，故称之为短反馈","c":"o","b":"原题库补充 #167"}]},{"t":"第十一章 免疫系统的调节功能","items":[{"q":"免疫/免疫力","a":"人体通过自身识别并排除“非己”成分以保持机体安全的一种生理反应称为免疫。免疫作为机体的一种防御功能，也称为免疫力。","c":"4","b":"第四版"},{"q":"先天性免疫","a":"人体对抗原性异物的抵抗力，有些是天生具有的，即在种系发育进化过程中形成的，经遗传获得的，称为先天性免疫。","c":"4","b":"第四版"},{"q":"非特异性免疫","a":"因先天性免疫并非针对某一特定的病原微生物，又称为非特异性免疫，该免疫是由机体的解剖结构与生理功能所体现，如机体的各种屏障结构、吞噬细胞及体液中的抗菌物质等。","c":"4","b":"第四版"},{"q":"获得性免疫","a":"个体在生活过程中，因受某种病原微生物感染或接种疫苗而获得的免疫，称为获得性免疫。","c":"4","b":"第四版"},{"q":"特异性免疫","a":"因获得性免疫免疫一般仅针对所感染的病原微生物或疫苗所能预防的疾病，故又称为特异性免疫，通常所说的免疫是指特异性免疫。","c":"4","b":"第四版"},{"q":"中枢免疫器官","a":"能够使免疫细胞增殖，并在一定程度上分化成为成熟的免疫细胞的器官，称为中枢免疫器官，如骨髓和胸腺，它们是免疫细胞发育分化的场所。","c":"4","b":"第四版"},{"q":"外周免疫器官","a":"能够接受中枢免疫器官输送到外周的成熟免疫细胞的器官，称为外周免疫器官，如淋巴结、脾和扁桃体，它们是免疫细胞定居的场所。","c":"4","b":"第四版"},{"q":"免疫细胞","a":"免疫细胞是指参与免疫应答或与免疫应答过程相关的细胞，主要包括淋巴细胞、单核/巨噬细胞、粒细胞和肥大细胞等，不同免疫细胞的形态各异。","c":"4","b":"第四版"},{"q":"抗原特异性淋巴细胞或免疫活性细胞","a":"能接受抗原刺激而活化、增殖、分化并发生特异性免疫反应的淋巴细胞，称为抗原特异性淋巴细胞或免疫活性细胞，即T淋巴细胞和B淋巴细胞。","c":"4","b":"第四版"},{"q":"T细胞","a":"T淋巴细胞全称为胸腺依赖性淋巴细胞，简称为T 细胞，主要介导细胞免疫。","c":"4","b":"第四版"},{"q":"B细胞","a":"B 淋巴细胞全称为骨髓依赖性淋巴细胞，简称为B细胞，主要介导体液免疫。","c":"4","b":"第四版"},{"q":"免疫系统的功能","a":"免疫系统的功能是机体识别和清除外来人侵抗原及体内突变或衰老细胞并维持机体内环境稳定的功能的总称，是指免疫系统在识别和排除异已物质过程中所产生的各种生物学效应。","c":"4","b":"第四版"},{"q":"免疫防御","a":"免疫防御是指机体防御外来病原微生物的抗感染免疫，但在异常情况下若免疫反应过于强烈，可引起超敏反应，免疫防御功能过低或缺陷则表现为易受感染或免疫缺陷病。","c":"4","b":"第四版"},{"q":"免疫稳定","a":"免疫稳定（或称免疫自稳）是机体免疫系统内部的自控调节机制，以清除体内出现的变性、衰老、死亡细胞等，从而维持机体在生理范围内的相对稳定。若此功能失调，可导致自身免疫性疾病。","c":"4","b":"第四版"},{"q":"免疫监视","a":"免疫监视是指机体的免疫系统能够寻找和识别外来病原体（如细菌和病毒）或体内癌变细胞。","c":"4","b":"第四版"},{"q":"“开窗”理论","a":"该理论认为，人体在进行大强度急性运动时，应激激素的急剧升高及血流动力学发生的急剧变化，导致淋巴细胞快速动员入血、数量急剧升高，出现免疫低下期。形象地将这段免疫低下期称为“openwindow”，意为“打开的窗户”，此阶段运动员易感率明显上升。","c":"4","b":"第四版"},{"q":"“J”形曲线模式","a":"以正常不运动者安静水平作为参照，发现适量强度的经常性身体运动可明显降低上呼吸道感染率，而大强度运动训练则使之明显升高，将这三者用拟合曲线相连，可形成一条类似“J”形的曲线，故将这一现象形象地称之为“J”形曲线模式。","c":"4","b":"第四版"},{"q":"运动因子","a":"不同器官受身体运动影响所释放的相关的信号分子统称为运动因子。运动因子通过激活相关信号通路，改善靶器官、靶组织和靶细胞的功能状态和代谢水平，在改善全身不同系统和器官健康方面发挥至关重要的作用。","c":"4","b":"第四版"},{"q":"抗原与抗体","a":"一般意义上的抗原，就是指侵入人体的病原体，包括细菌、病毒和微生物，而抗体是机 体针对抗原而产生的对抗性物质，即机体受到抗原刺激而产生的特异性糖蛋白（亦称免疫球 蛋白）","c":"o","b":"原题库补充 #173"},{"q":"免疫调理","a":"免疫调理是通过补充有助于保护和提升免疫功能的外源性物质（如维生素、微量元素、 抗氧化剂等），或通过医学手段（中医中药、激光照射等）保护或恢复免疫功能所用的各种 方法","c":"o","b":"原题库补充 #178"},{"q":"补体","a":"是指人与动物血清中正常存在的、与免疫有关的、并可具有酶活性的一组球蛋白。补体 并非单一物质，而是包含30 多种成分的血浆蛋白，故又称为补体系统","c":"o","b":"原题库补充 #179"},{"q":"细胞因子","a":"主要由淋巴细胞与单核-巨噬细胞所产生，习惯上称前者为淋巴因子，后者为单核因子， 实际上其他免疫细胞与非免疫细胞（包括神经细胞和内分泌细胞）也可以产生，故经称为细 胞因子。","c":"o","b":"原题库补充 #180"},{"q":"抗体","a":"是机体受到抗原刺激而产生的特异性糖蛋白，也称为免疫球蛋白","c":"o","b":"原题库补充 #444"}]},{"t":"第十二章 身体素质","items":[{"q":"身体素质","a":"通常将人体在肌肉活动过程中所表现出的力量、速度、耐力、柔韧性、平衡、协调性和灵敏等机能能力统称为身体素质。","c":"4","b":"第四版"},{"q":"力量素质","a":"力量素质是指肌肉工作时克服阻力或对抗负荷的能力。力量素质是实现人体各种运动的动力源，以及提高运动能力的基础。","c":"4","b":"第四版"},{"q":"肌肉生理横截面积","a":"肌肉生理横截面积是指垂直横切一块肌肉所有肌纤维所获得的横截面的面积之和，通常以cm2表示，其面积的大小取决于肌纤维的数量和直径。","c":"4","b":"第四版"},{"q":"中枢激活/中枢驱动","a":"中枢神经系统动员肌纤维参与收缩的能力称为中枢激活，也称为中枢驱动。","c":"4","b":"第四版"},{"q":"最大肌肉力量","a":"肌肉进行最大随意收缩时所表现出的克服极限负荷阻力的能力，称为最大肌肉力量。","c":"4","b":"第四版"},{"q":"等长肌力","a":"等长肌力是指肌肉收缩时在长度不变的情况下对抗阻力的静力性力量。","c":"4","b":"第四版"},{"q":"等张肌力","a":"等张肌力是指肌肉缩短和舒张交替进行的动力性力量。","c":"4","b":"第四版"},{"q":"等张最大肌力","a":"肌肉在进行最大的缩短和舒张交替收缩时的力量称为等张最大肌力，常用的评价方法有卧推、蹬腿、屈臂、负重蹲起等。","c":"4","b":"第四版"},{"q":"RM/最大重复次数","a":"RM即最大重复次数，是指肌肉克服某一重量/阻力能够完成的最高收缩次数，是力量训练计划中最常用的训练参数之一。","c":"4","b":"第四版"},{"q":"肌肉功率","a":"肌肉功率是指肌肉收缩时单位时间内所做的功。肌肉功率的大小与肌肉收缩时所产生的张力和收缩速度有关。","c":"4","b":"第四版"},{"q":"爆发力","a":"在克服一定阻力的条件下，机体能在极短的时间发挥出最大的肌张力称为爆发力，是速度力量的一种表现形式。","c":"4","b":"第四版"},{"q":"力量发展速率","a":"根据肌肉在爆发性主动收缩过程中记录的力量-时间曲线计算所得的单位时间内力量的变化，称为力量发展速率，是衡量肌肉爆发力的一个可靠指标。","c":"4","b":"第四版"},{"q":"肌肉耐力","a":"肌肉耐力是指肌肉以一定负荷或者一定速度收缩时，能够重复的次数或所能坚持的时间。","c":"4","b":"第四版"},{"q":"等长肌肉耐力","a":"肌肉在进行静力性收缩时，克服一定负荷所能坚持的收缩时间的长短称为等长肌肉耐力，如进行悬垂、倒立、马步等动作时所能保持的时间。","c":"4","b":"第四版"},{"q":"等张肌肉耐力","a":"肌肉在进行等张收缩时，克服一定负荷重量所能完成的最大练习次数，称为等张肌肉耐力。","c":"4","b":"第四版"},{"q":"等速肌肉耐力","a":"等速肌肉耐力是指肌肉在进行等速肌肉收缩时所能持续的时间。","c":"4","b":"第四版"},{"q":"延迟性肌肉疼痛","a":"延迟性肌肉疼痛是指在从事不适应的运动负荷或大负荷运动 24~72h 后，运动肌群产生不同程度的疼痛，伴随着僵硬、肿胀和肌力下降等症状的出现，且疼痛不发生在运动过程中和运动后即刻，而是在运动后24h逐渐加剧。","c":"4","b":"第四版"},{"q":"肌肉的牵张-收缩循环","a":"肌肉先被拉伸做离心收缩，再迅速转为向心收缩，是肌肉刺激一反应功能的自然属性。这种肌肉的收缩方式也被称为肌肉的牵张-收缩循环。","c":"4","b":"第四版"},{"q":"速度素质","a":"速度素质是指人体进行快速运动或最短时间完成某种运动的能力。按照其在运动中的表现，可分为反应速度、动作速度和位移速度等。","c":"4","b":"第四版"},{"q":"反应速度","a":"反应速度是指人体对各种刺激产生反应的快慢，反应速度的快慢主要取决于反应时的长短、中枢神经系统的机能状态和运动条件反射的巩固程度等。","c":"4","b":"第四版"},{"q":"反应时","a":"机体从感受器接受刺激开始，到引起效应器发生反应所需的时间，称为反应时。","c":"4","b":"第四版"},{"q":"动作速度","a":"动作速度是指完成单个动作时间的长短，如排球运动员扣球时挥臂的速度、投掷运动员器械出手的速度、足球运动员摆腿踢球的速度等都是典型的动作速度。","c":"4","b":"第四版"},{"q":"位移速度","a":"周期性运动中，人体在单位时间内通过的距离，或通过一定距离所需要的时间，称为位移速度。","c":"4","b":"第四版"},{"q":"周期性运动","a":"周期性运动通常是指周而复始地进行相同动作的运动，如跑步、游泳和骑自行车等。","c":"4","b":"第四版"},{"q":"简单反应时","a":"简单反应时是指测试时呈现一种刺激且固定不变，受试者对该刺激做出单一的反应的时间间隔。","c":"4","b":"第四版"},{"q":"选择反应时","a":"选择反应时是指测试时呈现两种或两种以上的刺激，要求受试者对每一种刺激做出不同反应所需的时间。","c":"4","b":"第四版"},{"q":"耐力","a":"耐力是指人体能够长时间进行工作的能力，依据运动时的外部表现与能量代谢属性可将耐力素质分为有氧耐力和无氧耐力。","c":"4","b":"第四版"},{"q":"有氧耐力","a":"人体能够长时间进行有氧工作的能力，即机体以有氧代谢供能为主进行长时间运动的能力，称为有氧耐力。","c":"4","b":"第四版"},{"q":"最大摄氧量","a":"最大摄氧量是指人体在进行有大量肌群参加的长时间剧烈运动中，当氧运输系统功能和肌肉利用氧的能力达到本人极限水平时，单位时间内所摄取的氧气量，其值可用绝对值和相对值两种方式表示。","c":"4","b":"第四版"},{"q":"乳酸阈","a":"在递增负荷运动中，血乳酸浓度随运动负荷的递增而增加，当运动强度达到某一负荷时，血乳酸浓度会急剧增加，血乳酸出现急剧增加的拐点，称为乳酸阈，其拐点所对应的运动强度即为乳酸阈强度。","c":"4","b":"第四版"},{"q":"个体乳酸阀","a":"将个体在渐增负荷中出现的乳酸拐点，称为个体乳酸阀。","c":"4","b":"第四版"},{"q":"通气阀","a":"碳酸解离出的H+可通过体内的化学感受器反射性地刺激呼吸中枢，加强肺通气，从而使得肺通气量突然升高，运动时肺通气量突增时的转折点，称为通气阀。","c":"4","b":"第四版"},{"q":"持续训练","a":"持续训练是指强度较低、持续时间较长且不间歇的有氧耐力训练。","c":"4","b":"第四版"},{"q":"个体乳酸阀强度","a":"个体乳酸阀强度是发展有氧耐力训练的有效强度，用该强度进行训练能显著提高机体的有氧耐力水平。","c":"4","b":"第四版"},{"q":"间歇训练","a":"间歇训练是指在两组训练之间有适当的间歇时间，并要求在间歇期进行强度较低的运动来代替静止休息。","c":"4","b":"第四版"},{"q":"高原训练","a":"高原训练是指有目的、有计划地将运动员组织到具有适宜海拔高度的地区进行定期的专项运动训练。","c":"4","b":"第四版"},{"q":"无氧耐力","a":"无氧耐力是指机体在糖无氧酵解供能的情况下，较长时间地进行肌肉活动的能力。","c":"4","b":"第四版"},{"q":"最大氧亏积累","a":"氧亏积累可由运动过程中测量的需氧量积累和总摄氧量之差来确定，在超最大强度疲劳性运动中氧亏积累达到最大值，该值称为最大氧亏积累。","c":"4","b":"第四版"},{"q":"最大乳酸训练","a":"最大乳酸训练是指机体在运动中血乳酸水平达到最高时的训练。","c":"4","b":"第四版"},{"q":"乳酸耐受训练","a":"乳酸耐受训练是指机体处于较高乳酸水平时仍坚持较高强度运动的训练。","c":"4","b":"第四版"},{"q":"柔韧素质/柔韧性","a":"人体关节活动幅度的大小，以及跨关节的韧带、肌腱、肌肉等组织的弹性和伸展能力，称为柔韧素质，又称为柔韧性。","c":"4","b":"第四版"},{"q":"静态柔韧素质","a":"静态柔韧素质是柔韧素质的基础，测试简单、利于评价、易于普及和应用，在健身实践中常以其代表柔韧素质，其核心测试指标为坐位体前屈。","c":"4","b":"第四版"},{"q":"一般性柔韧素质","a":"一般性柔韧素质是指机体中最主要的关节活动的幅度，如肩、膝、髋等关节。","c":"4","b":"第四版"},{"q":"专门性柔韧素质","a":"专门性柔韧素质是指掌握专项运动技术所需要的特殊柔韧素质。","c":"4","b":"第四版"},{"q":"关节的活动幅度","a":"关节的活动幅度是指关节围绕各个运动轴在相应平面活动的角度范围。","c":"4","b":"第四版"},{"q":"平衡","a":"平衡是指人体在静态和动态活动中对抗重力与外力的作用保持身体重心稳定的能力。","c":"4","b":"第四版"},{"q":"静态平衡","a":"静态平衡是指人体在相对静止的状态下维持身体重心稳定和肢体空间定位的能力，如金鸡独立、燕式平衡、站桩等动作。","c":"4","b":"第四版"},{"q":"动态平衡","a":"动态平衡是指在动态过程中调整、控制身体姿势和维持重心稳定的能力，如蹦床、游泳与花样滑冰等均需要很好的动态平衡能力。","c":"4","b":"第四版"},{"q":"自动态平衡","a":"自动态平衡也称为主动平衡，即人体在进行各种自主运动时（如由坐到站、由站到坐的姿势转换），能重新获得稳定状态的能力。","c":"4","b":"第四版"},{"q":"他动态平衡","a":"他动态平衡也称为被动平衡，即人体在受到外界施加的力（如推、拉等）时，产生反应、恢复稳定状态的能力。","c":"4","b":"第四版"},{"q":"协调素质","a":"在中枢神经系统控制下，与特定动作相关的肌群以一定的时空关系共同工作，从而产生平稳、准确、有控制的运动的一种能力，称为协调素质。","c":"4","b":"第四版"},{"q":"灵敏素质","a":"灵敏素质是指机体为完成预定目标或应对突然变化的环境，能够迅速、准确、协调地改变身体运动的空间位置和运动方向，以获得适宜的运动表现的能力。","c":"4","b":"第四版"},{"q":"一般灵敏性","a":"一般灵敏性是指在日常生活和体育运动中基础性动作变换的能力，如起动、急停、起跳、躲闪、维持平衡和改变动作姿态等。","c":"4","b":"第四版"},{"q":"专项灵敏性","a":"专项灵敏性是指运动员在专项运动中，迅速、准确、协调自如地完成本专项各种技术动作的能力。不同的项目对运动员的专业技能要求有较大差异，对灵敏素质的要求也不同。","c":"4","b":"第四版"},{"q":"快速肌肉力量","a":"肌肉在短时间内快速发挥力量的能力，称为快速肌肉力量，亦可称为爆发力","c":"o","b":"原题库补充 #258"},{"q":"力量耐力","a":"力量耐力是指肌肉长时间对抗阻力的能力","c":"o","b":"原题库补充 #259"},{"q":"肌肉生理横断面积","a":"垂直横切某块肌肉中所有肌纤维获得的横断面积，称为肌肉生理横断面积。它的大小是 由肌纤维的数量和直径决定的，通常以平方厘米表示","c":"o","b":"原题库补充 #262"},{"q":"复合超等长力量训练","a":"在超等长练习之前先进行短暂的大强度负重刺激，有助于更大程度地动员运动单位参与 随后的运动，从而强化超等长练习的效果，此练习方法称为复合超等长力量训练","c":"o","b":"原题库补充 #263"},{"q":"核心力量","a":"核心力量是指附着在人体核心部位的肌肉收缩产生的力量。核心力量训练是指针对身体 核心肌群及深层小肌肉进行的力量训练，旨在提高力量的传递、协调和控制肌肉的能力","c":"o","b":"原题库补充 #264"},{"q":"缺氧训练","a":"缺氧训练是指机体在低于正常氧分压环境下进行的训练，其目的是为了造成体内缺氧以 提高无氧能力","c":"o","b":"原题库补充 #270"},{"q":"需氧量","a":"是指机体为维持某种生理活动所需要的氧量。可由两个变量决定：单位时间内的需氧量 和总的需氧量","c":"o","b":"原题库补充 #271"},{"q":"摄氧量","a":"通常将单位时间内机体能够摄取并利用的氧量称为摄氧量,也称为耗氧量","c":"o","b":"原题库补充 #272"},{"q":"氧亏","a":"在运动过程中，当机体能够摄取的氧量不能满足实际需要的氧量时，造成体内氧量的亏 欠，称为氧亏","c":"o","b":"原题库补充 #273"},{"q":"运动后过量氧耗","a":"运动结束后一段时间，肌肉活动虽然停止，但机体的摄氧量并不能立即恢复到运动前安 静时的水平，机体的耗氧水平高于运动前(或安静状态)耗氧水平，称为运动后过量氧耗","c":"o","b":"原题库补充 #274"},{"q":"灵敏","a":"是运动者迅速改变体位、转换动作和随机应变的能力。它是运动员运动技能和各种运动 能力在运动过程中的综合表现","c":"o","b":"原题库补充 #282"},{"q":"柔韧","a":"是人体在运动过程中完成大幅度动作的能力，即关节的主动或被动活动范围","c":"o","b":"原题库补充 #283"},{"q":"协调","a":"是指人体在运动过程中身体各器官、系统在时间和空间上相互配合完成动作的能力。","c":"o","b":"原题库补充 #284"},{"q":"核心稳定性","a":"核心稳定性是指核心区的联合稳定程度，对运动能力的发挥非常重要","c":"o","b":"原题库补充 #285"},{"q":"振动训练","a":"振动训练是指利用振动仪改变垂直方向加速度产生额外负荷进行身体训练的方法，称为 振动训练","c":"o","b":"原题库补充 #286"},{"q":"呼吸肌训练","a":"通过增加呼吸阻力的方式增强呼吸肌工作能力，以增强运动能力、提高运动成绩的一种 训练方法称为呼吸肌训练","c":"o","b":"原题库补充 #287"},{"q":"低氧训练","a":"利用人工低氧环境进行训练，提高运动员有氧能力的方法称为低氧训练。","c":"o","b":"原题库补充 #288"},{"q":"延迟性酸痛","a":"运动停止后运动肌会产生不同程度的酸痛，并伴随僵硬、肿胀和肌力下降等症状，肌肉 酸痛不发生在运动期间或运动后即刻，而是在运动后24h 开始逐渐加剧，因而称为延迟性肌 肉酸痛","c":"o","b":"原题库补充 #356"},{"q":"有氧/无氧工作能力","a":"机体在有氧代谢供能情况下进行肌肉活动的能力，称为有氧工作能力；机体在无氧代谢 供能情况下进行肌肉活动的能力，称为无氧工作能力","c":"o","b":"原题库补充 #451"},{"q":"乳酸阈强度训练法","a":"个体乳酸阈强度是发展有氧耐力训练的最佳强度。以此强度进行耐力训练，能显著提高 有氧工作能力","c":"o","b":"原题库补充 #452"},{"q":"绝对肌力","a":"绝对肌力是指肌肉做最大随意收缩时所能产生的张力，通常用肌肉收缩时所能克服的最 大阻力负荷来表示","c":"o","b":"原题库补充 #455"},{"q":"相对肌力","a":"相对肌力又叫作比肌力，是指单位生理横断面积的肌肉做最大收缩时所能产生的肌张力","c":"o","b":"原题库补充 #456"},{"q":"肌肉爆发力","a":"肌肉爆发力是指肌肉在短时间内发挥力量的能力，通常用肌肉单位时间的做功量来表示","c":"o","b":"原题库补充 #457"}]},{"t":"第十三章 运动技能的形成","items":[{"q":"运动技能","a":"运动技能是指人体在运动过程中通过学习而获得的专门技术动作能力，它是在大脑皮质信息整合下完成的一系列外周肌肉活动。","c":"4","b":"第四版"},{"q":"基本运动技能","a":"基本运动技能包括位移技能，如走、跑、跳等，非位移技能包括扭转、屈曲、伸展等，操作技能包括投掷、传接、攀爬等，基本运动技能是专项运动技能的基础。","c":"4","b":"第四版"},{"q":"专项运动技能","a":"专项运动技能是指特定的运动项目中所需要的技能，如篮球、体操、游泳等项目的技术。","c":"4","b":"第四版"},{"q":"小肌群运动技能","a":"小肌群运动技能是指由小肌群高度控制产生的动作，通常需要手眼配合且动作精细度较高，如排球传球时手指对球的弹拨、扣球时手腕对球的推压；","c":"4","b":"第四版"},{"q":"大肌群运动技能","a":"大肌群运动技能则是指由大肌群高度控制产生的动作，多由躯干或下肢肌肉产生，如羽毛球运动中扣球及扣杀中的腾空动作。","c":"4","b":"第四版"},{"q":"开放式运动技能","a":"开放式运动技能环境不断变化且不可预见，外界环境刺激因素较多，如球类、摔跤、击剑等，这些项目要求运动员充分利用各类感受器、快速进行感觉信息整合，并对外界环境变化迅速作出反应。","c":"4","b":"第四版"},{"q":"闭锁式运动技能","a":"闭锁式运动技能动作环境相对稳定且可预见，项目多为重复性动作，反馈信息主要来自本体感受器，如游泳、举重、太极拳等。","c":"4","b":"第四版"},{"q":"经典条件反射","a":"经典条件反射是俄国生理学家巴甫洛夫提出的，机体对条件刺激的一种习得性反应称为经典条件反射。","c":"4","b":"第四版"},{"q":"操作条件反射","a":"操作条件反射是由美国行为心理学家斯金纳提出的，是一种动物学会将一个动作反应与奖励或惩罚相联系的行为。","c":"4","b":"第四版"},{"q":"条件反射的泛化","a":"在条件反射形成的初期，除条件刺激本身外，与该条件刺激相似的刺激也可引起条件反射，这种现象称为条件反射的泛化。","c":"4","b":"第四版"},{"q":"分化抑制","a":"分化的形成是由大脑皮质抑制过程的建立所致，那些近似刺激的皮质代表区由于得不到非条件刺激的强化而进入抑制过程，这种抑制称为分化抑制。","c":"4","b":"第四版"},{"q":"泛化阶段","a":"在运动技能形成的初期，学习者对动作仅有感性认识，表现出不协调、不连贯的技术特征，该阶段称为泛化阶段。","c":"4","b":"第四版"},{"q":"分化阶段","a":"随着运动技能的不断重复练习，中枢的兴奋和抑制过程逐渐集中，特别是分化抑制得到发展，建立的神经联系得到了强化，表明运动技能已从泛化阶段进入了分化阶段。","c":"4","b":"第四版"},{"q":"巩固阶段","a":"当运动技能进入分化阶段后，中枢神经系统内的兴奋和抑制在时间和空间上更加集中，对肌肉收缩和舒张的控制更加精确，条件反射不断得到巩固，该阶段称为巩固阶段。","c":"4","b":"第四版"},{"q":"自动化阶段","a":"当运动技能进入巩固阶段后，大脑皮质中兴奋和抑制高度集中，运动条件反射已非常牢固，练习者在强化过程中可下意识地完成技术动作，达到了自动化程度，该阶段即称为自动化阶段。","c":"4","b":"第四版"},{"q":"反馈","a":"反馈是指在反应过程中产生的输出信息又返回到输入信息中去，通过中枢神经系统调整，使再次输出的信息更为精确。","c":"4","b":"第四版"},{"q":"学习的迁移","a":"学习的迁移是指已获得的学习经验对后来学习的影响，是学习过程中普遍存在的现象，起促进作用的迁移称为正迁移或良性迁移；起妨碍作用的迁移称为负迁移或劣性迁移。","c":"4","b":"第四版"},{"q":"正迁移","a":"若原有技能对新技能学习起积极作用，同时有助于原有技能的巩固和完善，就是正迁移。","c":"4","b":"第四版"},{"q":"负迁移","a":"若原有技能对新技能学习起阻碍或干扰作用，或破坏原有技能就是负迁移。","c":"4","b":"第四版"},{"q":"运动动力定型","a":"在形成运动条件反射过程中，各有关中枢的兴奋和抑制在大脑皮质中按照严格的时间间 隔和顺序出现，形成固定化的暂时性神经联系，这种固定化的格式称为运动动力定型","c":"o","b":"原题库补充 #308"},{"q":"第一信号系统","a":"对第一信号发生反应的大脑皮质功能系统称为第一信号系统","c":"o","b":"原题库补充 #309"},{"q":"第二信号系统","a":"对第二信号发生反应的大脑皮质功能系统称为第二信号系统。","c":"o","b":"原题库补充 #310"},{"q":"离散技能","a":"指运动持续时间很短的行为，例如投球、射击等。离散技能在一些以击打、踢和投掷等 动作为主导的运动和日常行动中发挥重要作用","c":"o","b":"原题库补充 #448"},{"q":"连续技能","a":"连续技能是指没有特定开始或结束，并且持续时间较长的运动技能，例如游泳、竞走等","c":"o","b":"原题库补充 #449"},{"q":"串联技能","a":"串联技能通常介于离散技能和连续技能之间，是由一系列连续的离散技能组合在一起构 成的一个具有更复杂行为的运动技能，例如体操等。","c":"o","b":"原题库补充 #450"}]},{"t":"第十四章 运动过程中的身体机能变化","items":[{"q":"赛前状态","a":"在参加正式比赛或训练前，机体产生的一系列条件反射性和压力反应性变化，称为赛前状态。","c":"4","b":"第四版"},{"q":"赛前冷淡","a":"赛前冷淡是由于赛前过度紧张使中枢神经系统持续性兴奋引起大脑产生保护性抑制，导致中枢神经系统兴奋性整体下降，常表现为情绪低落、全身无力、反应迟钝、对比赛淡漠、主观上不愿意参加比赛或训练等生理与心理的消极状态。","c":"4","b":"第四版"},{"q":"压力","a":"压力通常是指一种真实的或可被感知的肉体上或情感上的干扰，它能改变内稳态，导致中枢神经系统和周围器官所介导的应激反应，以恢复或重建内稳态。","c":"4","b":"第四版"},{"q":"心率变异性","a":"心率变异性是指逐次心动周期之间的微小差异，其生理机制是血压波动通过动脉压力反射导致的心率波动。","c":"4","b":"第四版"},{"q":"准备活动","a":"准备活动也称为热身，是指在训练和比赛之前进行的各种有目的、有计划的身体练习。","c":"4","b":"第四版"},{"q":"动态热身","a":"动态热身是指与训练内容和运动专项相适应的一组动态动作练习。","c":"4","b":"第四版"},{"q":"赛前减量训练/尖峰状态训练","a":"赛前减量训练是指为降低运动员的生理和心理疲劳，促进机体恢复并产生良好适应，使运动员达到最佳竞技状态和提高比赛能力的赛前准备性训练，又称为尖峰状态训练。","c":"4","b":"第四版"},{"q":"进入工作状态","a":"在运动初始阶段，人体各器官、系统的机能并不是立刻达到最高水平，而是有一个逐步提高的过程，称为进入工作状态。","c":"4","b":"第四版"},{"q":"极点","a":"在进行强度较大、持续时间较长的剧烈运动中，由于初始阶段内脏器官的机能不能满足运动器官的需要，练习者常常产生一些难以忍受的生理反应，如呼吸困难、胸闷、头晕、心率剧增、肌肉酸痛无力、动作迟缓不协调，甚至产生停止运动的念头等，这种机能状态称为“极点”。","c":"4","b":"第四版"},{"q":"第二次呼吸","a":"“极点”出现后，如果依靠意志力或调整运动节奏继续坚持运动，机体这些不良生理反应便会逐渐减轻或消失，此时呼吸变得均匀自如，动作变得轻松有力，运动员能以较好的机能状态继续运动下去，这种状态称为“第二次呼吸”。","c":"4","b":"第四版"},{"q":"植物神经","a":"支配骨骼肌的神经系统是躯体神经，支配内脏器官的神经系统是自主神经，又称为植物神经。","c":"4","b":"第四版"},{"q":"稳定状态","a":"稳定状态是指运动时当进入工作状态结束后，人体机能活动在一段时间内保持在一个相对较高的稳定水平。此阶段人体的生理机能与运动输出功率保持相对稳定。","c":"4","b":"第四版"},{"q":"真稳定状态","a":"在进行中小强度的长时间运动时，进入工作状态结束后，内脏器官的生理惰性被克服，机体所需的氧可以得到满足，即摄氧量和需氧量保持动态平衡，这种状态称为真稳定状态。","c":"4","b":"第四版"},{"q":"假稳定状态","a":"在进行运动强度较大、持续时间较长的运动时，进入工作状态结束后，机体的摄氧量已达到并稳定在最大摄氧量水平，但仍不能满足机体对氧的需求，氧亏逐渐增多，这种状态称为假稳定状态。","c":"4","b":"第四版"},{"q":"无氧阀","a":"无氧阀是指机体由有氧代谢供能为主过渡到无氧代谢供能为主的临界点，表现的方式有乳酸无氧阔、通气无氧阀和心率无氧阀等。","c":"4","b":"第四版"},{"q":"无氧阀强度","a":"无氧阀强度是指机体进行有氧运动的最大运动强度。","c":"4","b":"第四版"},{"q":"运动性疲劳","a":"运动过程中机体生理过程不能继续保持在特定水平上进行和（或）不能维持预定的运动强度的生理状态，称为运动性疲劳。","c":"4","b":"第四版"},{"q":"体力疲劳","a":"在体育活动中体力疲劳非常普遍，如剧烈运动后出现的肌肉酸痛、周身乏力、身体活动能力下降均属于体力疲劳症状。","c":"4","b":"第四版"},{"q":"神经疲劳","a":"以脑力活动为主的运动可导致神经疲劳，表现为头昏脑涨、思维迟钝、注意力不集中、记忆力下降、错误动作增多等。","c":"4","b":"第四版"},{"q":"心理疲劳/精神疲劳","a":"心理/精神疲劳主要是指内外环境不良刺激引起情志低落、厌倦、对立等心理反应，表现为对任何事物都没有兴趣，办事效率降低等。","c":"4","b":"第四版"},{"q":"中枢疲劳","a":"中枢疲劳是指发生在中枢部位的疲劳，即发生在大脑运动皮质对运动神经元的驱动、脊随神经冲动传导至骨骼肌，以及两者之间的过程或部位的疲劳。","c":"4","b":"第四版"},{"q":"外周疲劳","a":"外周疲劳是指发生在神经-肌肉接头、肌细胞膜、线粒体、肌质网和肌肉收缩蛋白等部位的疲劳。","c":"4","b":"第四版"},{"q":"整体性疲劳","a":"整体性疲劳是指由全身运动引起的机体调控机能和多器官机能下降导致的疲劳，如马拉松、铁人三项、足球比赛等。","c":"4","b":"第四版"},{"q":"局部性疲劳","a":"局部性疲劳是指以身体某一局部持续运动导致的局部器官或组织机能下降，如局部的肌肉训练和专门动作练习等。","c":"4","b":"第四版"},{"q":"快速性疲劳","a":"快速性疲劳是指较大强度剧烈运动引起的机能下降，如短跑、投掷和跳跃等，这种疲劳产生快，消除也相对较快。","c":"4","b":"第四版"},{"q":"慢速性疲劳","a":"慢速性疲劳是小强度、较长时间的运动导致的身体机能下降，该疲劳产生缓慢，消除也相对缓慢。","c":"4","b":"第四版"},{"q":"皮肤空间阀值","a":"对不同空间位置的皮肤给予感觉刺激时，人体能够辨别出的皮肤两点间的最小距离称为皮肤空间阀值。","c":"4","b":"第四版"},{"q":"闪光融合频率","a":"当断续的光刺激达到一定频率时，能引起连续感觉时的光刺激频率，称为闪光融合频率。","c":"4","b":"第四版"},{"q":"恢复过程","a":"人体在运动过程中及运动结束后，生理机能和能源物质逐渐恢复与提高的过程，称为恢复过程。","c":"4","b":"第四版"},{"q":"超量恢复","a":"运动中消耗的能源物质在运动后的一段时间内不仅恢复到原来水平，甚至超过原来水平，这种现象称为超量恢复。超量恢复保持一段时间后就会再回到原来水平。","c":"4","b":"第四版"},{"q":"整理活动","a":"整理活动是指运动后进行的各种较为轻松的身体练习，其目的是消除疲劳，促进体力恢复。","c":"4","b":"第四版"},{"q":"积极性休息","a":"运动结束后为了消除疲劳而采取的各种变换动作或运动强度的练习，称为积极性休息。","c":"4","b":"第四版"},{"q":"脱训","a":"又称停训，是指由于运动训练停止或运动负荷减少，使先前训练所产生的解剖、生理适 应和提高的运动成绩完全或部分消退","c":"o","b":"原题库补充 #297"},{"q":"运动性力竭","a":"当运动性疲劳继续发展，身体和心理均达到疲惫程度时，就会出现运动性力竭或过度疲 劳。后者可能会造成机体损伤以致损害健康","c":"o","b":"原题库补充 #300"},{"q":"自由基","a":"自由基是指外层电子轨道含有未配对电子的原子、离子或分子","c":"o","b":"原题库补充 #301"},{"q":"主观感觉判断","a":"在运动时，来自肌肉、呼吸、痛觉和心血管等各方面的刺激，都会传到大脑皮质，而引 起大脑感觉系统的应激，这一应激过程称为主观感觉判断","c":"o","b":"原题库补充 #304"},{"q":"去极点","a":"极点出现后，运动者继续坚持运动，一些不良的生理反应逐渐减轻或消失，这种现象称 为去极点。这时呼吸会变得均匀自如，心率趋于稳定，动作变得轻松有力，能以较好的机能 状态继续运动","c":"o","b":"原题库补充 #464"}]},{"t":"第十五章 年龄、性别与运动","items":[{"q":"生长","a":"生长是指组织器官的不断增长，细胞不断增殖的过程。","c":"4","b":"第四版"},{"q":"发育","a":"发育是指各器官组织细胞的功能不断分化，机能逐渐成熟的过程。","c":"4","b":"第四版"},{"q":"生长发育","a":"个体的生长发育是一个长期复杂的过程，是机体在形态和机能方面逐步完善的连续过程。","c":"4","b":"第四版"},{"q":"青春期","a":"青春期是指从出现第二性征到性成熟的生理发育过程。","c":"4","b":"第四版"},{"q":"青春期生长突增","a":"到青春期早期，会迎来第二次生长突增期，也称为青春期生长突增，约持续三年。","c":"4","b":"第四版"},{"q":"青春期高血压","a":"青春发育期后，心脏发育速度加快，血管发育处于相对落后状态，加之内分泌功能的影响，如性腺、甲状腺等分泌旺盛，使血压明显升高，一些人甚至出现暂时偏高的现象，称为青春期高血压。","c":"4","b":"第四版"},{"q":"身体素质的自然增长","a":"儿童少年各项身体素质随着年龄的增长而增长的现象，称为身体素质的自然增长。","c":"4","b":"第四版"},{"q":"停滞阶段","a":"女生的身体素质在快速增长阶段和缓慢增长阶段之间可能出现数年停滞的现象，称为停滞阶段。","c":"4","b":"第四版"},{"q":"稳定阶段","a":"在增长阶段之后身体素质趋于稳定，称为稳定阶段，表现为身体素质发展速度明显变慢或停滞，甚至有所下降。","c":"4","b":"第四版"},{"q":"身体素质的敏感期","a":"在儿童少年身体素质的发展过程中，不仅存在着一个连续的、增长速度较快的快速增长期，而且还存在着一个或几个增长速度特别快的连续年龄段或年龄点，将其称为该项身体素质的敏感期。","c":"4","b":"第四版"},{"q":"身体素质发展的顺序性","a":"在儿童少年身体素质增长过程中，由于各种素质增长的速度不同，即出现高峰的时间有早有晚，表现出增长的顺序有先有后，这一特性称为身体素质发展的顺序性。","c":"4","b":"第四版"},{"q":"骨质疏松","a":"60岁以上的老年人因骨无机盐的丢失及多孔疏松，会导致骨质量减少30%~50%，进而表现为骨质疏松。","c":"4","b":"第四版"},{"q":"高黏滞血症","a":"老年人血液变化特征呈现出浓、黏、聚和凝等状态，临床上称为高黏滞血症。","c":"4","b":"第四版"},{"q":"月经","a":"女性性成熟后，因子宫内膜脱落，发生阴道流血现象，称为月经。","c":"4","b":"第四版"},{"q":"月经周期","a":"每次出血的第1日为月经周期的开始，两次月经第1日的间隔时间，称为月经周期，每个周期一般为28天。","c":"4","b":"第四版"},{"q":"痛经","a":"痛经是由月经期及其前后出现下腹部疼痛、坠胀，或伴有其他不适，症状严重影响生活质量者。可分为原发性和继发性痛经两种类型。","c":"4","b":"第四版"},{"q":"原发性痛经","a":"原发性痛经是指生殖器官无器质性病变的痛经。","c":"4","b":"第四版"},{"q":"继发性痛经","a":"继发性痛经是指盆腔器质性疾病，如子宫内膜异位症、子宫腺肌症等引起的痛经。","c":"4","b":"第四版"},{"q":"运动性闭经","a":"运动性闭经是由运动引起的一种严重的月经失调，其发生率一般女性为5%~20%，优秀运动员可高达40%~50%。产生的原因主要是雕激素分泌减少。","c":"4","b":"第四版"},{"q":"女运动员三联征","a":"女运动员三联征是指女运动员的能量利用、骨骼健康和月经失调之间相互关联、相互影响的一种医学症候群。","c":"4","b":"第四版"},{"q":"绝经","a":"绝经是指月经的永久性停止，属回顾性临床诊断。40岁以上的女性停经12个月，排除妊娠及其他可能导致闭经的疾病后，即可临床诊断为绝经。","c":"4","b":"第四版"},{"q":"绝经综合征","a":"在绝经前后的一系列相关症状统称为绝经综合征（旧称为更年期综合征）。","c":"4","b":"第四版"},{"q":"敏感期","a":"在身体素质的发展过程中，不仅存在着一个连续的、增长速度较快的快速增长期，而且 还存在着一个或几个增长速度特别快的连续年龄段或年龄点，这个年龄段或年龄点称为该项 身体素质的敏感期","c":"o","b":"原题库补充 #312"},{"q":"青春发育期","a":"青春发育期是儿童发育为成人的过渡期，年龄范围在10~20 岁之间，也是生长发育的关 键时期，机体在形态和机能等方面达到成人水平","c":"o","b":"原题库补充 #313"},{"q":"青春性高血压","a":"青春发育期后，心脏发育速度增快，血管发育处于落后状态，同时由于性腺、甲状腺等 分泌旺盛引起的血压升高，称为青春性高血压","c":"o","b":"原题库补充 #314"},{"q":"运动性月经失调","a":"由于运动训练引起体重降低、精神应激等因素导致女运动员正常月经周期出现一定的紊 乱、称为运动性月经失调","c":"o","b":"原题库补充 #317"},{"q":"妊娠","a":"妊娠是新个体的产生和孕育的生理过程。包括：受精及受精卵发育、输送与着床、妊娠 的维持及其激素调节和胎儿的生长等环节","c":"o","b":"原题库补充 #318"},{"q":"衰老","a":"衰老又称老化，是生物体自成熟期开始，随增龄发生的、渐进的、受遗传因素影响的、 全身复杂的形态结构与生理功能发生不可逆的退行性变化，具有普遍性、内因性、进行性、 累积性及有害性等特点。衰老是生物体生命过程中不可避免的阶段。","c":"o","b":"原题库补充 #319"},{"q":"成熟","a":"是指生长发育过程达到一个比较完备的阶段，标志着个体发育在形态、生理、心理方面 全面达到成人阶段。上述过程主要受遗传因素，以及营养、疾病、季节气候、体育锻炼等因 素共同影响，表现出连续发展、阶段发展的特点，在不同阶段均是由量变到质变的完整过程。","c":"o","b":"原题库补充 #473"}]},{"t":"第十六章 运动训练的生理学基础","items":[{"q":"运动训练的科学性","a":"运动训练的科学性是指在训练过程中所实施的训练刺激必须高度地符合人体反应和适应的基本规律。","c":"4","b":"第四版"},{"q":"运动训练额艺术性","a":"运动训练额艺术性是指训练过程必须紧密结合运动员的特征精心安排负荷强度、负荷总量、训练密度、训练频率、训练周期等训练要素，通过高度个性化的训练方案使运动员的身体机能发生所预期的应答性反应和适应性变化。","c":"4","b":"第四版"},{"q":"运动刺激","a":"运动刺激是通过训练课来施加的，包括训练内容、负荷强度、每种练习的次数与组数，以及间歇方式、总持续时间、总运动量和恢复方式等。","c":"4","b":"第四版"},{"q":"结构重建","a":"机体在对运动刺激产生应答性反应的过程中，运动系统和呼吸循环系统等的结构发生了一定程度的破坏，而在恢复期中所破坏的结构不仅得到恢复，且会得到一定程度的改善，这种现象称为结构重建。","c":"4","b":"第四版"},{"q":"机能重建","a":"结构重建后身体机能得到的相应提高，称为机能重建。","c":"4","b":"第四版"},{"q":"超量补偿/超量恢复","a":"在恢复阶段若安排有足够的恢复时间，在身体结构和机能重建完成后，运动中所消耗的能源物质，以及降低的身体机能水平不仅能得以恢复，而且会超过原有水平，这种现象称为超量补偿或超量恢复。","c":"4","b":"第四版"},{"q":"训练效果","a":"由于超量补偿所导致的机能改善，称为训练效果。","c":"4","b":"第四版"},{"q":"过度训练/过度疲劳","a":"机体对不适宜的运动负荷刺激，也可产生适应性变化，只是所产生变化的结果并非运动能力的提高，而是发生过度训练或过度疲劳，这种现象则属于不良反应。","c":"4","b":"第四版"},{"q":"超负荷原则","a":"超负荷原则是指当运动员对某一负荷刺激基本适应后，必须适时、适量地增大负荷使之超过原有负荷，运动能力才能继续增长。","c":"4","b":"第四版"},{"q":"超负荷","a":"当机体的运动能力不再随着继续施加同一负荷继续提高，而只能得以保持，要想继续提高运动效果，只有在原有刺激强度的基础上再增加负荷强度，即所谓的超负荷。","c":"4","b":"第四版"},{"q":"运动潜能","a":"由于受遗传因素制约，每个人的运动能力都有一个可达到的最高高度，即运动潜能。","c":"4","b":"第四版"},{"q":"运动能力发展的递减性原则","a":"运动员在开始接受运动训练时，运动成绩提高较快，而到达高水平后，成绩提高速度会逐渐减慢，甚至停滞不前，这种现象称为“运动能力发展的递减性原则”。","c":"4","b":"第四版"},{"q":"恢复性原则","a":"恢复性原则是指在长期的运动训练过程中，只有当运动员机体得到适宜的恢复，才能获得理想的训练效果。","c":"4","b":"第四版"},{"q":"周期性原则","a":"周期性原则是指将运动员的多年训练计划划分为时间长度不一的各种周期，每个周期赋予不同的训练目标，训练过程在不同层次上周而复始地循环。","c":"4","b":"第四版"},{"q":"个体化原则","a":"个体化原则是指教练员在制订训练计划时，必须严格按照每个运动员所独具的身体能力、潜质、学习特征及从事的专项等特点，设计出适合每个运动员特点的个体化方案。","c":"4","b":"第四版"},{"q":"血氧饱和度","a":"血氧饱和度是指与氧结合的血红蛋白量占血红蛋白总量的百分比。","c":"4","b":"第四版"},{"q":"运动性蛋白尿","a":"当运动训练导致肾小球滤过膜完整性受损，一些分子质量较大的蛋白质分子会通过滤过膜进入原尿且超过肾小管重吸收阀值，尿中蛋白质浓度增加，出现蛋白尿，也称为运动性蛋白尿。","c":"4","b":"第四版"},{"q":"无氧阈/乳酸阀","a":"无氧阈（乳酸阀）是指递增强度运动过程中，达到某一强度后，需氧量大于摄氧量，细胞仍以有氧代谢为主，但开始动员无氧代谢供能的运动强度临界点。","c":"4","b":"第四版"},{"q":"乳酸无氧阈强度","a":"血乳酸开始急剧增加的拐点强度称为乳酸无氧阈强度。","c":"4","b":"第四版"},{"q":"通气无氧阀强度","a":"肺通气开始急剧增加的拐点称为通气无氧阀强度。","c":"4","b":"第四版"},{"q":"无氧功","a":"无氧功又称为无氧功率，是指机体在较短时间内，以无氧代谢系统供能的极限工作能力。","c":"4","b":"第四版"},{"q":"等速运动","a":"等速运动是指在关节活动的过程中，通过等速测试设备的自动调节对运动关节施加一定的阻力，使被测试关节按照预先设定的角速度进行运动。","c":"4","b":"第四版"},{"q":"肌电图","a":"肌电图是将单个或多个骨骼肌细胞活动时的生物电变化加以引导、放大、显示和记录所获得的一维时间序列图形。","c":"4","b":"第四版"},{"q":"高原习服","a":"机体暴露于高原低氧环境后，机体会从整体水平调动其内在机制发生一系列的代偿适应性变化以应对高原低氧环境，使机体内环境由不平衡到平衡，这一过程称为高原习服。","c":"4","b":"第四版"},{"q":"高住低训","a":"高住低训是指运动员在较高海拔的自然高原条件下居住，而在较低海拔的自然条件下训练的方法。","c":"4","b":"第四版"},{"q":"间歇性低氧训练","a":"间歇性低氧训练是利用低氧仪在平原条件下模拟不同海拔高度的高原低氧环境，对运动员进行间歇性（脉冲式）的低氧刺激，以提高机体的有氧代谢能力和抗缺氧能力的一种新的科学训练方法。","c":"4","b":"第四版"},{"q":"冷环境","a":"冷环境一般是指气温在0℃以下或者更低的环境。在这种环境中长时间训练，会引发机体散热增加、周围血管收缩以致皮下组织血流减少、肌肉的黏滞性增加，从而导致其收缩能力下降且极易发生损伤。","c":"4","b":"第四版"},{"q":"冷应激","a":"人体为对抗外界冷环境引起的热量散失而产生的一系列紧张性防御生理反应，称为冷应激。","c":"4","b":"第四版"},{"q":"低温习服/冷习服","a":"人体在低温条件下经过一定时期的锻炼，会对低温产生一定的适应，即对低温的耐受性提高，对低温发生的生理反应减轻，这种现象称之为寒冷的适应，医学上称为“低温习服”或“冷习服”。","c":"4","b":"第四版"},{"q":"热环境","a":"气温在 32℃以上或温度更高的环境称为热环境。在热环境条件下长时间训练，可能会因体表散热不足和失水而形成体内热淤积进而发生中暑、热痉挛和热衰竭等热疾患。","c":"4","b":"第四版"},{"q":"热应激","a":"人体为对抗外界热环境而产生的一系列防御性生理反应称为热应激。","c":"4","b":"第四版"},{"q":"热习服","a":"若长期或反复居留在高温环境中，人体会逐渐适应热刺激，对抗热应激的稳定性得到发展，对炎热的耐受能力提高，出现热适应状态，这种状态称为热习服。","c":"4","b":"第四版"},{"q":"水环境训练","a":"水环境训练是指人体在水中运动时，充分利用水的物理特性做主动运动的特定训练方法。","c":"4","b":"第四版"},{"q":"体温调节","a":"在人体体温调节系统的调控下，通过机体的产热和散热，以实现人体体温的相对恒定， 称体温调节","c":"o","b":"原题库补充 #326"},{"q":"高原适应","a":"当人体在高原居住几天（或几周）后，机体对较低的氧分压进行了相应的调整，产生了 一定程度的适应现象，称为高原适应","c":"o","b":"原题库补充 #328"},{"q":"中暑","a":"中暑是指人在高温和热辐射的长期作用下，机体体温调节中枢出现功能障碍，汗腺功能 衰竭，以水、电解质代谢紊乱及神经系统功能损害为特征的一种疾病","c":"o","b":"原题库补充 #329"},{"q":"大气环境污染","a":"当大气环境的污染物达到一定浓度并持续一定时间时，破坏了大气正常组成和生态的平 衡，对人体、动植物、物品材料以及工农业生产等产生不利影响和危害，称为大气环境污染","c":"o","b":"原题库补充 #331"},{"q":"非同步综合征","a":"由外界环境急性变动而引起的机体暂时性生物节奏失调，表现为暂时性疲劳、失眠、胃 肠道障碍、性功能障碍、精神及运动能力下降等各种身心功能障碍，称为非同步综合症，亦 称之为时差病。","c":"o","b":"原题库补充 #332"},{"q":"脱水","a":"脱水是指体液丢失量达到体重的1%以上。人体在运动训练过程中，由于气温、运动强 度、运动持续时间等因素的影响，可能产生程度不同的水分丢失，称为被动脱水","c":"o","b":"原题库补充 #404"},{"q":"体温","a":"特指机体深部的平均温度。","c":"o","b":"原题库补充 #406"}]},{"t":"第十七章 健身锻炼的生理学基础","items":[{"q":"健身锻炼","a":"健身锻炼是指通过身体活动促进机体健康水平提高的一种行为，是运用科学的方式和方法进行的，以发达肌肉、增强体质、改善形体、防治疾病和陶冶情操为目的的运动。","c":"4","b":"第四版"},{"q":"应激","a":"应激是指当机体受到各种内外环境因素刺激时所表现出来的非特异性全身反应。","c":"4","b":"第四版"},{"q":"运动应激","a":"运动应激是指由运动引起的机体的非特异性全身反应。","c":"4","b":"第四版"},{"q":"运动性应激综合征","a":"运动性应激综合征是指一次运动的负荷超过运动参与者的最大承受能力时所引发的一系列生理功能紊乱或病理过程。","c":"4","b":"第四版"},{"q":"应激反应","a":"应激反应是指所有对机体导致损耗的非特异性生理、心理反应的总和。","c":"4","b":"第四版"},{"q":"快速应答型","a":"快速应答型是指在运动开始后的几分钟内激素就会出现相应的应答性升高，并在很短时间内达到峰值，这些激素出现变化的反应快，运动负荷强度对其影响相对较大。","c":"4","b":"第四版"},{"q":"缓慢应答型","a":"缓慢应答型是指运动开始后激素才会出现一定的变化，但变化相对较为缓慢，持续时间长，激素水平随运动时间的延长而逐步升高，甚至可以持续到运动结束后。","c":"4","b":"第四版"},{"q":"滞后应答型","a":"滞后应答型是指运动开始阶段，激素并不立即出现明显变化，似乎存在一个停滞反应阶段，运动持续十几分钟甚至几十分钟后激素才会缓慢出现变化，如生长激素、胰高血糖素和胰岛素等。","c":"4","b":"第四版"},{"q":"适应","a":"适应是指当机体在持续受到恒量的刺激时，其反应强度随时间的延长而减弱的现象，表现为机体的形态结构、生理功能或行为习性随外界环境做出相应的改变。","c":"4","b":"第四版"},{"q":"运动适应","a":"机体受到长期运动刺激后，通过调节机制可诱导多种生理适应过程，最终导致机体形态结构和生理机能上的适应性变化，这种变化称为运动适应。","c":"4","b":"第四版"},{"q":"“去补偿”现象","a":"运动过程中的激素水平会发生一定程度的“去补偿”现象，表现为最初完成某种负荷运动时，激素反应幅度相对变化较大，随着不断重复该负荷刺激，激素的反应幅度逐渐变小，表明这些激素对该运动负荷的反应幅度更加精确，不同激素水平变化之间的相互关系更加协调，出现节省化现象。","c":"4","b":"第四版"},{"q":"运动性免疫抑制","a":"若运动强度过高、运动量过大、运动频度过高，则上述指标可能发生负性变化，免疫功能反而会降低，即发生运动性免疫抑制现象。","c":"4","b":"第四版"},{"q":"健身锻炼的生理监控","a":"健身锻炼的生理监控是指运用医学、生理学和卫生学的手段和方法，对从事健身锻炼者进行健康和身体机能监控，使各种安全、卫生措施得以实施，督导和协助运动者进行科学的锻炼，预防运动伤害的发生，使运动过程更符合人体生理机能的变化规律。","c":"4","b":"第四版"},{"q":"运动风险","a":"人们从事健身锻炼时可能会产生一定的运动风险，如关节扭伤、肌肉韧带拉伤、心血管事件及热损伤等，从而对锻炼者身心健康造成不利的影响。","c":"4","b":"第四版"},{"q":"运动风险筛查","a":"运动风险筛查是指在人体开始健身锻炼计划或改变运动方案前对锻炼者的健康状况、体力活动水平、带来不利运动后果的内外因素进行筛查，并按风险评价指标体系进行分类评价的过程。","c":"4","b":"第四版"},{"q":"运动能力","a":"运动能力是指人体从事运动所具备的能力。","c":"4","b":"第四版"},{"q":"节律性变化/生物节律","a":"生物体内的各种功能活动经常是发生变化的，如果这种变化以一定时间重复出现，周而复始，则称为节律性变化，而这种变化的节律则称为生物节律。","c":"4","b":"第四版"},{"q":"身体成分","a":"身体成分是指人体内各种组成成分的含量，可反映身体的构成和比例，对于评估健康状况、运动能力、营养状况等具有重要的生理学意义。","c":"4","b":"第四版"},{"q":"体重","a":"组成人体的各种成分的重量总和称为体重。体重是反映人体充实程度的整体指标，可以间接地反映人体营养状况。","c":"4","b":"第四版"},{"q":"体质指数","a":"体质指数（BMI）是指体重（kg）/身高²（m²），BMI 也称为身体质量指数或体重指数。","c":"4","b":"第四版"},{"q":"肥胖","a":"肥胖是一种常见的、明显的、复杂的代谢失调症，可影响整个机体正常生理功能，会引发一系列健康问题。","c":"4","b":"第四版"},{"q":"运动处方","a":"运动处方是由运动处方师、运动健康指导师、康复医师、康复治疗师、社会体育指导员 和临床医生等专业人员依据参加体育活动者的年龄、性别、个人健康信息、医学检查、体育 活动的经历及心肺耐力等健康体适能测试结果，并根据健身目的，用处方的形式制订的系统 化、个性化的体育活动指导方案","c":"o","b":"原题库补充 #324"},{"q":"基础心率","a":"基础心率是清晨起床前空腹卧位心率，基础心率一般较为稳定。基础心率随着训练年限 的延长和训练水平的提高而减慢，基础心率突然加快或者减慢往往提示有过度疲劳或疾病的 存在","c":"o","b":"原题库补充 #325"},{"q":"运动经济性","a":"代表在固定负荷做功中，血乳酸浓度达到平稳状态，即达到稳态乳酸浓度的上限。","c":"o","b":"原题库补充 #467"},{"q":"代谢综合征","a":"是指机体的蛋白质、脂肪、碳水化合物等物质发生代谢紊乱，在临床上出现一系列综合 征，其特征是一组以非传染性且疾病进程缓慢，以中心性肥胖、高血糖、血脂紊乱和高血压 及心脑血管疾病等为主要表现的临床综合征，属于慢性非传染性疾病的重要临床表现","c":"o","b":"原题库补充 #468"},{"q":"糖代谢异常","a":"糖代谢异常是指与正常血糖浓度(空腹：3.9~6.1mmol/L,餐后2h:3.9~7.8mmol/L)比较，由 遗传、环境或疾病等因素作用，机体胰岛素或相关激素/酶的结构、功能及浓度异常导致的 血糖浓度调控紊乱","c":"o","b":"原题库补充 #469"},{"q":"超重与肥胖","a":"肥胖是可能导致健康损害的异常或过多的脂肪堆积，而超重是一种由正常体重向肥胖发 展的中间状态。","c":"o","b":"原题库补充 #470"},{"q":"体适能","a":"是指人们除了足以胜任日常工作外，还能够从事休闲活动、应对压力和突发状况的身体 适应能力，是从体育学角度评价健康的一个综合指标。根据体适能与健康水平、竞技水平的 关系可分为健康体适能和竞技体适能两类","c":"o","b":"原题库补充 #474"}]}]},{"s":"学校体育学","chapters":[{"t":"第一章 学校体育的发展与思想演变","items":[{"q":"学校体育学","a":"是研究与揭示学校体育工作基本规律，阐明学校体育工作基本原理与方法的一门学科， 是体育教育专业的核心课程之一","c":"s","b":""},{"q":"维多利诺","a":"是意大利教育领域具有代表性的人文主义者，被视为“第二位现代体育教师”。提出教 育的目的是使受教育者的身体、精神和道德得到发展，以培养注重个性、有责任感并能为社 会服务的公民","c":"s","b":""},{"q":"夸美纽斯","a":"捷克教育学家，被称为“学校体育之父”，他的主要功绩在于推动了学校体育从“活动” 向“课程”的转变，并使学校冲破了贵族阶级的禁锢，走向大众。夸美纽斯十分强调儿童的 身体健康，倡导身心和谐发展。他认为教育必须顺应自然","c":"s","b":""},{"q":"卢梭","a":"法国著名的启蒙思想家和教育家，自然主义教育学派的代表性任务，他提出了一切顺应 自然、归于自然的教育理论，认为教育的目的是培养“自然人”，其思想主要体现于《爱弥 儿》一书中。 5.斯宾塞；p23 英国著名的哲学家、社会学家，近代自然科学教育运动的倡导者，他提倡科学教育，强 调德育、智育和体育的全面发展，其著作《教育论：智育、德育和体育》对当时和后来的世 界教育改革产生了深远影响，对现代科学教育的发展起到了重要的促进作用","c":"s","b":""},{"q":"巴泽多","a":"德国教育学家，是博爱主义教育学派的创始人。强调教育的目的是培养健康、幸福、对 社会有用的人。并创造了著名的“德绍五项”体操，即跑步、跳高、攀登、平衡和负重","c":"s","b":""},{"q":"古茨穆茨","a":"被尊称为“近代体育之父”。他认为体操的主要功能是满足身体需要和使身体完美，并 将以身体形成为目的的体操活动分为三类：基本运动、手工劳动和青少年游戏。为德国、瑞 典、丹麦等国家的体操体系奠定了基础，使学校体育彻底改变了贵族的性质","c":"s","b":""},{"q":"《奏定学堂章程》","a":"1904 年，清政府颁布并实施了《奏定学堂章程》，这是我国近代第一个以教育法令公布 并在全国实行的学制。规定各级各类学校均开设“体操科”，小学每周3 小时，中学2 小时， 师范学堂2 小时","c":"s","b":""},{"q":"壬戌学制","a":"1922 年11 月教育部颁布《学校系统改革令》即实行壬戌学制，宣布废除军国民主义教 育。随后各级各类学校正式将“体操科”改名为“体育科”，剔除了“兵操”。增加了田径、 球类、游戏等近代体育项目，同时还将卫生保健知识纳入了体育教学的范围","c":"s","b":""},{"q":"体质教育思想","a":"主张体育是发展身体、建设身体、完善身体的教育，是增强体质的教育","c":"s","b":""},{"q":"终身体育思想","a":"认为学校体育是其最重要、具有决定性意义的中间环节，主张培养学生终身从事体育学 习和锻炼的观念、能力和习惯。从而使体育伴随人的一生","c":"s","b":""},{"q":"健康第一思想","a":"是强调身体、心理与社会适应在内的三维健康观，体育在培养全面发展的人的方面具有 其他学科不可替代的作用，因此学校体育应树立“健康第一”指导思想","c":"s","b":""},{"q":"扬州会议","a":"1979 年5 月,由教育部、国家体委、卫生部、共青团中央联合召开的“全国学校体育卫 生工作经验交流会”在我国学校体育发展史上具有“里程碑”意义,史称“扬州会议”,极大 地提高了学校体育的地位。","c":"s","b":""}]},{"t":"第二章 学校体育的结构、功能与使命","items":[{"q":"学校体育","a":"使指以在校学生为参与主体的体育活动，通过培养学生的体育兴趣、态度、习惯、知识 和能力来增强学生的身体素质，培养学生的道德和意志品质，促进学生的身心健康","c":"s","b":""},{"q":"学校体育的结构","a":"是学校体育系统各组成要素之间相对稳定的联系方式、组织秩序及其时空关系的内在表 现形式","c":"s","b":""},{"q":"体育与健康课程","a":"是学校教学计划中规定的必修课程，是学校体育的基本组织形式，是实现学校体育目标 的重要途径，承担着对学生进行体育文化知识教育、运动技能教育和心理社会健康教育等重 任","c":"s","b":""},{"q":"课外体育活动","a":"课外体育活动是指学生在课余时间里，运用各种身体练习或手段，以发展身体、增进健 康、提升素养、丰富业余文化生活和提高运动技术水平为目的而进行的多种形式及内容的体 育教育活动","c":"s","b":""},{"q":"学校课余体育训练","a":"是指遵循我国教育与运动训练本身的规律,对具有体育天赋以及运动特长的学生,进行有 组织、有计划、有目标的学校课余体育训练活动,从而实现发展和提高个人运动才能的教育 过程","c":"s","b":""},{"q":"学校课余体育竞赛","a":"是指利用学生的课余时间组织学生以运动项目、游戏活动、身体素质练习为内容，根据 正规的、简化的或自定的规则进行个人或集体的体力、技艺、智力和心理的比赛","c":"s","b":""},{"q":"运动能力","a":"是体能、技战术和心理能力等在身体练习中的综合表现，是人类身体活动的基础","c":"s","b":""},{"q":"健康行为","a":"是增进身心健康和积极适应外部环境的综合表现，是提高健康意识、改善健康状况并逐 渐形成健康文明生活方式的关键","c":"s","b":""},{"q":"体育品德","a":"是指体育运动中应当遵循的行为规范，以及形成的价值追求和精神风貌，包括体育精神、 体育道德和体育品格三个方面","c":"s","b":""},{"q":"学校体育的目标","a":"是教育目的纵向层次和横向内容结构体系的交集，是学校教育对学生身心健康作出的规 定，是教育目的在学校体育中的具体体现","c":"s","b":""},{"q":"全面发展","a":"即人的全面发展，指人的体力和智力的充分发展，又指人在德智体美劳各方面的和谐发 展，它反对的是人的片面、畸形和异化的发展","c":"s","b":""},{"q":"体教融合","a":"“体教融合”是新时代背景下贯彻党的教育方针,全面推进素质教育,强化学校教育、卫 生和健康教育融合的一项新的重要举措,是整合体育、教育等资源而实施的人才培养战略,体 现了体育、教育事业最根本的培养目标,符合人才培养的内在要求。","c":"s","b":""}]},{"t":"第三章 体育与健康课程编制","items":[{"q":"体育与健康课程编制","a":"是指完成一项体育与健康课程方案或计划的整个过程，可以分为国家、地方、学校三个 层面。包括确定体育与健康课程目标、选择和组织体育与健康课程内容、体育与健康课程实 施，体育与健康课程评价4 个方面","c":"s","b":""},{"q":"运动技能正迁移","a":"是指已经掌握的运动技能对新技能的形成会产生积极影响，能促进新技能的形成和发展","c":"s","b":""},{"q":"运动技能负迁移","a":"是指已经掌握的运动技能对新技能的形成会产生消极的影响，会阻碍新技能的形成和发 展","c":"s","b":""},{"q":"社会文化","a":"是指人类在社会历史实践过程中所创造的物质财富和精神财富的综合，它是人类在对自 然进行开发的过程中所取得的成果","c":"s","b":""},{"q":"个体社会化论","a":"人的社会化是指个体在社会实践中学习知识、技能和规范等社会文化，适应社会生活， 积极作用于社会，创造新的社会文化的过程","c":"s","b":""},{"q":"体育与健康课程目标","a":"是指学生通过体育学习与活动所要达到的预期学习效果，体育与健康课程目标的首要作 用是为体育与健康课程编制提供依据和参考，其次是为体育教师的教和学生的学提供指导","c":"s","b":""},{"q":"体育与健康课程内容","a":"是指体育学科中特定的事实、观点、原理和问题以及处理它们的方式。选择和组织体育 与健康课程内容是体育与健康课程编制过程中的一个基本环节，是实现体育与健康课程价值 的支柱","c":"s","b":""},{"q":"体育与健康课程实施","a":"是指把新的体育与健康课程方案或计划付诸实践的过程，它是达到预期的课程目标的基 本途径","c":"s","b":""},{"q":"体育学科发展逻辑","a":"是指体育学科知识本身系统的、内在的联系，主要涉及体育学科纵向组织与横向组织两个 方面","c":"s","b":""},{"q":"学生心理发展逻辑","a":"是指按照学生心理发展的先后顺序组织课程编制的逻辑。学生的认知结构水平是一个由 幼稚到成熟的过程，学生的学习能力也是一个由浅人深、从简单到复杂的过程","c":"s","b":""},{"q":"体育教学逻辑","a":"是指根据教学基本规律来编制课程的一种逻辑，具体涉及教授的逻辑、学习的逻辑、知 识与技能逻辑、认知逻辑和关系逻辑等","c":"s","b":""},{"q":"连续性原则","a":"连续性是指把选出的各种课程内容要素直线式地加以叙述，使学习者在不同学习阶段不 断地予以“重提”,学习者能够有机会反复地、连续地学习、练习与复习，避免遗忘","c":"s","b":""},{"q":"顺序性原则","a":"顺序性是指每一后续学习的课程内容应建立在前面学习内容的基础上。对课程内容要素 要进行从已知到未知、从具体到抽象、从简单到复杂的处理，要对有关内容加以深入、广泛 开展，从而使学生能够在更高层次理解后续内容","c":"s","b":""},{"q":"整合性原则","a":"整合性是指在课程内容各要素之间的横向联系和组织，寻求要素之间的内在联系，形成 适当的关联，逐渐获得一种统一的观点，把各种要素整合为一个有机整体，从而克服由于分 科所造成的课程内容支离破碎的状态，以增强学习的价值、应用性和效率。 15.忠实取向；p98 是指忠实地执行课程方案的过程。衡量课程实施成功与否的基本标准即是课程实施过程 对预定的课程方案的实现程度","c":"s","b":""},{"q":"相互适应取向","a":"认为课程实施过程是课程与班级或学校实践情境在课程目标、内容、方法、组织模式诸 方面相互调整、改变与适应的过程","c":"s","b":""},{"q":"创生取向","a":"认为真正的课程是教师与学生联合创造的教育经验，课程实施本质上是在具体教育情境 中创生新的教育经验的过程，既有的方案只是这个经验创生过程选择的工具而已。","c":"s","b":""}]},{"t":"第四章 体育教学","items":[{"q":"体育教学","a":"是指在体育教师和学生的共同参与下，通过有效的教学方法与手段，指导学生掌握体育 与健康的知识、技能和方法，培育学生体育与健康学科核心素养和增进学生身心健康、全面 发展的一种有目的、有计划、有组织的教育过程","c":"s","b":""},{"q":"体育教学目标","a":"是指在一定的时间范围内教学所要达到的预期结果，既是体育教学的出发点，也是体育 教学的归宿，是教育目的、培养目标和课程目标的具体体现","c":"s","b":""},{"q":"体育教学内容","a":"是指在体育教学目标的指导下，在体育教学过程中选择的各种体育与健康的知识、技术、 技能及方法的总称","c":"s","b":""},{"q":"体育教学方法","a":"是师生在实现体育教学目标过程中的路径操作程序","c":"s","b":""},{"q":"体育教学手段","a":"是实现体育教学目标过程中所使用的实体工具，是帮助体育教师完成教学任务，达成教 学目标的基本要素","c":"s","b":""},{"q":"体育教学环境","a":"在教学活动中，影响教师教和学生学的一切内外部条件共同构成一定的教学环境。从主 体构成看，它包括教师教的环境和学生学的环境；从内容构成看，它包括教学物理环境、教 学信息环境和教学心理环境","c":"s","b":""},{"q":"体育教学评价","a":"是以体育与健康课程的学习目标为依据，按照一定的评价标准和方式，对学生的体育学 习过程、学习效果，对教师的教学行为所做的一种价值评判","c":"s","b":""},{"q":"教学主体的管理","a":"是指在教学过程中教师对自我站位的选择和对学生学习行为的管理，主要包括教师的站 位艺术和学生学习行为的管理技巧两个方面","c":"s","b":""},{"q":"体育教学的基本规范","a":"主要指体育教学过程中为教师与学生确立的行为标准，是日常体育课中教师和学生都要 共同遵守的“行为规范”，是体育教学工作顺利开展的基本要求，也被称为体育教学常规， 一般包括课前教学常规、课中教学常规、课后教学常规","c":"s","b":""},{"q":"教学","a":"是教者有目的、有计划、有组织地向学习者传授知识、技能,指导学习者进行学习,进而 使学习者获得某方面知识、技能、能力发展的教育活动。 11.同质分组；p121 同质分组是指按照体能或运动技能水平将一个班级中的学生分成若干小组，然后按照 水平高低设置不同的教学目标，安排不同的教学内容，亦或设计不同的教学策略等进行教学 的组织形式","c":"s","b":""},{"q":"异质分组","a":"异质分组是指有意识地扩大组内差异，将不同体能和运动技能水平的学生分在同一小 组，小组间基本同质，实现小组内学生互帮互学的组织形 态","c":"s","b":""},{"q":"友情分组","a":"友情分组是学生自主选择练习伙伴的情况，大多数学生会选择与自己关系较为密切的 同学一起进行练习","c":"s","b":""},{"q":"个别教学","a":"是历史上最早出现的教学组织形式，是把不同年龄、不同基础的学生组织到一起，教 师分别对每一个人进行教学的一种组织形式。","c":"s","b":""}]},{"t":"第五章 课外体育活动","items":[{"q":"个人体育锻炼","a":"是学生在课余时间和节假日,根据自身的兴趣爱好,依据体育锻炼的方法要求,自发进行 的各种体育活动","c":"s","b":""},{"q":"家庭体育","a":"是以家庭为单位,由学生与家庭成员一起进行的身体练习或各种体育活动。家庭体育有 利于加深亲子感情,创造和谐的家庭氛围,丰富家庭生活","c":"s","b":""},{"q":"社区体育","a":"是指在所在地的青少年文化宫、青少年活动中心、体育场(馆)等场所组织的体育活动","c":"s","b":""},{"q":"全校性活动计划","a":"全校性活动计划一般由体育教研室(或组),根据有关精神,结合本校实际条件,在广泛征求 有关部门意见的基础上研究制订,并经过学校主管领导研究批准后执行","c":"s","b":""},{"q":"班级活动计划","a":"是根据全校性活动和年级计划要求,结合班级的实际情况制订的。其内容主要包括班级 体育锻炼目标和要求、锻炼小组的组成、锻炼对间、锻炼内容、基本安排、检查评比办法等","c":"s","b":""},{"q":"体育俱乐部活动计划","a":"体育俱乐部活动计划一般由体育俱乐部专门责任人制订,根据学校体育工作计划和课外 体育活动计划确立体育俱乐部的目标、任务、开设项目、活动时间、人员安排、经费预算与 筹措、参加要求、场地器材设施的合理配置等","c":"s","b":""},{"q":"个人体育锻炼计划","a":"是根据班级活动计划并结合个人实际情况,在征求老师、同学和家长意见的基础上,对个 人每次或每周参加的锻炼所做的具体安排。其主要内容有锻炼目标、内容、方法、时间以及 自我评价要求和标准等。","c":"s","b":""}]},{"t":"第六章 学校课余体育训练与竞赛","items":[{"q":"年度训练计划","a":"是将多年训练计划中的目标和要求,根据学年教学周期安排、比赛任务的安排及季节特 点落实到每个年度的训练计划,其内容比多年训练计划更加具体充实","c":"s","b":""},{"q":"阶段训练计划","a":"是根据年度训练计划所规定的各阶段任务、内容、要求和训练次数等制订的","c":"s","b":""},{"q":"周训练计划","a":"是根据阶段训练计划,并结合学校课余体育训练实际制订的一个星期的训练安排","c":"s","b":""},{"q":"课时训练计划","a":"是最基础的训练计划,它是根据周训练计划以及体育训练实际情况,包括学生运动员身心 状态、具体训练要求、气候等,对一次训练课所做出的具体安排","c":"s","b":""},{"q":"体能训练","a":"是指在学校课余体育训练过程中运用各种有效手段和方法,增进学生运动员的身体健康, 改善其体形,全面发展其体能素质和运动能力,为其掌握运动技术战术,创造优异运动成绩打 好基础的训练过程","c":"s","b":""},{"q":"技术训练","a":"是指学习、掌握和提高运动技术的训练过程。技术是提高运动成绩的重要因素,只有掌 握先进技术,才能充分发展学生运动员的身体能力,使其创造优异的运动成绩","c":"s","b":""},{"q":"战术","a":"是在比赛中为战胜对手或为表现出理想的竞技水平而采取的计谋和行动,是运动员(队) 竞技能力整体水平的重要构成部分","c":"s","b":""},{"q":"心理训练","a":"是指在运动训练中,有意识地对运动员的心理过程和个性特征施加影响,使他们学会在训 练和比赛中调节自己心理状态的训练过程","c":"s","b":""},{"q":"校内竞赛","a":"是指学校主办的为了激励学生积极参加体育活动、展示学校体育工作成果、提高运动技 术水平、培养体育后备人才而开展的学生体育比赛","c":"s","b":""},{"q":"运动会","a":"是指学校组织的由多个运动项目组成并集中于某一时段进行的比赛","c":"s","b":""},{"q":"友谊赛","a":"是指班级或小组之间为增进友谊、加强交流、切磋技术而自发组织的体育比赛","c":"s","b":""},{"q":"选拔赛","a":"是指学校为了组建代表队、选拔优秀运动员代表学校参加校外体育比赛而组织的比赛","c":"s","b":""},{"q":"表演赛","a":"是指学校为扩大体育运动的影响,推广运动项目和促进经验交流及满足学生体育欣赏需 要而进行的比赛","c":"s","b":""},{"q":"周期赛","a":"是在一定时间跨度内组织的群众性课余体育活动的比赛","c":"s","b":""},{"q":"校外竞赛","a":"是指学校学生参加的非本校主办的体育竞赛","c":"s","b":""},{"q":"淘汰法","a":"是指在竞赛过程中逐步淘汰成绩差的,最后决出优胜者的一种方法","c":"s","b":""},{"q":"循环法","a":"是指在比赛过程中,参赛者都要按照一定的次序相互轮流进行一次比赛,最后综合全部比 赛的胜负来决定名次的一种比赛方法,较多地用于集体项目的球类比赛和其他对抗性项目的 比赛","c":"s","b":""},{"q":"单循环","a":"是指所有参赛者之间要轮流相遇一次,最后根据各队胜负场次的积分来决定名次","c":"s","b":""},{"q":"分组循环","a":"是将参赛者分成若干个平行小组,在组内先进行单循环比赛,排出各小组名次,然后再按 名次重新分组","c":"s","b":""},{"q":"双循环","a":"是指参赛者先后进行两次单循环的比赛方法","c":"s","b":""},{"q":"顺序法","a":"是指参赛者按一定的顺序表现成绩的比赛方法","c":"s","b":""},{"q":"轮换法","a":"是指在同一比赛时间内,参赛者按规定的轮换顺序依次进行不同项目的比赛,最后综合各 项目的成绩来决定名次的一种比赛方法。","c":"s","b":""}]},{"t":"第七章 学校体育文化建设","items":[{"q":"学校体育文化","a":"是反映学校体育这一文化现象的本质属性和思维方式，它是广大师生在学校体育文化建 设过程中实践经验的总结。随着人类社会的发展变化，学校体育文化也在不断变化","c":"s","b":""},{"q":"体育文化","a":"是人们在有目的地增强体质、增进健康，改善生活方式，提高生活质量的过程中所创造 的一切物质和精神财富","c":"s","b":""},{"q":"文化","a":"文化有广义和狭义之分，广义文化是指人类在社会历史发展过程中所创造的物质财富 和精神财富的总和。狭义文化是指社会的意识形态以及与之相适应的制度和组织机构","c":"s","b":""},{"q":"学校体育精神文化","a":"是全校师生员工在长期的体育实践活动中所形成的理念、精神和价值追求，是广大师生 达成共识并遵循的体育价值观和信念","c":"s","b":""},{"q":"学校体育制度文化","a":"是全校师生员工在长期的体育教育实践活动过程中形成的一种规范性文化，它既包括师 生共同遵守、按照一定程序办事的体育规章制度，也包括学校体育在长期发展过程中所形成 的体育传统与风气","c":"s","b":""},{"q":"学校体育行为文化","a":"是全校师生员工在体育教育实践活动中所表现出的精神状态、行为操守和文化品位。它 是一所学校的体育理念、体育精神和体育价值追求在体育课程、体育教学、校园体育活动中 的动态体现","c":"s","b":""},{"q":"学校体育物质文化","a":"是全校师生员工在体育教育实践活动过程中所创造的各种物质设施和条件，但并不泛指 学校范围内的一切物质资料，而是指能够记载学校的发展历程，体现学校的精神和品位，阐 述学校的教育理念、审美情趣和价值追求，传播先进体育文化以及彰显学校文化特色的体育 物质设施。 第八章学校体育管理 名词解释 1.学校体育管理体制；p218 是指学校体育管理机构的设置、管理权限划分和运行机制等方面的体系和制度的总称， 是实现学校体育目标的组织保证，受国家政治、经济体制的制约","c":"s","b":""}]},{"t":"第八章 学校体育管理","items":[{"q":"学校体育设施","a":"学校体育设施是指开展学校体育工作过程中所使用的体育场地和相适应的器材设备","c":"s","b":""},{"q":"学校体育风险管理","a":"学校体育风险管理是对学校体育运动风险的致因进行考察、预测和分析的基础上制定出 有效、妥善处理风险等一整套系统而科学的管理方法","c":"s","b":""},{"q":"法规制度管理法","a":"是指根据国家或地方有关学校体育的各种法令、条例、规章制度等来规范学校体育工作 的方法","c":"s","b":""},{"q":"行政管理法","a":"是指行政管理部门运用行政职能与手段，对各级各类学校体育实施管理的一种方法","c":"s","b":""},{"q":"目标管理法","a":"是根据学校体育工作有关规定、制度及计划，科学制订一定时期的学校体育工作目标， 并通过督促、检查，目标实施情况的一种方法","c":"s","b":""},{"q":"过程管理法","a":"是对学校体育工作的计划、实施、检查和改进进行全过程的有效控制和管理的方法。 8.体育教学计划； 是体育教师进行教学的主要依据,也是检查、评估教学质量的重要内容","c":"s","b":""},{"q":"体育教学质量评估","a":"是指根据一定的质量标准,测评和判定体育教学质量状况及其优劣程度","c":"s","b":""},{"q":"学习体育管理办法","a":"是指为达到学校体育管理目标而采用的方式、手段或途径的总称","c":"s","b":""},{"q":"风险识别","a":"是指通过对大量来源可靠的信息资料进行系统了解和分析,认清项目存在的各种风险因 素,进而确定项目所面临的风险及其性质,并把握其发展趋势","c":"s","b":""},{"q":"风险评估","a":"是指在风险识别的基础上,通过对收集的大量详细资料加以分析,运用概率论和数理统计, 估计和预测风险发生的概率(频率)和损失程度,为选择恰当的风险应对方法与进行正确的风 险管理决策提供依据","c":"s","b":""},{"q":"风险控制手段","a":"是损失形成前防范和减轻风险损失的技术性措施,它通过避免、消除和减少风险事件发 生的概率以及限制已发生的损失继续扩大,达到减少损失概率、降低损失程度、使风险损失 最小化的目的。","c":"s","b":""}]},{"t":"第九章 学校体育运动伤害防范","items":[{"q":"学校体育运动伤害事故","a":"是由教育行政部门或学校组织开展的体育教学、课外体育活动、课余体育训练、体育比 赛，以及学生在学校负有责任的体育场地、器材设施内自主开展体育活动时发生的造成人员 身体损伤的事故。","c":"s","b":""}]},{"t":"第十章 学校体育工作督导评估","items":[{"q":"学校体育工作督导评估","a":"主要是对学校体育工作进行视察、评估、监督和指导，以促进学校体育工作不断改进的 发展的过程","c":"s","b":""}]},{"t":"第十一章 学校体育政策法规","items":[{"q":"阳光体育运动","a":"是指由教育部、国家体育总局和共青团中央共同决定,自2007 年开始结合学生体质健康标准 全面实施,并在全国各级各类学校中广泛、深入地开展“全国亿万学生阳光体育运动”的简 称。","c":"s","b":""}]},{"t":"第十二章 体育教师","items":[{"q":"体育教师的专业发展","a":"体育教师在专业学习、专业知识以及专业精神等方面不断丰富和发展的过程,是体育教 师由不成熟逐步走向成熟的自我发展过程,也是体育教师职业能力不断提升的过程","c":"s","b":""},{"q":"体育教师的专业化","a":"是指教师职业专门化的过程。教师专业化是指教师职业成为专门职业,并获得应有的专 业地位的过程,所关注的问题包括专业的发展历史、专业资格审定、专业组织、专业守则等","c":"s","b":""},{"q":"教师专业发展","a":"是指教师个体的专业不断发展的过程,是教师不断接受新知识、提高专业能力的过程","c":"s","b":""},{"q":"学历教育","a":"主要是指以学历提升为主要目的,通过脱产或全日制等多种形式进行的一种教育形式。 补充：","c":"s","b":""}]}]}];
